local config = {
  ui_story_5043_50430101_1_dialog_content = "<color=#e8d9bb>O Hall of Justice, Lumopolis Gardens</color>",
  ui_story_5043_50430101_2_dialog_content = "Meritíssimo, esse não é o caso!",
  ui_story_5043_50430101_3_dialog_content = "Juro pelo Deus da Luz, não menti para ela em assuntos do coração.",
  ui_story_5043_50430101_4_dialog_content = "<color=#e8d9bb>Tum!</color>",
  ui_story_5043_50430101_5_dialog_content = "Ordem no tribunal! O réu se absterá de interromper o autor.",
  ui_story_5043_50430101_6_dialog_content = "Por favor, continue, juiz Leyn.",
  ui_story_5043_50430101_7_dialog_content = "Senhorita, você acabou de declarar que o queixoso não cumpriu seus deveres como seu noivo durante o período de seu noivado. Isso é correto?",
  ui_story_5043_50430101_8_dialog_content = "Isso é!",
  ui_story_5043_50430101_9_dialog_content = "Você pode fazer uma declaração final antes que o tribunal comece suas deliberações.",
  ui_story_5043_50430101_10_dialog_content = "O Mooncrown Day do mês passado foi o aniversário de sete meses do nosso noivado.",
  ui_story_5043_50430101_11_dialog_content = "Mas aquele imprestável nem se importava!",
  ui_story_5043_50430101_12_dialog_content = "Oh, por favor. Você não pode esperar que eu celebre nosso noivado todo mês!",
  ui_story_5043_50430101_13_dialog_content = "Eu poderia não ter objetado. Mas você conseguiu comprar presentes diferentes para várias outras pessoas!",
  ui_story_5043_50430101_14_dialog_content = "Espere um minuto. Eu já expliquei, aqueles eram para conexões de negócios da minha família—",
  ui_story_5043_50430101_15_dialog_content = "H-Espere! Não comece a discutir, agora...",
  ui_story_5043_50430101_16_dialog_content = "<size=30>Tina, você é um juiz agora. Aja como um!</size>",
  ui_story_5043_50430101_17_dialog_content = "<size=30>Ah sim, isso mesmo! Eu sou. Ok, observe isso. Aham...</size>",
  ui_story_5043_50430101_18_dialog_content = "<size=45>Ordem, ordem!</size>",
  ui_story_5043_50430101_19_dialog_content = "<color=#e8d9bb>*multidão murmurando*</color>",
  ui_story_5043_50430101_20_dialog_content = "(O que eu quero saber é por que estou aqui sentado ouvindo uma briga de namorados...)",
  ui_story_5043_50430101_21_dialog_content = "Ficando impaciente, PlayerName? Você está começando a parecer entediado.",
  ui_story_5043_50430101_22_dialog_content = "O que, eu? De jeito nenhum... Oh, ok, você está certo como sempre, Carleen.",
  ui_story_5043_50430101_23_dialog_content = "Para ser sincero, sinto exatamente o mesmo.",
  ui_story_5043_50430101_24_dialog_content = "Mas ao contrário de você, não posso deixar transparecer. Afinal-",
  ui_story_5043_50430101_25_dialog_content = "Eu sei. Até certo ponto, isso refletiria mal no City Lord de lá.",
  ui_story_5043_50430101_26_dialog_content = "...",
  ui_story_5043_50430101_27_dialog_content = "Até agora, ele não disse nada.",
  ui_story_5043_50430101_28_dialog_content = "Desculpe. Inicialmente, eu pretendia que você viesse aos Jardins Lumopolis para fazer um relatório sobre suas aventuras em Longzhou.",
  ui_story_5043_50430101_29_dialog_content = "Mas parece que o City Lord não vai conseguir perder tempo.",
  ui_story_5043_50430101_30_dialog_content = "Não há problema. Não é como se eu tivesse algo urgente para fazer.",
  ui_story_5043_50430101_31_dialog_content = "<size=30>E para ser honesto, eu realmente não quero voltar para uma daquelas salas de conferências solenes...</size>",
  ui_story_5043_50430101_32_dialog_content = "Desculpe, o que?",
  ui_story_5043_50430101_33_dialog_content = "Nada!",
  ui_story_5043_50430101_34_dialog_content = "(Agora eu penso sobre isso, eu não estive aqui desde então <color=#FFB400>incidente</color>...)",
  ui_story_5043_50430101_35_dialog_content = "(Irridon estava sentada onde está agora, lendo o veredicto do Tribunal de Justiça sobre Carleen.)",
  ui_story_5043_50430101_36_dialog_content = "(E Carleen... bem, ela mudou muito desde então.)",
  ui_story_5043_50430101_37_dialog_content = "PlayerName, você está sonhando acordado?",
  ui_story_5043_50430101_38_dialog_content = "Uhm, bem... eu só estava pensando...",
  ui_story_5043_50430101_39_dialog_content = "Eu estava pensando sobre o efeito que o Mooncrown Day tem em Lumopolis!",
  ui_story_5043_50430101_40_dialog_content = "Sim, esse tipo de coisa é comum nessa época do ano.",
  ui_story_5043_50430101_41_dialog_content = "À medida que rapazes e moças desfrutam da atmosfera de Mooncrown, alguns iniciam novos romances e, às vezes, rachaduras se formam nos relacionamentos existentes.",
  ui_story_5043_50430101_42_dialog_content = "Depois, há os nobres decadentes que tendem a tentar pensar em maneiras de fazer o entretenimento durar o máximo possível.",
  ui_story_5043_50430101_43_dialog_content = "Como resultado, o Tribunal de Justiça acaba com uma pilha de disputas de relacionamento para resolver.",
  ui_story_5043_50430101_44_dialog_content = "O City Lord senta-se para ouvir com mais frequência do que o habitual, para evitar que possíveis situações inéditas ocorram ou saiam do controle.",
  ui_story_5043_50430101_45_dialog_content = "De qualquer forma, gosto mais de sentar aqui na audiência do que na cadeira do réu.",
  ui_story_5043_50430101_46_dialog_content = "Carleen...",
  ui_story_5043_50430101_47_dialog_content = "<color=#e8d9bb>Bate, baque, baque!</color>",
  ui_story_5043_50430101_48_dialog_content = "<size=45>Ordem!</size>",
  ui_story_5043_50430101_49_dialog_content = "Em suma, foi cruel e imperdoável!",
  ui_story_5043_50430101_50_dialog_content = "Portanto, solicito ao tribunal que encerre nosso noivado!",
  ui_story_5043_50430101_51_dialog_content = "Hehe. Caro queixoso, certamente compreendo de onde vem.",
  ui_story_5043_50430101_52_dialog_content = "Pelo que entendi, este foi um acordo de longa data entre suas famílias. E você e o réu foram namorados de infância.",
  ui_story_5043_50430101_53_dialog_content = "O que faz sentido. É difícil imaginar um homem como o réu conquistando o coração de uma bela dama como você sem tais vantagens.",
  ui_story_5043_50430101_54_dialog_content = "Você tem razão. Nós crescemos juntos, e é por isso que eu o conheço melhor do que ninguém.",
  ui_story_5043_50430101_55_dialog_content = "Que invejável. Ora, estou quase com ciúmes do réu.",
  ui_story_5043_50430101_56_dialog_content = "(O quê?! Este juiz é um pouco assustador!)",
  ui_story_5043_50430101_57_dialog_content = "J-Juiz Schwab...",
  ui_story_5043_50430101_58_dialog_content = "<color=#e8d9bb>Tum!</color>",
  ui_story_5043_50430101_59_dialog_content = "Juiz Schwab, por favor, mantenha seu profissionalismo.",
  ui_story_5043_50430101_60_dialog_content = "Afinal, nem eu nem o juiz principal temos conhecimento do caráter do réu.",
  ui_story_5043_50430101_61_dialog_content = "Tudo o que podemos afirmar é que você deve ter chegado a sua decisão depois de muita consideração com base no número de anos em que o conhece.",
  ui_story_5043_50430101_62_dialog_content = "É...?",
  ui_story_5043_50430101_63_dialog_content = "(Heh. Ela caiu nessa.)",
  ui_story_5043_50430101_64_dialog_content = "Ué, eu...",
  ui_story_5043_50430101_65_dialog_content = "Réu, tem algo a dizer perante o Juiz Chefe Irridon entrega o veredicto?",
  ui_story_5043_50430101_66_dialog_content = "<size=45>Meu querido! Você sempre foi o único para mim!</size>",
  ui_story_5043_50430101_67_dialog_content = "C-Como você pode dizer essas coisas aqui...",
  ui_story_5043_50430101_68_dialog_content = "Muito bem. E a seguir-",
  ui_story_5043_50430101_69_dialog_content = "<size=45>Espere!</size>",
  ui_story_5043_50430101_70_dialog_content = "Desculpe. Mas eu reconsiderei.",
  ui_story_5043_50430101_71_dialog_content = "eu desejo <color=#FFB400>retirar</color> o meu caso.",
  ui_story_5043_50430101_72_dialog_content = "(O que, assim?)",
  ui_story_5043_50430101_73_dialog_content = "Lamento profundamente. Eu falhei em considerar minhas ações completamente. Deveríamos ter resolvido nossos mal-entendidos nós mesmos.",
  ui_story_5043_50430101_74_dialog_content = "Não. A culpa é minha por não ser mais amoroso. Sou eu quem o prejudicou.",
  ui_story_5043_50430101_75_dialog_content = "Pedido negado. Os processos judiciais devem ser respeitados. Existem formalidades a serem seguidas tanto ao entrar com um caso quanto ao retirá-lo.",
  ui_story_5043_50430101_76_dialog_content = "Mas há uma maneira mais fácil de lidar com isso.",
  ui_story_5043_50430101_77_dialog_content = "Eu acho que o réu—",
  ui_story_5043_50430101_78_dialog_content = "<color=#e8d9bb>Tum!</color>",
  ui_story_5043_50430101_79_dialog_content = "-inocente!",
  ui_story_5043_50430101_80_dialog_content = "Querido!",
  ui_story_5043_50430101_81_dialog_content = "Doçura! Venha, vamos tomar um chá da tarde...",
  ui_story_5043_50430101_82_dialog_content = "Caso encerrado. O tribunal está suspenso.",
  ui_story_5043_50430101_83_dialog_content = "Senhor Schwab, por favor, espere!",
  ui_story_5043_50430101_84_dialog_content = "Parabéns pela audiência bem-sucedida, Lord Schwab! Por favor, pegue essas flores!",
  ui_story_5043_50430101_85_dialog_content = "A-E eu também tenho um pouco de chocolate branco para você. Aqui...",
  ui_story_5043_50430101_86_dialog_content = "(Argh...)",
  ui_story_5043_50430101_87_dialog_content = "Um de cada vez, meus lindos. Forme uma fila ordenada...",
  ui_story_5043_50430101_88_dialog_content = "<color=#e8d9bb>Lumopolis Gardens, Gabinete do Juiz Chefe</color>",
  ui_story_5043_50430101_89_dialog_content = "O objetivo de ter regras é nos permitir ver rapidamente onde o caos ainda reina.",
  ui_story_5043_50430101_90_dialog_content = "Há quanto tempo esses casos ridículos de relacionamento aparecem no tribunal?",
  ui_story_5043_50430101_91_dialog_content = "City Lord, senhor, apenas no último mês.",
  ui_story_5043_50430101_92_dialog_content = "Eu vejo. Ah, ser jovem novamente...",
  ui_story_5043_50430101_93_dialog_content = "Mas o Tribunal de Justiça é um lugar sagrado e sério.",
  ui_story_5043_50430101_94_dialog_content = "Deseja que paremos de ouvir esses casos, meu senhor?",
  ui_story_5043_50430101_95_dialog_content = "Não, ainda não é hora disso.",
  ui_story_5043_50430101_96_dialog_content = "Isso resultaria apenas em cidadãos direcionando sua raiva para o Tribunal de Justiça.",
  ui_story_5043_50430101_97_dialog_content = "O que você gostaria que fizéssemos, então?",
  ui_story_5043_50430101_98_dialog_content = "Estabeleça um tribunal subordinado temporário para lidar com essas disputas românticas.",
  ui_story_5043_50430101_99_dialog_content = "Ainda fará parte dos Jardins de Lumopolis, mas separado do Palácio da Justiça.",
  ui_story_5043_50430101_100_dialog_content = "Quanto ao pessoal... mande alguns dos mais jovens. Será uma boa experiência para eles.",
  ui_story_5043_50430101_101_dialog_content = "Um tribunal temporário exigirá um juiz supremo temporário.",
  ui_story_5043_50430101_102_dialog_content = "May Eu pergunto se você tem alguém em mente?",
  ui_story_5043_50430101_103_dialog_content = "Por acaso notei um jovem candidato em particular mais cedo...",
  ui_story_5043_50430101_104_dialog_content = "<color=#e8d9bb>O Hall of Justice, Lumopolis Gardens</color>",
  ui_story_5043_50430101_105_dialog_content = "parece Irridon e o City Lord estão discutindo negócios importantes.",
  ui_story_5043_50430101_106_dialog_content = "Acho que a reunião de hoje não vai acontecer. Se bem me lembro, a próxima vaga livre na agenda dele é...",
  ui_story_5043_50430101_107_dialog_content = "Oh, desculpe, PlayerName. Você vai ficar esperando por dias.",
  ui_story_5043_50430101_108_dialog_content = "Você vai se acostumar com isso. Ele sempre quebra seus compromissos e ignora as opiniões dos outros.",
  ui_story_5043_50430101_109_dialog_content = "D-Não fale assim. E nós temos algum tempo livre agora, certo?",
  ui_story_5043_50430101_110_dialog_content = "Até mesmo observar esses juízes arrumando seus papéis é uma ótima maneira de passar o tempo.",
  ui_story_5043_50430101_111_dialog_content = "Acusação. Evidências. Argumentos... Ok, isso é tudo.",
  ui_story_5043_50430101_112_dialog_content = "Estou quase terminando aqui. Tina, como vai?",
  ui_story_5043_50430101_113_dialog_content = "Eh? O que?",
  ui_story_5043_50430101_114_dialog_content = "Oh, desculpe, Leyn. Essa audiência durou três horas. Eu sou todo-bocejo...",
  ui_story_5043_50430101_115_dialog_content = "Ah, é assim, né?",
  ui_story_5043_50430101_116_dialog_content = "Que dia agitado você teve. Aqui, minha querida Tina, tome um copo de bebida reconfortante para se sentir melhor...",
  ui_story_5043_50430101_117_dialog_content = "Mm, obrigado, Leyn. *Gole*",
  ui_story_5043_50430101_118_dialog_content = "Eh!?",
  ui_story_5043_50430101_119_dialog_content = "C-Chocolate quente?! Eu odeio bebidas doces!!!",
  ui_story_5043_50430101_120_dialog_content = "Heehee, acordado agora, não é? Eu não me importo se você tem narcolepsia. Trabalhe primeiro, durma depois.",
  ui_story_5043_50430101_121_dialog_content = "E agora que penso nisso... sinto que você tem estado mais sonolento do que o normal nos últimos dias.",
  ui_story_5043_50430101_122_dialog_content = "Eu não acho. Faço questão de ficar acordado quatro horas todos os dias.",
  ui_story_5043_50430101_123_dialog_content = "Ainda hoje? E você começou a bocejar antes de terminarmos o trabalho ontem.",
  ui_story_5043_50430101_124_dialog_content = "Você não dormiu bem? Não consigo imaginar você sofrendo de insônia.",
  ui_story_5043_50430101_125_dialog_content = "O que? Isso é ridículo. Até parece...",
  ui_story_5043_50430101_126_dialog_content = "Ok, está tudo arrumado. Eu estou indo para casa.",
  ui_story_5043_50430101_127_dialog_content = "Até amanhã, pessoal.",
  ui_story_5043_50430101_128_dialog_content = "Sim, irei em breve.",
  ui_story_5043_50430101_129_dialog_content = "Adeus, senhora Carleen e companheiro masculino.",
  ui_story_5043_50430101_130_dialog_content = "Até mais!",
  ui_story_5043_50430101_131_dialog_content = "(É a isso que fui reduzido? \"Companheiro\"?)",
  ui_story_5043_50430101_132_dialog_content = "Uau! Quanto tempo não vejo, companheiro de Lady Carleen!",
  ui_story_5043_50430101_133_dialog_content = "Eu conheço essa voz...",
  ui_story_5043_50430101_134_dialog_content = "Matthieu! E Loewe. Eu não esperava ver vocês dois.",
  ui_story_5043_50430101_135_dialog_content = "Matthieu, Vejo que você está ocioso e atrevido como sempre.",
  ui_story_5043_50430101_136_dialog_content = "Não fique com raiva, princesa. Não estou aqui para ficar ocioso.",
  ui_story_5043_50430101_137_dialog_content = "Algo interessante está acontecendo. você quer entrar?",
  ui_story_5043_50430101_138_dialog_content = "Algo interessante\"?",
  ui_story_5043_50430101_139_dialog_content = "Sim. Acabei de receber a palavra. Os plebeus não saberão disso até amanhã.",
  ui_story_5043_50430101_140_dialog_content = "Continue.",
  ui_story_5043_50430101_141_dialog_content = "É tipo isso. O tribunal tem um caso muito incomum para ouvir. Agora, ainda não foi atribuído, mas...",
  ui_story_5043_50430101_142_dialog_content = "É tão bom quanto o meu.",
  ui_story_5043_50430101_143_dialog_content = "O que ele quer dizer é que ele implorou e implorou ao Juiz Chefe desesperadamente até que ele conseguisse.",
  ui_story_5043_50430101_144_dialog_content = "Ei! Pare de interromper.",
  ui_story_5043_50430101_145_dialog_content = "Enfim, está ligado ao Mooncrown Day...",
  ui_story_5043_50430101_146_dialog_content = "<color=#e8d9bb>Jardins de Lumopolis, bairro residencial</color>",
  ui_story_5043_50430101_147_dialog_content = "La la... lalala... la la ♪...",
  ui_story_5043_50430101_148_dialog_content = "(Primeira coisa a fazer ao voltar para casa: verifique se há cartas ou pacotes...)",
  ui_story_5043_50430101_149_dialog_content = "Ai...",
  ui_story_5043_50430101_150_dialog_content = "Nada ainda.",
  ui_story_5043_50430101_151_dialog_content = "(ainda tenho as folhas e nozes <color=#FFB400>ele</color> me enviou no mês passado.)",
  ui_story_5043_50430101_152_dialog_content = "(É hora de enviar algo em troca, mas <color=#FFB400>ele</color> ainda não me deu seu novo endereço.)",
  ui_story_5043_50430101_153_dialog_content = "(E agora que penso nisso, faz quase um mês desde que ouvi <color=#FFB400>ele</color>.)",
  ui_story_5043_50430101_154_dialog_content = "(É bastante preocupante... Quando poderei enviar os biscoitos que fiz para <color=#FFB400>ele</color>?)",
  ui_story_5043_50430101_155_dialog_content = "(Talvez eu devesse... ser um pouco mais proativo?)",
  ui_story_5043_50430201_1_dialog_content = "<color=#e8d9bb>No dia seguinte</color>",
  ui_story_5043_50430201_2_dialog_content = "Então é assim que as coisas são.",
  ui_story_5043_50430201_3_dialog_content = "O City Lord decidiu criar um tribunal temporário nos Jardins de Lumopolis.",
  ui_story_5043_50430201_4_dialog_content = "Eu decidi chamá-lo de <color=#FFB400>Divisão Romance</color>.",
  ui_story_5043_50430201_5_dialog_content = "Eu entendo. E vou continuar a fazer o meu melhor lá.",
  ui_story_5043_50430201_6_dialog_content = "Mas se posso perguntar, quem servirá como juiz supremo? Você também assumirá esse fardo?",
  ui_story_5043_50430201_7_dialog_content = "Não, tivemos orientação do City Lord sobre esse assunto. Ele sugeriu o juiz <color=#FFB400>Schwab</color>.",
  ui_story_5043_50430201_8_dialog_content = "Uma decisão que não entendo inteiramente, embora ele tenha impressionado o Lorde da Cidade ontem...",
  ui_story_5043_50430201_9_dialog_content = "E talvez seu estilo seja particularmente adequado para lidar com casos amorosos.",
  ui_story_5043_50430201_10_dialog_content = "Muito bem. Schwab tinha sua própria maneira única de resolver aquela bagunça ontem. Fiquei impressionado.",
  ui_story_5043_50430201_11_dialog_content = "Ele certamente sabe como usar seus... encantos.",
  ui_story_5043_50430201_12_dialog_content = "Você não deve se decepcionar, Leyn.",
  ui_story_5043_50430201_13_dialog_content = "Vocês acabaram de se tornar juízes oficiais, mas o Lorde da Cidade aprecia suas habilidades.",
  ui_story_5043_50430201_14_dialog_content = "E quando voltar da Divisão de Romance, estará bem posicionado para uma promoção.",
  ui_story_5043_50430201_15_dialog_content = "Sim. Obrigado, Juiz Supremo.",
  ui_story_5043_50430201_16_dialog_content = "Além disso, tenho outra tarefa para você.",
  ui_story_5043_50430201_17_dialog_content = "Na verdade, pode ser o caso mais complicado que a Divisão Romance tem que lidar no momento.",
  ui_story_5043_50430201_18_dialog_content = "Você pode ter ouvido falar disso? <color=#FFB400>O caso da estátua sem cabeça</color>?",
  ui_story_5043_50430201_19_dialog_content = "Recebo meu primeiro caso tão cedo?",
  ui_story_5043_50430201_20_dialog_content = "Ah, é um alívio saber que você está tão interessado. Cinco ou seis pessoas já recusaram o caso.",
  ui_story_5043_50430201_21_dialog_content = "E por que eles fizeram isso?",
  ui_story_5043_50430201_22_dialog_content = "Além do fato de que é um caso estranho... a maioria deles disse que estava ocupada saindo com seus amantes.",
  ui_story_5043_50430201_23_dialog_content = "Ah, entendi.",
  ui_story_5043_50430201_24_dialog_content = "(Esses nobres nunca mudam...)",
  ui_story_5043_50430201_25_dialog_content = "O autor do caso é um nobre do Pátio de Lumópolis, Sr. <color=#FFB400>Byron</color>.",
  ui_story_5043_50430201_26_dialog_content = "<color=#e8d9bb>Quatro dias atrás</color>",
  ui_story_5043_50430201_27_dialog_content = "<color=#e8d9bb>Ding, ding—Ding—</color>",
  ui_story_5043_50430201_28_dialog_content = "Estou chegando, estou chegando. Pare de cantar!",
  ui_story_5043_50430201_29_dialog_content = "Você ligou, senhor? Você tocou o Sino da Justiça?",
  ui_story_5043_50430201_30_dialog_content = "Eu fiz. Desejo processar alguém! É meu vizinho.",
  ui_story_5043_50430201_31_dialog_content = "ele danificou <color=#FFB400>Galatea</color>, a estátua que fica do lado de fora do Hall of Justice. Eu vi com meus próprios olhos!",
  ui_story_5043_50430201_32_dialog_content = "Espere. Eu sei que a estátua simboliza a justiça. Mas desde quando se chama Galatea?",
  ui_story_5043_50430201_33_dialog_content = "E sim, quebrou há alguns dias, mas para ser honesto, pensamos que era apenas velho...",
  ui_story_5043_50430201_34_dialog_content = "Senhorita, por favor, preste atenção ao seu idioma. Galatea é um <color=#FFB400>\"ela\"</color>!!! Fui eu quem a nomeou.",
  ui_story_5043_50430201_35_dialog_content = "Er, tudo bem. Então, você poderia por favor me entregar sua reclamação?",
  ui_story_5043_50430201_36_dialog_content = "Vejamos...",
  ui_story_5043_50430201_37_dialog_content = "Hum? Sr. Byron, o crime do qual você acusa seu vizinho... está correto?",
  ui_story_5043_50430201_38_dialog_content = "Você acabou de dizer que ele danificou a estátua, mas aqui você escreveu <color=#FFB400>\"obstrução do amor</color>.\"",
  ui_story_5043_50430201_39_dialog_content = "Está correto. Porque...",
  ui_story_5043_50430201_40_dialog_content = "Galatea é minha <color=#FFB400>amante</color>!",
  ui_story_5043_50430201_41_dialog_content = "Então ele se apaixonou por uma estátua... e agora quer processar a pessoa que a vandalizou?",
  ui_story_5043_50430201_42_dialog_content = "Sim. Como a estátua é classificada como um bem público, não podemos impedir que alguém se apaixone por ela.",
  ui_story_5043_50430201_42X1_dialog_content = "E assim, estritamente falando, este é um caso para a Divisão Romance.",
  ui_story_5043_50430201_43_dialog_content = "Também enviei pessoas para falar com o réu.",
  ui_story_5043_50430201_44_dialog_content = "Há lacunas na história do Sr. Byron. O réu no caso pode não ser o suspeito.",
  ui_story_5043_50430201_45_dialog_content = "Como vocês sabem, aqui no Tribunal de Justiça tanto investigamos quanto julgamos. Leyn, devemos descobrir o que está acontecendo antes que o caso seja ouvido.",
  ui_story_5043_50430201_46_dialog_content = "Caso contrário, acabaremos adiando o caso até uma audiência futura. E a Divisão Romance nem é um arranjo permanente, então isso não é uma opção.",
  ui_story_5043_50430201_47_dialog_content = "Sim, eu entendo. Vou resolver o caso antes que a Divisão Romance feche, garanto.",
  ui_story_5043_50430201_48_dialog_content = "Fico feliz em ouvir isso. E dois de seus colegas estarão ajudando você.",
  ui_story_5043_50430201_49_dialog_content = "Um é seu velho amigo, Tina. Ela concordou em ajudar esta manhã.",
  ui_story_5043_50430201_50_dialog_content = "Pedi a ela para revisar a papelada, embora suspeite que ela esteja recuperando o sono agora.",
  ui_story_5043_50430201_51_dialog_content = "O outro... bem, ele é uma dor de cabeça, mas ele é tecnicamente <color=#FFB400>mais experiente</color> do que você. Tenho certeza de que ele lhe dará algumas dicas úteis.",
  ui_story_5043_50430201_52_dialog_content = "Você pode encontrá-lo agora, na frente daquela estátua.",
  ui_story_5043_50430201_53_dialog_content = "Comparar notas com Tina quando você terminar suas investigações.",
  ui_story_5043_50430201_54_dialog_content = "Eu irei imediatamente.",
  ui_story_5043_50430201_55_dialog_content = "<color=#e8d9bb>Jardins de Lumopolis, junto à estátua</color>",
  ui_story_5043_50430201_56_dialog_content = "(Eu me pergunto quem é essa pessoa \"mais experiente\" sobre a qual o Juiz Chefe estava sendo tão vago...)",
  ui_story_5043_50430201_57_dialog_content = "Oh meu, o Hall of Justice está apenas deixando qualquer plebeu entrar agora?",
  ui_story_5043_50430201_58_dialog_content = "(Eu deveria ter adivinhado...)",
  ui_story_5043_50430201_59_dialog_content = "Eu penso Leyn parece mais um juiz adequado do que você, Matthieu.",
  ui_story_5043_50430201_60_dialog_content = "bom dia capitão Carleen, e meus melhores votos.",
  ui_story_5043_50430201_61_dialog_content = "Por favor, não faça cerimônia. Isso é PlayerName. Matthieu aqui nos pediu para ajudar na investigação.",
  ui_story_5043_50430201_62_dialog_content = "Você é o lendário Celestita! Você é muito mais acessível pessoalmente!",
  ui_story_5043_50430201_63_dialog_content = "V-você é muito gentil. Espero poder ajudar.",
  ui_story_5043_50430201_64_dialog_content = "<size=32>O que no mundo os rumores dizem sobre mim...</size>",
  ui_story_5043_50430201_65_dialog_content = "Você deve agradecer ao Deus da Luz, plebeu. Com a nossa ajuda, seu trabalho deve prosseguir rapidamente.",
  ui_story_5043_50430201_66_dialog_content = "Ficarei surpreso se não correr mal.",
  ui_story_5043_50430201_67_dialog_content = "O que há de errado, novato? Você não parece animado.",
  ui_story_5043_50430201_68_dialog_content = "Este é um dos casos mais estranhos da história do Tribunal de Justiça. Mostre um pouco de entusiasmo!",
  ui_story_5043_50430201_69_dialog_content = "Sim. Uma estátua estranha, um crime estranho, um queixoso estranho. E um mentor estranho.",
  ui_story_5043_50430201_70_dialog_content = "Cuidado, garoto! Mostre um pouco mais de respeito.",
  ui_story_5043_50430201_71_dialog_content = "Muito bem. Não vim aqui para brigar com você. Presumo que tenha examinado a estátua?",
  ui_story_5043_50430201_72_dialog_content = "Huh? Oh, você quer dizer a caixa de dinheiro?",
  ui_story_5043_50430201_73_dialog_content = "Desculpe, é só sem a cabeça, isso me lembra de algo em que você pode guardar moedas. Isso me dá vontade de jogar um Nightium.",
  ui_story_5043_50430201_74_dialog_content = "Oh, por favor. Tente levar isso a sério...",
  ui_story_5043_50430201_75_dialog_content = "<color=#e8d9bb>Foto-</color>",
  ui_story_5043_50430201_76_dialog_content = "O que foi isso?",
  ui_story_5043_50430201_77_dialog_content = "Graaaaaah! Rugido!",
  ui_story_5043_50430201_78_dialog_content = "O que no mundo?! Como os Eclipsites chegaram aos Jardins de Lumopolis?",
  ui_story_5043_50430201_79_dialog_content = "É impossível! Lumópolis é vigiada dia e noite. Não tem como um Eclipsite entrar...",
  ui_story_5043_50430201_80_dialog_content = "Guardas!",
  ui_story_5043_50430201_81_dialog_content = "Senhora!",
  ui_story_5043_50430201_82_dialog_content = "Vou verificar todos os registros de entrada e saída. E diga ao Nightwatch que quero um relatório sobre todas as atividades recentes!",
  ui_story_5043_50430201_83_dialog_content = "Quanto aos Eclipsitos... PlayerName, Presumo que vocês quatro possam lidar com eles?",
  ui_story_5043_50430201_84_dialog_content = "Claro. Ir, Carleen.",
  ui_story_5043_50430201_85_dialog_content = "Está bem então. Hora de os Eclipsitas receberem seu veredicto final.",
  ui_story_5043_50430202_1_dialog_content = "Acabou! Ninguém se machucou, não é?",
  ui_story_5043_50430202_2_dialog_content = "Estou bem. Apenas um pouco enojado.",
  ui_story_5043_50430202_3_dialog_content = "Eu só tenho que trabalhar. Agora preciso de um banho de novo.",
  ui_story_5043_50430202_4_dialog_content = "Ei, plebeu, tudo bem?",
  ui_story_5043_50430202_5_dialog_content = "Obrigado por perguntar. Acontece que não sou abençoado com a mesma necessidade de banho constante que vocês, aristocratas, gostam.",
  ui_story_5043_50430202_6_dialog_content = "Eu me sinto tão triste por você. Embora eu suponha que isso signifique que Loewe é o maior germafóbico aqui.",
  ui_story_5043_50430202_7_dialog_content = "Você sempre se escondeu tão bem, Loewe. Suspeito que você até ache o ar sujo.",
  ui_story_5043_50430202_8_dialog_content = "Vocês provavelmente podem renunciar se a estátua estiver quebrada.",
  ui_story_5043_50430202_9_dialog_content = "Não me ignore!",
  ui_story_5043_50430202_10_dialog_content = "Ok, você já viu o suficiente. O Tribunal de Justiça pode lidar com isso agora.",
  ui_story_5043_50430202_11_dialog_content = "Crucial <color=#FFB400>evidência</color> não deve ser deixado sentado ao ar livre assim.",
  ui_story_5043_50430202_12_dialog_content = "Segundo o reclamante, este é o <color=#FFB400>vítima</color>.",
  ui_story_5043_50430202_13_dialog_content = "Espere, deixe-me dar uma olhada mais de perto...",
  ui_story_5043_50430202_14_dialog_content = "Hum. A seção de fratura é mais limpa. Não parece uma velha rachadura que finalmente se abriu.",
  ui_story_5043_50430202_15_dialog_content = "É mais como se alguém deliberadamente tivesse quebrado a cabeça.",
  ui_story_5043_50430202_16_dialog_content = "PlayerName, Você tem algum conselho?",
  ui_story_5043_50430202_17_dialog_content = "Há uma coisa estranha.",
  ui_story_5043_50430202_18_option_content = "A cabeça que falta",
  ui_story_5043_50430202_19_dialog_content = "Não parece vandalismo espontâneo. A ruptura é muito limpa.",
  ui_story_5043_50430202_20_dialog_content = "Além disso, não há nenhum outro dano. Apenas a cabeça que falta.",
  ui_story_5043_50430202_21_option_content = "fragmentos de estátua",
  ui_story_5043_50430202_22_dialog_content = "Os arredores são limpos demais. Não deveria haver pedaços extras da estátua por aí?",
  ui_story_5043_50430202_23_dialog_content = "As pessoas enviadas para coletar as evidências provavelmente as varreram.",
  ui_story_5043_50430202_24_dialog_content = "T-Isso faz sentido! Nesse caso, acho que o estranho é... a cabeça faltando.",
  ui_story_5043_50430202_25_dialog_content = "Eu acho que você está certo. Parece que alguém quebrou a cabeça da estátua para que eles pudessem <color=#FFB400>roubá-lo</color>...",
  ui_story_5043_50430202_26_dialog_content = "Ei, espere. Algum de vocês vê <color=#FFB400>que</color>? Eu simplesmente apareci do nada.",
  ui_story_5043_50430202_27_dialog_content = "Olhe, ao lado daquela janela, no céu sobre Lumópolis...",
  ui_story_5043_50430202_28_dialog_content = "É um <color=#FFB400>lua</color>.",
  ui_story_5043_50430202_29_dialog_content = "Eu vejo isso!",
  ui_story_5043_50430202_30_dialog_content = "Coisas estranhas continuam acontecendo. O que anda acontecendo no mundo?",
  ui_story_5043_50430202_31_dialog_content = "Que intrigante. Devemos dar uma olhada?",
  ui_story_5043_50430202_32_dialog_content = "Espere... Ainda temos trabalho a fazer!",
  ui_story_5043_50430202_33_dialog_content = "Oh, vocês estão todos aqui?",
  ui_story_5043_50430202_34_dialog_content = "Ei, Tina. Isso é PlayerName. O celestita.",
  ui_story_5043_50430202_35_dialog_content = "Hehe. Na verdade, nos conhecemos no mês passado, no Mooncrown Day.",
  ui_story_5043_50430202_36_dialog_content = "Bom dia, PlayerName. É adorável ver você de novo.",
  ui_story_5043_50430202_37_dialog_content = "Olá, Tina. Embora não seja mais manhã...",
  ui_story_5043_50430202_38_dialog_content = "Tina sempre pensa que é de manhã quando acorda.",
  ui_story_5043_50430202_39_dialog_content = "Você tem um timing perfeito, Tina. Vamos compartilhar notas sobre a investigação.",
  ui_story_5043_50430202_40_dialog_content = "Então... vamos dizer o que temos ao mesmo tempo. Até agora, eu descobri—",
  ui_story_5043_50430202_41_dialog_content = "Nenhuma coisa.",
  ui_story_5043_50430202_42_dialog_content = "Suspirar. Então você também não fez nenhum progresso?",
  ui_story_5043_50430202_43_dialog_content = "Examinei repetidamente os documentos do caso que o Juiz Chefe me deu.",
  ui_story_5043_50430202_44_dialog_content = "Mas é tudo tão ilógico e inconsistente. Não consigo entender nada disso.",
  ui_story_5043_50430202_45_dialog_content = "Nós temos uma teoria potencial, pelo menos.",
  ui_story_5043_50430202_46_dialog_content = "PlayerName e suspeito que a cabeça da estátua foi roubada.",
  ui_story_5043_50430202_47_dialog_content = "Certo... Por que alguém faria isso?",
  ui_story_5043_50430202_48_dialog_content = "Quem sabe! Talvez Judge Jr. decidiu comprar um novo capacete.",
  ui_story_5043_50430202_49_dialog_content = "Se não estamos fazendo nenhum progresso, talvez devêssemos encerrar o dia?",
  ui_story_5043_50430202_50_dialog_content = "Espere! Na verdade, eu... Erm...",
  ui_story_5043_50430202_51_dialog_content = "O fato é que eu queria pedir a todos vocês alguns conselhos sobre um assunto particular.",
  ui_story_5043_50430202_52_dialog_content = "Uh, que tipo de assunto privado, exatamente? Não tenho certeza se quero me envolver...",
  ui_story_5043_50430202_53_dialog_content = "F-Tudo bem. Tive um pequeno problema ultimamente e queria uma segunda opinião.",
  ui_story_5043_50430202_54_dialog_content = "Oooh. Um assunto privado, em um momento como este?",
  ui_story_5043_50430202_55_dialog_content = "Deixe-me arriscar um palpite. É um problema romântico, não é?",
  ui_story_5043_50430202_56_dialog_content = "Você está muito animado com isso.",
  ui_story_5043_50430202_57_dialog_content = "Hum. De qualquer forma, posso convidar todos vocês para virem à minha casa? Preparei chá e bolos.",
  ui_story_5043_50430202_58_dialog_content = "PlayerName, Eu gostaria que você viesse também.",
  ui_story_5043_50430202_59_dialog_content = "Ouvi dizer que os celestitas são muito bons em entender as emoções das pessoas. Então você tem que me ajudar.",
  ui_story_5043_50430202_60_dialog_content = "Seria uma honra. Embora eu não tenha certeza de que temos essa habilidade em particular...",
  ui_story_5043_50430301_1_dialog_content = "<color=#e8d9bb>Jardins Lumopolis, a casa de Tina</color>",
  ui_story_5043_50430301_2_dialog_content = "Ok, isso é o que aconteceu.",
  ui_story_5043_50430301_3_dialog_content = "No Mooncrown Day do mês passado, recebi um presente de <color=#FFB400>ele</color>.",
  ui_story_5043_50430301_4_dialog_content = "Foram apenas algumas coisas comuns, mas eu poderia dizer que <color=#FFB400>ele</color> realmente se importava comigo.",
  ui_story_5043_50430301_5_dialog_content = "W-Woah! Aguentar, Tina. Você está apaixonado?",
  ui_story_5043_50430301_6_dialog_content = "Huh? Não, acho que não é isso...",
  ui_story_5043_50430301_7_dialog_content = "Bem, isso soa como o tipo de coisa que os amantes fazem.",
  ui_story_5043_50430301_8_dialog_content = "Se você também pensa assim...",
  ui_story_5043_50430301_9_dialog_content = "Ah, não importa! Deixe-me terminar a história.",
  ui_story_5043_50430301_10_dialog_content = "Já se passou quase um mês desde o Dia da Coroa da Lua e, de acordo com a tradição, devo enviar <color=#FFB400>ele</color> um presente em troca.",
  ui_story_5043_50430301_11_dialog_content = "Então eu fiz alguns biscoitos para <color=#FFB400>ele</color>. Eu até fiz cada biscoito em uma forma diferente.",
  ui_story_5043_50430301_12_dialog_content = "Então os biscoitos estavam todos prontos para serem enviados. Mas...",
  ui_story_5043_50430301_13_dialog_content = "Mas <color=#FFB400>ele</color> não respondeu a mais nenhuma das minhas cartas.",
  ui_story_5043_50430301_14_dialog_content = "Eu não tive a chance de marcar uma reunião com <color=#FFB400>ele</color>. E agora nem recebo cartas.",
  ui_story_5043_50430301_15_dialog_content = "Eu estou tão preocupado. Tem me mantido acordado. Estou dormindo apenas 16 horas por noite!",
  ui_story_5043_50430301_16_dialog_content = "Que homem desprezível!",
  ui_story_5043_50430301_17_dialog_content = "Sim. Ele soa pior do que Matthieu.",
  ui_story_5043_50430301_18_dialog_content = "Sugiro que desista dele.",
  ui_story_5043_50430301_19_dialog_content = "Não, ainda não posso fazer isso. Tenho certeza de que ele tem seus motivos.",
  ui_story_5043_50430301_20_dialog_content = "Afinal, <color=#FFB400>ele</color> tem uma aparência bastante única. As pessoas notam <color=#FFB400>ele</color> onde quer que ele vá. Então talvez ele não consiga manter contato tanto quanto gostaria.",
  ui_story_5043_50430301_21_dialog_content = "Uh-oh. Tina tem um péssimo caso de estar apaixonada.",
  ui_story_5043_50430301_22_dialog_content = "Hmm...?",
  ui_story_5043_50430301_23_dialog_content = "<size=32>Ei, PlayerName, Matthieu, Loewe. Eu tenho uma teoria...</size>",
  ui_story_5043_50430301_24_dialog_content = "<size=32>Esse <color=#FFB400>homem</color> O que Tina está falando parece familiar!</size>",
  ui_story_5043_50430301_25_dialog_content = "<size=32>Verdadeiro! Alguém que é notado onde quer que vá...</size>",
  ui_story_5043_50430301_26_dialog_content = "<size=32>E faz apenas um esforço mínimo para manter seus admiradores felizes...</size>",
  ui_story_5043_50430301_27_dialog_content = "<size=32>E é cruel, superficial, obcecado por si mesmo, egoísta...</size>",
  ui_story_5043_50430301_28_dialog_content = "<size=32>Parece que ele poderia ser seu irmão gêmeo.</size>",
  ui_story_5043_50430301_29_dialog_content = "<size=32>De qualquer forma, essa pessoa de quem Tina está falando deve ser <color=#FFB400>Schwab</color>, certo?</size>",
  ui_story_5043_50430301_30_dialog_content = "Ei, o que você está sussurrando?",
  ui_story_5043_50430301_31_dialog_content = "Aham. OK, Tina. Nós sabemos quem é sua paixão.",
  ui_story_5043_50430301_32_dialog_content = "O que? Você já adivinhou? Eu esperava manter isso em segredo...",
  ui_story_5043_50430301_33_dialog_content = "(Parece Tina não tem escolha a não ser admitir...)",
  ui_story_5043_50430301_34_dialog_content = "A primeira vez que o vi foi em Salar Manor.",
  ui_story_5043_50430301_35_dialog_content = "Eu tinha sido convidado para um baile lá.",
  ui_story_5043_50430301_36_dialog_content = "Mas cheguei um pouco mais cedo e fui conduzido ao jardim para esperar.",
  ui_story_5043_50430301_37_dialog_content = "Mas é claro que os Salar têm um jardim incrível e me perdi no labirinto de sebes.",
  ui_story_5043_50430301_38_dialog_content = "Deus sabe quanto tempo passei lá. Então, de repente, encontrei um pequeno pavilhão e ele estava sentado nele.",
  ui_story_5043_50430301_39_dialog_content = "Ele ficou surpreso ao ver alguém ali. E passamos tanto tempo olhando um para o outro sob aquele lindo céu azul...",
  ui_story_5043_50430301_40_dialog_content = "Foi a primeira vez que percebi o quão gentil e amável ele podia ser. Ele parecia ser um com as árvores e flores ao seu redor.",
  ui_story_5043_50430301_41_dialog_content = "Ele acabou saindo antes de mim. Mas não consegui prestar atenção em mais ninguém naquele dia.",
  ui_story_5043_50430301_42_dialog_content = "Hehe. Como romantico.",
  ui_story_5043_50430301_43_dialog_content = "(Salar Manor. Então tem que ser Schwab Salar.)",
  ui_story_5043_50430301_44_dialog_content = "(\"Gentil\"? \"Gentil\"?! Aquele cara?? Se você diz...)",
  ui_story_5043_50430301_45_dialog_content = "Como já sabem quem ele é, tenho um favor a pedir a todos.",
  ui_story_5043_50430301_46_dialog_content = "Eu preciso de você para me ajudar com <color=#FFB400>Operação Acci-Meet</color>.",
  ui_story_5043_50430301_47_dialog_content = "O que no mundo é um Acci-Meet?",
  ui_story_5043_50430301_48_dialog_content = "Bem, eu quero projetar tantos <color=#FFB400>reuniões acidentais</color> possível com ele. Acimeet. Inteligente, hein?",
  ui_story_5043_50430301_49_dialog_content = "Você não vai desistir, vai? Mesmo que não o ajudemos.",
  ui_story_5043_50430301_50_dialog_content = "Não. Desculpe...",
  ui_story_5043_50430301_51_dialog_content = "Muito bem. Fico sempre feliz em ajudar um colega.",
  ui_story_5043_50430301_52_dialog_content = "Concordo.",
  ui_story_5043_50430301_53_dialog_content = "Gaah... Graaah...",
  ui_story_5043_50430301_54_dialog_content = "Eclipsitas!",
  ui_story_5043_50430301_55_dialog_content = "Oh sério! Servo! Servo!",
  ui_story_5043_50430301_56_dialog_content = "Deixa para lá. Faz muito tempo que não treino a Mão Divina.",
  ui_story_5043_50430301_57_dialog_content = "Eu mesmo vou limpar essa sujeira.",
  ui_story_5043_50430301_58_dialog_content = "Esta não é a sua própria casa? Você está agindo como se fossem apenas algumas baratas!",
  ui_story_5043_50430302_1_dialog_content = "Que luta emocionante... *Bocejos*",
  ui_story_5043_50430302_2_dialog_content = "Eu não tinha notado antes, mas você é canhoto?",
  ui_story_5043_50430302_3_dialog_content = "haha. Sim eu sou. Fui treinado dessa maneira para lidar com o poder da Mão Divina.",
  ui_story_5043_50430302_4_dialog_content = "Mas eu sempre me sinto tão cansado depois de uma luta...",
  ui_story_5043_50430302_5_dialog_content = "Se você vai para a cama agora, então vamos embora.",
  ui_story_5043_50430302_6_dialog_content = "Cama? Não! Estou cheio de energia.",
  ui_story_5043_50430302_7_dialog_content = "Vamos voltar aos negócios. Preciso de todos vocês para me ajudar com a Operação Accimeet.",
  ui_story_5043_50430302_8_dialog_content = "Ok, mas... como?",
  ui_story_5043_50430302_9_dialog_content = "Bem... Para ser sincero, nunca persegui ninguém antes. É por isso que preciso da sua ajuda.",
  ui_story_5043_50430302_10_dialog_content = "O que eu preciso fazer?",
  ui_story_5043_50430302_11_dialog_content = "Deixe-me pensar... Li certa vez em um livro que o primeiro passo para mudar é reconhecer suas próprias deficiências.",
  ui_story_5043_50430302_12_dialog_content = "Acho que a melhor maneira de conquistar o coração dele é...<color=#FFB400> confessar seu amor</color>.",
  ui_story_5043_50430302_13_dialog_content = "Vá a algum lugar onde ele possa aparecer e espere por ele.",
  ui_story_5043_50430302_14_dialog_content = "E quando ele aparecer, você ataca! Surpreenda-o!",
  ui_story_5043_50430302_15_dialog_content = "Oh. Eu vejo...",
  ui_story_5043_50430302_16_dialog_content = "Errado de novo, plebeu. Tina não pode confiar apenas em tomar a iniciativa. Ela também precisa aprender <color=#FFB400>a arte da ocultação</color>.",
  ui_story_5043_50430302_17_dialog_content = "Ela precisa esconder seus verdadeiros sentimentos. Ele não pode ver como ela está ansiosa.",
  ui_story_5043_50430302_18_dialog_content = "Se você tem coragem de se aproximar dele, mas está nervoso demais para olhá-lo nos olhos, apenas finja ser tímido.",
  ui_story_5043_50430302_19_dialog_content = "Oh, eu vejo! Eu entendo.",
  ui_story_5043_50430302_20_dialog_content = "E também-<color=#FFB400>reconhecimento</color>.",
  ui_story_5043_50430302_21_dialog_content = "Você deve observar sua atitude ao discutir tópicos aparentemente inócuos.",
  ui_story_5043_50430302_22_dialog_content = "Você será capaz de descobrir seus verdadeiros sentimentos em duas ou três conversas.",
  ui_story_5043_50430302_23_dialog_content = "Isso parece difícil. Mas farei o possível...",
  ui_story_5043_50430302_24_dialog_content = "Depois de uma consideração cuidadosa, acho que é melhor apenas <color=#FFB400>seja honesto</color>.",
  ui_story_5043_50430302_25_dialog_content = "Ao longo de um relacionamento, todos os seus hábitos e defeitos serão expostos à outra pessoa.",
  ui_story_5043_50430302_26_dialog_content = "Você não será capaz de encobri-los para sempre. Então, a honestidade é a coisa mais importante.",
  ui_story_5043_50430302_27_dialog_content = "Você tem razão! Embora eu espere que possamos chegar a esse estágio...",
  ui_story_5043_50430302_28_dialog_content = "Obrigado a todos! Vou me lembrar de todos os seus conselhos.",
  ui_story_5043_50430302_29_dialog_content = "A propósito... vocês estão falando por experiência própria?",
  ui_story_5043_50430302_30_dialog_content = "Aham…",
  ui_story_5043_50430302_31_dialog_content = "Receio não ter nenhuma experiência prática, não...",
  ui_story_5043_50430302_32_dialog_content = "Eu não queria criticar ninguém. É só... Acho que vou precisar tentar eu mesmo.",
  ui_story_5043_50430302_33_dialog_content = "Mas onde posso encontrá-lo?",
  ui_story_5043_50430302_34_dialog_content = "Se for ele, provavelmente em algum lugar movimentado, cheio de gente.",
  ui_story_5043_50430302_35_dialog_content = "Oh. OK...",
  ui_story_5043_50430302_36_dialog_content = "Falando em lugares movimentados, a escolha é óbvia.",
  ui_story_5043_50430302_37_dialog_content = "Aquele lugar onde nobres e plebeus se reúnem. Diretamente sob a \"lua\".",
  ui_story_5043_50430302_38_dialog_content = "P-por quê!?",
  ui_story_5043_50430302_39_dialog_content = "Ouvi algumas notícias sobre a \"lua\" antes. Acho que devemos ir investigar.",
  ui_story_5043_50430302_40_dialog_content = "Você só quer ir e ver.",
  ui_story_5043_50430302_41_dialog_content = "Não importa, eu também estou curioso. Vamos agora!",
  ui_story_5043_50430302_42_dialog_content = "Oh não. Espere um minuto!",
  ui_story_5043_50430302_43_dialog_content = "eu quero vestir o <color=#FFB400>luvas</color> Eu usava quando nos conhecemos e demos as mãos.",
  ui_story_5043_50430302_44_dialog_content = "E tenho que levar os biscoitos que fiz para ele também.",
  ui_story_5043_50430401_1_dialog_content = "<color=#e8d9bb>Jardins de Lumopolis, bairro residencial</color>",
  ui_story_5043_50430401_2_dialog_content = "Então, este balão de ar quente que parece uma lua está flutuando lá em cima há dias?",
  ui_story_5043_50430401_3_dialog_content = "eu nem tinha percebido...",
  ui_story_5043_50430401_4_dialog_content = "Acho que não imaginava que haveria alguma coisa lá em cima, exceto os Jardins de Lumopolis e o sol.",
  ui_story_5043_50430401_5_dialog_content = "É bastante normal que você perca isso. Plebeus como você nunca pensariam em levantar a cabeça e apreciar a beleza dos céus.",
  ui_story_5043_50430401_6_dialog_content = "Ei, diga isso de novo!",
  ui_story_5043_50430401_7_dialog_content = "Está bem, está bem. Mais caminhadas, menos lutas, por favor.",
  ui_story_5043_50430401_8_dialog_content = "Lembro que quando eu era pequena, minha mãe me levou à Escadaria para os Céus e disse que era o único lugar onde podíamos ver estrelas.",
  ui_story_5043_50430401_9_dialog_content = "A cada passo, você vê uma estrela. Suba todos os degraus, você vê mil.",
  ui_story_5043_50430401_10_dialog_content = "Eu estava tão animado! Eu corri todo o caminho até o topo.",
  ui_story_5043_50430401_11_dialog_content = "Quantas estrelas você viu?",
  ui_story_5043_50430401_12_dialog_content = "Nenhum. Apenas o sol. Era meio-dia.",
  ui_story_5043_50430401_13_dialog_content = "Você poderia pelo menos ter esperado até a noite!",
  ui_story_5043_50430401_14_dialog_content = "Mas é quando eu durmo...",
  ui_story_5043_50430401_15_dialog_content = "...",
  ui_story_5043_50430401_16_dialog_content = "Por falar nisso Matthieu, o que você ouviu sobre a \"lua\"?",
  ui_story_5043_50430401_17_dialog_content = "Oh, é apenas um evento preparado por aqueles entusiastas do Mooncrown Day.",
  ui_story_5043_50430401_18_dialog_content = "Eles enviam um balão de ar quente que se parece com a lua para o céu sobre Lumopolis, para anunciar o reino do amor livre.",
  ui_story_5043_50430401_19_dialog_content = "E quando o balão sobe, todos sabem que se reúnem embaixo dele para um salão improvisado.",
  ui_story_5043_50430401_20_dialog_content = "Todos os nobres que seguem as tendências adoram.",
  ui_story_5043_50430401_21_dialog_content = "Eu vejo. Eu lembro Carleen dizendo algo sobre os entusiastas do Mooncrown Day.",
  ui_story_5043_50430401_22_dialog_content = "É por isso que eles usam um balão que se parece com a lua... porque é o Dia da Coroa da Lua.",
  ui_story_5043_50430401_23_dialog_content = "Como vocês, nobres, são espertos.",
  ui_story_5043_50430401_24_dialog_content = "Acho que faz sentido porque a lua e o amor são coisas puras e belas.",
  ui_story_5043_50430401_25_dialog_content = "Tenho certeza de que quem planejou esses eventos estava pensando nisso.",
  ui_story_5043_50430401_26_dialog_content = "Que coisa para dizer. É assim que as garotas são quando estão apaixonadas?",
  ui_story_5043_50430401_27_dialog_content = "Eu disse que não estou apaixonada! Tanto faz, pare de me provocar, ok?",
  ui_story_5043_50430401_28_dialog_content = "De qualquer forma, parece que o balão está sobre o pátio de Lumopolis, então deve ser lá que a festa vai acontecer.",
  ui_story_5043_50430401_29_dialog_content = "Eca. Como é que temos que andar ainda mais? Quando os Guardiões vão colocar carruagens na Escadaria para os Céus?",
  ui_story_5043_50430401_30_dialog_content = "Nem todo mundo pode se dar ao luxo de pegar carruagens, você sabe.",
  ui_story_5043_50430401_31_dialog_content = "A Stairway to the Skies é a rota principal do Pátio de Lumopolis aos Jardins de Lumopolis.",
  ui_story_5043_50430401_32_dialog_content = "Você está pronto para mergulhar no mundo dos plebeus, Matthieu?",
  ui_story_5043_50430401_33_dialog_content = "Oh, cale-se!",
  ui_story_5043_50430401_34_dialog_content = "<color=#e8d9bb>Pátio Lumopolis, Praça Meadow</color>",
  ui_story_5043_50430401_35_dialog_content = "Uau—",
  ui_story_5043_50430401_36_dialog_content = "Não sabia que o Pátio de Lumopolis tinha um espaço verde tão lindo. É lindo.",
  ui_story_5043_50430401_37_dialog_content = "Acho que foi construído nesta primavera. Eles usam Luminatics para mantê-lo.",
  ui_story_5043_50430401_38_dialog_content = "Ei, você ouviu isso?",
  ui_story_5043_50430401_39_dialog_content = "Parece que estão tocando música no meio da praça, bem embaixo do balão.",
  ui_story_5043_50430401_39X1_dialog_content = "Pelo que ouvi, o salão tem três partes: uma confraternização, um baile e uma sessão de apreciação de poesia.",
  ui_story_5043_50430401_40_dialog_content = "Mm ... música de dança bastante normal. Sabor surpreendentemente aceitável.",
  ui_story_5043_50430401_40X1_dialog_content = "Jovens, é a primeira vez que vão ao Moonlight Salon?",
  ui_story_5043_50430401_40X2_dialog_content = "Não fique parado! Vem vem!",
  ui_story_5043_50430401_40X3_dialog_content = "Ei! Espere, não me puxe... Puxa, eu não aguento isso!",
  ui_story_5043_50430401_41_dialog_content = "Devemos ter chegado a tempo para a dança!",
  ui_story_5043_50430401_42_dialog_content = "É indelicado apenas ficar de lado com as costas contra a parede. Vamos nos juntar a eles e observar a multidão enquanto fazemos isso!",
  ui_story_5043_50430401_43_dialog_content = "M-Mas... eu não sei nada sobre danças nobres ou costumes!",
  ui_story_5043_50430401_44_dialog_content = "E eu tenho dois pés esquerdos.",
  ui_story_5043_50430401_45_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5043_50430401_46_dialog_content = "Então... Por que sou eu que estou dançando com o plebeu? Sinto-me doente!",
  ui_story_5043_50430401_47_dialog_content = "Você acha que estou gostando disso?!",
  ui_story_5043_50430401_48_dialog_content = "Ai!",
  ui_story_5043_50430401_49_dialog_content = "Cuidado onde pisa, seu tolo — ai!",
  ui_story_5043_50430401_50_dialog_content = "Você está fazendo isso deliberadamente!",
  ui_story_5043_50430401_51_dialog_content = "Ei, o que está fazendo?",
  ui_story_5043_50430401_52_dialog_content = "Pare com isso! Não puxe meu cabelo!",
  ui_story_5043_50430401_53_dialog_content = "Hahaha! Eles parecem estar se divertindo.",
  ui_story_5043_50430401_54_dialog_content = "PlayerName, você está nervoso?",
  ui_story_5043_50430401_55_dialog_content = "Não, não, estou bem.",
  ui_story_5043_50430401_56_dialog_content = "Vá para a esquerda, levante o pé, volte para a direita, vire...",
  ui_story_5043_50430401_57_dialog_content = "HHH-Como minha mão bateu em você!?",
  ui_story_5043_50430401_58_dialog_content = "Não se preocupe, é apenas uma dança amigável.",
  ui_story_5043_50430401_59_dialog_content = "Por que não tentamos isso de novo?",
  ui_story_5043_50430401_60_dialog_content = "OK. Eu vou fazer melhor desta vez.",
  ui_story_5043_50430401_61_dialog_content = "haha. Veja, você pode fazê-lo.",
  ui_story_5043_50430401_62_dialog_content = "Você é um aprendiz rápido.",
  ui_story_5043_50430401_63_dialog_content = "Ufa! Dançar é um verdadeiro exercício.",
  ui_story_5043_50430401_64_dialog_content = "Eu não quero fazer isso de novo...",
  ui_story_5043_50430401_65_dialog_content = "Tch, se eu não fosse tão gentil, estaria processando você.",
  ui_story_5043_50430401_66_dialog_content = "Para onde Loewe desapareceu?",
  ui_story_5043_50430401_67_dialog_content = "Parece que perdi toda a diversão.",
  ui_story_5043_50430401_68_dialog_content = "Avistei alguns personagens suspeitos do lado de fora mais cedo. Definitivamente não eram participantes do salão.",
  ui_story_5043_50430401_69_dialog_content = "Fui investigar e encontrei Lady Carleen.",
  ui_story_5043_50430401_70_dialog_content = "Obrigado por me mostrar o caminho. E esses personagens suspeitos estão comigo, na verdade.",
  ui_story_5043_50430401_71_dialog_content = "Uau! Senhora Carleen, você veio também!",
  ui_story_5043_50430401_72_dialog_content = "O que há de mais recente, Carleen? Algum progresso na incursão do Eclipsite?",
  ui_story_5043_50430401_73_dialog_content = "Não, mas eliminei algumas possibilidades.",
  ui_story_5043_50430401_74_dialog_content = "Os passes de viagem estão todos em ordem, então eles não poderiam estar se esgueirando para Lumopolis disfarçados.",
  ui_story_5043_50430401_75_dialog_content = "A Nightwatch tem feito seu trabalho e não há buracos no escudo sobre Lumopolis.",
  ui_story_5043_50430401_76_dialog_content = "Ultimamente tem havido mais movimento de mercadorias e mercenários, por causa de todos os festivais.",
  ui_story_5043_50430401_77_dialog_content = "Portanto, é possível que os guardas não tenham revistado os carregamentos de mercadorias adequadamente e os Eclipsites tenham se esgueirado dessa maneira.",
  ui_story_5043_50430401_78_dialog_content = "Huh? Você está procurando infiltrar-se em Eclipsites?",
  ui_story_5043_50430401_79_dialog_content = "Nesse caso... Tenho que encontrá-lo o mais rápido possível.",
  ui_story_5043_50430401_80_dialog_content = "Acho que você não precisa se preocupar com ele. Tenho certeza que ele está perfeitamente seguro.",
  ui_story_5043_50430401_81_dialog_content = "M-Mesmo...?",
  ui_story_5043_50430401_82_dialog_content = "(A preocupação de Tina parece muito estranha...)",
  ui_story_5043_50430401_83_dialog_content = "Bem, o chefe do Eclipsite deve saber algum tipo de <color=#FFB400>habilidade de camuflagem</color> para poder se misturar com a multidão.",
  ui_story_5043_50430401_84_dialog_content = "Não autorizei uma busca completa porque não quero causar pânico.",
  ui_story_5043_50430401_85_dialog_content = "Acabei de colocar alguns guardas à paisana e disse-lhes para vigiar qualquer área movimentada, apenas por precaução.",
  ui_story_5043_50430401_86_dialog_content = "Você sabe, Carleen, isso se parece muito com o que o City Lord está fazendo com os casos do Mooncrown Day.",
  ui_story_5043_50430401_87_dialog_content = "... Não considero isso um elogio.",
  ui_story_5043_50430401_88_dialog_content = "Er... Desculpe. Que tal eu me desculpar ajudando um pouco?",
  ui_story_5043_50430401_89_dialog_content = "Eu poderia pelo menos confirmar que não há nenhum Eclipsite na multidão aqui.",
  ui_story_5043_50430401_90_option_content = "Aumento de Força",
  ui_story_5043_50430401_91_dialog_content = "Obrigada, PlayerName.",
  ui_story_5043_50430401_92_dialog_content = "Bem? Algo incomum?",
  ui_story_5043_50430401_93_dialog_content = "Hum...",
  ui_story_5043_50430401_94_dialog_content = "Desculpe. É muito movimentado e barulhento aqui. Não está funcionando.",
  ui_story_5043_50430401_95_dialog_content = "Senhora Carleen! PlayerName! Ei!",
  ui_story_5043_50430401_96_dialog_content = "Não fique aí parado. Venha pra cá!",
  ui_story_5043_50430401_97_dialog_content = "Já que estou aqui... vamos ver o que está acontecendo.",
  ui_story_5043_50430401_98_dialog_content = "Esse balão é realmente impressionante de perto.",
  ui_story_5043_50430401_99_dialog_content = "Senhora Carleen, você também acha?",
  ui_story_5043_50430401_100_dialog_content = "Prados primaveris, casais apaixonados, um coro cantando ao fundo...",
  ui_story_5043_50430401_101_dialog_content = "E sob uma lua raramente vista, todos sobem os degraus enquanto trocam pensamentos intelectuais, independentemente de suas classes...",
  ui_story_5043_50430401_102_dialog_content = "Ora, é como algo saído de um conto de fadas.",
  ui_story_5043_50430401_103_dialog_content = "Pensamentos intelectuais, minha bunda. Este é apenas um festival de amor sentimental para casais de namorados.",
  ui_story_5043_50430401_104_dialog_content = "E nunca vi tantos plebeus em um só lugar antes. O lugar fede a Lower Lumopolis. Que nojo.",
  ui_story_5043_50430401_105_dialog_content = "Bem, agora é tarde.",
  ui_story_5043_50430401_106_dialog_content = "Ei, plebeu. O que você está olhando?",
  ui_story_5043_50430401_107_dialog_content = "Eu só estava pensando... aquele balão da lua é um pouco estranho.",
  ui_story_5043_50430401_108_dialog_content = "Não está preso ao chão, mas permanece em um só lugar. Eu me pergunto se eles estão controlando com Luminatics.",
  ui_story_5043_50430401_109_dialog_content = "Deixa para lá. Apenas as preocupações tolas de um plebeu comum. Por que se incomodar em perguntar o que eu penso?",
  ui_story_5043_50430401_110_dialog_content = "Você está correto, senhor. E o que mais...",
  ui_story_5043_50430401_111_dialog_content = "A Luminatics também está mantendo o <color=#FFB400>presentes de festivais antigos</color> dentro do balão.",
  ui_story_5043_50430401_112_dialog_content = "Desculpe, você é...?",
  ui_story_5043_50430401_113_dialog_content = "Oh, apenas uma freira de Lumopolis. Você pode me chamar apenas de irmã.",
  ui_story_5043_50430401_114_dialog_content = "Sou o organizador desses salões Moonlight.",
  ui_story_5043_50430401_115_dialog_content = "E acho que nunca te vi aqui antes. Espero que esteja se divertindo.",
  ui_story_5043_50430401_116_dialog_content = "B-Bem, não estou aqui há muito tempo. Tudo parece muito emocionante.",
  ui_story_5043_50430401_117_dialog_content = "Não parece nada com o Lumopolis que conheço.",
  ui_story_5043_50430401_118_dialog_content = "Hehe. Obrigado, e que o Deus da Luz os abençoe. Vou deixar vocês se divertirem.",
  ui_story_5043_50430401_119_dialog_content = "Por favor, sirvam-se do chá e das sobremesas. E não se esqueça de curtir o coral.",
  ui_story_5043_50430401_120_dialog_content = "(Aquele coro... por favor, não me diga...)",
  ui_story_5043_50430401_121_dialog_content = "Então você veio para a festa na lua. ♪",
  ui_story_5043_50430401_122_dialog_content = "Mas é um balão. ♪",
  ui_story_5043_50430401_123_dialog_content = "Nós vemos você vagar e se misturar. ♪",
  ui_story_5043_50430401_124_dialog_content = "Você ainda está solteiro? Ainda solteiro? ♪",
  ui_story_5043_50430401_125_dialog_content = "Ver? Crianças tão fofas.",
  ui_story_5043_50430401_126_dialog_content = "Bonitinho? Até parece!",
  ui_story_5043_50430401_127_dialog_content = "Dê um soco! Fatty vai pop! ♪",
  ui_story_5043_50430401_128_dialog_content = "Pendurado lá em cima, no alto! ♪",
  ui_story_5043_50430401_129_dialog_content = "O que é que aparece tão cedo? ♪",
  ui_story_5043_50430401_130_dialog_content = "Talvez um nobre, talvez um balão. ♪",
  ui_story_5043_50430401_131_dialog_content = "Ah, eles conseguiram Dawn Coro da Academia para cantar para eles, hein?",
  ui_story_5043_50430401_132_dialog_content = "Vejo que estão mantendo seu estilo usual.",
  ui_story_5043_50430401_133_dialog_content = "Homens e mulheres flertam sob o luar. ♪",
  ui_story_5043_50430401_134_dialog_content = "Nobres e plebeus dividem uma mesa e não brigam. ♪",
  ui_story_5043_50430401_135_dialog_content = "Oh honrada freira, adorável freira! ♪",
  ui_story_5043_50430401_136_dialog_content = "Seus salões com certeza são divertidos! ♪",
  ui_story_5043_50430401_137_dialog_content = "Não tenho certeza se as letras deles fazem muito sentido, mas eles são bons cantores...",
  ui_story_5043_50430401_138_dialog_content = "Ouvir um coral sempre me dá vontade de rezar.",
  ui_story_5043_50430401_139_dialog_content = "Noite Branca no alto, oh, Deus da Luz, por favor, permita-me encontrá-lo.",
  ui_story_5043_50430401_140_dialog_content = "Não tenho certeza se o Deus da Luz está encarregado de tais assuntos...",
  ui_story_5043_50430401_141_dialog_content = "Todos em Lumopolis podem louvar o Deus da Luz. ♪",
  ui_story_5043_50430401_142_dialog_content = "Mas um nobre se casou com um plebeu? Isso não está certo! ♪",
  ui_story_5043_50430401_143_dialog_content = "Oh honrada freira, pobre freira! ♪",
  ui_story_5043_50430401_144_dialog_content = "O desastre está chegando. Você! Deve! Correr! ♪",
  ui_story_5043_50430401_145_dialog_content = "Espere o que?!",
  ui_story_5043_50430401_146_dialog_content = "Limpe a área! Quero que todos os participantes desta reunião ilegal sejam presos.",
  ui_story_5043_50430401_147_dialog_content = "E me traga o organizador!",
  ui_story_5043_50430401_148_dialog_content = "Eca!",
  ui_story_5043_50430401_149_dialog_content = "Os Guardiões dos Jardins de Lumopolis! Correr!",
  ui_story_5043_50430401_150_dialog_content = "Sou um nobre de Uptown. Eles não ousariam...",
  ui_story_5043_50430401_151_dialog_content = "Ehhh!?",
  ui_story_5043_50430401_152_dialog_content = "Ah! Meu <color=#FFB400>biscoitos</color>!",
  ui_story_5043_50430401_153_dialog_content = "EU <color=#FFB400>perdido</color> os biscoitos que eu ia dar para ele!",
  ui_story_5043_50430401_154_dialog_content = "<color=#e8d9bb>*multidão murmurando*</color>",
  ui_story_5043_50430401_155_dialog_content = "(Não pode ser. Esses não são meus guardas!)",
  ui_story_5043_50430401_156_dialog_content = "Eu não dei tais ordens! Quem ousa...",
  ui_story_5043_50430401_157_dialog_content = "Capitão Carleen!",
  ui_story_5043_50430401_158_dialog_content = "Eles não são Guardiões dos Jardins de Lumopolis.",
  ui_story_5043_50430401_159_dialog_content = "Mas poucos outros nobres têm tais forças.",
  ui_story_5043_50430401_160_dialog_content = "Os foliões vão assumir que este ataque foi ordenado por Lumopolis Gardens!",
  ui_story_5043_50430401_161_dialog_content = "Entendo o que você está dizendo. Mas precisamos restaurar a ordem primeiro.",
  ui_story_5043_50430401_162_dialog_content = "Por favor, não entre em pânico. Me siga!",
  ui_story_5043_50430401_163_dialog_content = "<color=#e8d9bb>Esmagar-!</color>",
  ui_story_5043_50430401_164_dialog_content = "(O que foi aquele barulho?!)",
  ui_story_5043_50430401_165_dialog_content = "PlayerName, Paladino Giratório, preciso da sua ajuda.",
  ui_story_5043_50430401_166_dialog_content = "Junte forças com meus guardas à paisana e enfrente esses soldados, sejam eles quem forem!",
  ui_story_5043_50430401_167_dialog_content = "Fico contente em ajudar!",
  ui_story_5043_50430401_168_dialog_content = "Como quiser!",
  ui_story_5043_50430501_1_dialog_content = "Esses guardas com certeza correm rápido!",
  ui_story_5043_50430501_2_dialog_content = "Capitão, devo persegui-lo?",
  ui_story_5043_50430501_3_dialog_content = "Não se preocupe. Você tem outro trabalho a fazer.",
  ui_story_5043_50430501_4_dialog_content = "É uma pena, no entanto. O Moonlight Salon está arruinado e não encontramos quem procurávamos.",
  ui_story_5043_50430501_5_dialog_content = "Oh? Quem você estava procurando?",
  ui_story_5043_50430501_6_dialog_content = "Tina queria encontrar Schwab e dar-lhe algo em troca de seu presente do Mooncrown Day.",
  ui_story_5043_50430501_7_dialog_content = "Oh, eu não sabia que os dois tinham esse tipo de relacionamento.",
  ui_story_5043_50430501_8_dialog_content = "Então esse é o poder do Mooncrown Day. Jovens se apaixonando sem que suas famílias fizessem acordos prévios.",
  ui_story_5043_50430501_9_dialog_content = "Mas... Se posso ser franco, o que ela vê naquele playboy?",
  ui_story_5043_50430501_10_dialog_content = "Eu sei direito...?",
  ui_story_5043_50430501_11_dialog_content = "Ei, alguém viu Loewe?",
  ui_story_5043_50430501_12_dialog_content = "Não o vejo desde que os guardas fugiram.",
  ui_story_5043_50430501_13_dialog_content = "Enviei-o para descobrir de onde eles vieram. Você deve continuar investigando seu caso.",
  ui_story_5043_50430501_14_dialog_content = "Já tenho uma boa ideia do que aconteceu. Mas é melhor garantir.",
  ui_story_5043_50430501_15_dialog_content = "T-Isso não é bom.",
  ui_story_5043_50430501_16_dialog_content = "Eu sei eu sei. Seus cookies sumiram, certo?",
  ui_story_5043_50430501_17_dialog_content = "Vamos procurá-los. Eles provavelmente estão misturados com todas essas bagunças.",
  ui_story_5043_50430501_18_dialog_content = "Oh, eu gostaria que fosse o único problema!",
  ui_story_5043_50430501_19_dialog_content = "É a estátua na entrada da praça. Isso é...",
  ui_story_5043_50430501_20_dialog_content = "ficou <color=#FFB400>quebrado</color> durante todo o caos.",
  ui_story_5043_50430501_21_dialog_content = "Quê?!",
  ui_story_5043_50430501_22_dialog_content = "Eu ouvi algo quebrando enquanto todos estavam correndo.",
  ui_story_5043_50430501_23_dialog_content = "O estranho é que ele quebrou exatamente da mesma forma que o do Hall da Justiça.",
  ui_story_5043_50430501_24_dialog_content = "É como se houvesse decapitadores de estátuas trabalhando.",
  ui_story_5043_50430501_25_dialog_content = "Hmm... Acho que devemos ir e relatar ao nosso juiz supremo temporário então.",
  ui_story_5043_50430501_26_dialog_content = "Sim. E se ele não está aqui no Moonlight Salon, então ele deve estar...",
  ui_story_5043_50430501_27_dialog_content = "<color=#e8d9bb>Jardins de Lumopolis, escritório de Schwab</color>",
  ui_story_5043_50430501_28_dialog_content = "Mmm... Ok, entendi.",
  ui_story_5043_50430501_29_dialog_content = "Estou feliz que você voltou. Preciso que você deixe o caso da estátua de lado por enquanto, até que o autor atualize seu pedido.",
  ui_story_5043_50430501_30_dialog_content = "Temos um novo caso de romance prestes a começar. Então preparem-se, meus queridos subordinados.",
  ui_story_5043_50430501_31_dialog_content = "Só isso?",
  ui_story_5043_50430501_32_dialog_content = "Esta é a vida na Divisão Romance. Movendo-se constantemente para frente, como uma carruagem movida a Luminatics.",
  ui_story_5043_50430501_33_dialog_content = "É muito difícil para você entender, meu pequeno dente-de-leão, já que você não é o juiz supremo.",
  ui_story_5043_50430501_34_dialog_content = "L-Pequeno dente-de-leão???",
  ui_story_5043_50430501_35_dialog_content = "(Ele acabou de me chamar de pequeno dente-de-leão? Que náusea.)",
  ui_story_5043_50430501_36_dialog_content = "Você vai se acostumar com isso, PlayerName...",
  ui_story_5043_50430501_37_dialog_content = "Na verdade, Juiz Chefe Schwab, Tina tem algo que ela quer—",
  ui_story_5043_50430501_38_dialog_content = "Não tenho certeza se este é o melhor momento para isso.",
  ui_story_5043_50430501_39_dialog_content = "(Sim. O que é Leyn fazendo? Não tenho nada a dizer a Schwab.)",
  ui_story_5043_50430501_40_dialog_content = "Hum? Parece que meus subordinados estão trabalhando tão bem juntos que até guardam pequenos segredos para mim.",
  ui_story_5043_50430501_41_dialog_content = "De qualquer forma, aqui está a acusação e toda a papelada. É tudo muito simples. Nos vemos no tribunal!",
  ui_story_5043_50430501_42_dialog_content = "Ele está certo, parece fácil. E tem a ver com o Moonlight Salon em que estivemos...",
  ui_story_5043_50430501_43_dialog_content = "Huh? Aguarde um minuto! Pessoal, vejam o motivo do caso!",
  ui_story_5043_50430501_44_dialog_content = "<color=#e8d9bb>Sala da Justiça, Divisão Romance</color>",
  ui_story_5043_50430501_45_dialog_content = "O City Lord não faz as coisas pela metade. Olha o tamanho desse lugar!",
  ui_story_5043_50430501_46_dialog_content = "E dado o número de casos que estamos lidando em nosso primeiro dia, ele também está obtendo uma boa relação custo-benefício.",
  ui_story_5043_50430501_47_dialog_content = "<color=#e8d9bb>Tum!</color>",
  ui_story_5043_50430501_48_dialog_content = "Tribunal está em sessão!",
  ui_story_5043_50430501_49_dialog_content = "Primeiro, vamos apresentar as partes envolvidas no litígio de hoje!",
  ui_story_5043_50430501_50_dialog_content = "O queixoso é... um homem de Lower Lumopolis, que não pode ser identificado por questões de privacidade.",
  ui_story_5043_50430501_51_dialog_content = "A ré é... uma mulher de Lower Lumopolis, que não pode ser identificada por questões de privacidade.",
  ui_story_5043_50430501_52_dialog_content = "(não ouvi nada disso!)",
  ui_story_5043_50430501_53_dialog_content = "Eu, Schwab Salar, presidirei como juiz principal no julgamento de hoje.",
  ui_story_5043_50430501_54_dialog_content = "A comissão julgadora é composta por Matthieu Serrador, Tina Campbell, e Leyn...",
  ui_story_5043_50430501_55_dialog_content = "Assim como vários outros membros do tribunal.",
  ui_story_5043_50430501_56_dialog_content = "(Uau! Na verdade, Schwab parece meio competente quando se dedica a isso...)",
  ui_story_5043_50430501_57_dialog_content = "Se ninguém tiver objeções a nada disso, podemos prosseguir.",
  ui_story_5043_50430501_58_dialog_content = "Espere. Como é que somos apenas \"vários outros membros do tribunal\"?",
  ui_story_5043_50430501_59_dialog_content = "Sem objeções? Muito bem, vamos começar.",
  ui_story_5043_50430501_60_dialog_content = "Se o autor pudesse relatar os fatos do caso para nós?",
  ui_story_5043_50430501_61_dialog_content = "*Soluçando* Foi isso que aconteceu...",
  ui_story_5043_50430501_62_dialog_content = "Minha noiva - a ré - e eu fomos a Meadow Square no Lumopolis Courtyard para o Moonlight Salon...",
  ui_story_5043_50430501_63_dialog_content = "M-Mas ela...",
  ui_story_5043_50430501_64_dialog_content = "Por favor, não chore. Apenas conte-nos o que aconteceu.",
  ui_story_5043_50430501_65_dialog_content = "Eu amo tanto ela. Estamos juntos há quatro anos! Ela gosta de tomar café com chocolate e—",
  ui_story_5043_50430501_66_dialog_content = "Se você puder se ater aos assuntos relevantes, por favor.",
  ui_story_5043_50430501_67_dialog_content = "S-Desculpe. Ah, eu sempre faço tanta bagunça em tudo...",
  ui_story_5043_50430501_68_dialog_content = "Fomos ao Moonlight Salon e nos divertimos muito. Mas então ela ficou com raiva de repente e disse que queria terminar comigo!",
  ui_story_5043_50430501_69_dialog_content = "Quer dizer... O que eu diria à minha família? *Soluçando*",
  ui_story_5043_50430501_70_dialog_content = "Muito bem. Em seguida, o réu.",
  ui_story_5043_50430501_71_dialog_content = "Eu tinha meus motivos.",
  ui_story_5043_50430501_72_dialog_content = "Este homem, o queixoso, levou-me a sair.",
  ui_story_5043_50430501_73_dialog_content = "No entanto, ousou aceitar um presente de outro!",
  ui_story_5043_50430501_74_dialog_content = "(Ela está agindo como se fosse a reclamante.)",
  ui_story_5043_50430501_75_dialog_content = "Eu não...",
  ui_story_5043_50430501_76_dialog_content = "Então você pode explicar onde aquela cesta de <color=#FFB400>biscoitos</color> veio de?",
  ui_story_5043_50430501_77_dialog_content = "(Biscoitos? São aqueles...)",
  ui_story_5043_50430501_78_dialog_content = "Lá! Essa é a evidência!",
  ui_story_5043_50430501_79_dialog_content = "Você os coloca em sua cadeira. E há um cartão.",
  ui_story_5043_50430501_80_dialog_content = "E fica pior. Quem escreveu o cartão usa o mesmo <color=#FFB400>nome do animal de estimação</color> para você que eu faço!",
  ui_story_5043_50430501_81_dialog_content = "Oh, eu estou acabado.",
  ui_story_5043_50430501_82_dialog_content = "Estávamos certos. Esses dois encontraram os biscoitos que Tina havia perdido.",
  ui_story_5043_50430501_83_dialog_content = "<color=#e8d9bb>Bate, baque, baque!</color>",
  ui_story_5043_50430501_84_dialog_content = "Ordem!",
  ui_story_5043_50430501_85_dialog_content = "Qualquer cidadão de Lumopolis encontrado em desacato ao tribunal será condenado à morte... Brincadeira!",
  ui_story_5043_50430501_86_dialog_content = "<size=32>Ei, Tina. Essa é a cesta de biscoitos que você perdeu?</size>",
  ui_story_5043_50430501_87_dialog_content = "<size=32>Eh? É aquele PlayerName?</size>",
  ui_story_5043_50430501_88_dialog_content = "<size=32>Você não pode falar comigo quando o tribunal está em sessão!</size>",
  ui_story_5043_50430501_89_dialog_content = "<size=32>Nesse caso...</size>",
  ui_story_5043_50430501_90_option_content = "Aumento de Força!",
  ui_story_5043_50430501_91_dialog_content = "Uau! Esta é a sua habilidade Celestita? Eu sempre me perguntei sobre isso.",
  ui_story_5043_50430501_92_dialog_content = "Não importa isso agora. Então esses são seus biscoitos, certo?",
  ui_story_5043_50430501_93_dialog_content = "Sim, são meus! Não acredito que causei tantos problemas a essas pessoas inocentes...",
  ui_story_5043_50430501_94_dialog_content = "PlayerName, O que você acha que eu deveria fazer?",
  ui_story_5043_50430501_95_option_content = "Seja honesto",
  ui_story_5043_50430501_96_dialog_content = "Acho que você deveria admitir o que aconteceu. Os cookies são seus, mas foram feitos para serem dados a outra pessoa.",
  ui_story_5043_50430501_97_dialog_content = "Mas acho que este não é o melhor momento para Schwab ouvir a verdade.",
  ui_story_5043_50430501_98_dialog_content = "Então eu entenderia se você não gostasse muito da ideia.",
  ui_story_5043_50430501_99_dialog_content = "Huh? Schwab? Ouvir que verdade?",
  ui_story_5043_50430501_100_option_content = "Espere e veja",
  ui_story_5043_50430501_101_dialog_content = "Eu acho que você deveria esperar e ver como as coisas acontecem.",
  ui_story_5043_50430501_102_dialog_content = "Se começar a falar agora, correrá o risco de ser condenado por desacato ao tribunal.",
  ui_story_5043_50430501_103_dialog_content = "Então, o que o tribunal fará a seguir?",
  ui_story_5043_50430501_104_dialog_content = "Em seguida, ouvimos argumentos de ambos os lados.",
  ui_story_5043_50430501_105_dialog_content = "não tenho certeza porque PlayerName está tão interessado. Mas vou deixar Schwab continuar com o caso.",
  ui_story_5043_50430501_106_dialog_content = "Como tanto o autor quanto o réu parecem tão ansiosos para continuar, vamos agora ouvir mais argumentos.",
  ui_story_5043_50430501_107_dialog_content = "<size=32>Ouça, plebeu! Esta não é a maneira de fazer as coisas.</size>",
  ui_story_5043_50430501_108_dialog_content = "<size=32>Precisamos fazer algo. Mas não podemos envergonhar Tina.</size>",
  ui_story_5043_50430501_109_dialog_content = "<size=32>Concordo. Mas não sabemos o que Tina quer fazer.</size>",
  ui_story_5043_50430501_110_dialog_content = "<size=32>Ela não está falando por si mesma. Então... e se ajudarmos Schwab a descobrir por si mesmo?</size>",
  ui_story_5043_50430501_111_dialog_content = "<size=32>Nada mau garoto! Boa ideia.</size>",
  ui_story_5043_50430501_112_dialog_content = "Os juízes agora, por favor, comecem com interrogatórios.",
  ui_story_5043_50430501_113_dialog_content = "Aham. Autor, você diz que esta cesta de biscoitos não é sua. Você poderia nos dizer a quem pertence?",
  ui_story_5043_50430501_114_dialog_content = "Eu... não faço ideia. De repente, apareceu na mesa na minha frente.",
  ui_story_5043_50430501_115_dialog_content = "Eu só posso supor <color=#FFB400>alguém deixou lá</color>.",
  ui_story_5043_50430501_116_dialog_content = "Então você diria que alguém que frequentava o Moonlight Salon perdeu a cesta de biscoitos?",
  ui_story_5043_50430501_117_dialog_content = "E tenho certeza de que todos podemos imaginar para que ele foi planejado.",
  ui_story_5043_50430501_118_dialog_content = "Sim. Quero dizer, deve ter sido concebido como um <color=#FFB400>presente</color>.",
  ui_story_5043_50430501_119_dialog_content = "Mas não é um presente para mim. Eu não tenho nada a ver com isso.",
  ui_story_5043_50430501_120_dialog_content = "Então eu gostaria de perguntar ao réu, por que você tem tanta certeza de que seu amante foi desleal?",
  ui_story_5043_50430501_121_dialog_content = "Certamente é óbvio. Qualquer um pode ver que aquela cesta de biscoitos foi um presente de um <color=#FFB400>mulher</color>.",
  ui_story_5043_50430501_122_dialog_content = "Ele não ousaria aceitar tal presente, a menos que estivesse planejando terminar comigo.",
  ui_story_5043_50430501_123_dialog_content = "E aqui está o cerne da questão. O autor insiste que não aceitou nenhum presente. Você acredita que sim.",
  ui_story_5043_50430501_124_dialog_content = "Mas a mensagem no <color=#FFB400>cartão</color> é claramente de um amante...",
  ui_story_5043_50430501_125_dialog_content = "Oh, tudo bem. Talvez eu tenha sido muito apressado. Mas então, para quem eram os cookies?",
  ui_story_5043_50430501_126_dialog_content = "Essa é a pergunta crucial!",
  ui_story_5043_50430501_127_dialog_content = "E o destinatário pretendido está bem aqui!",
  ui_story_5043_50430501_128_dialog_content = "Bem aqui...?",
  ui_story_5043_50430501_129_dialog_content = "<color=#e8d9bb>Bate, baque, baque!</color>",
  ui_story_5043_50430501_130_dialog_content = "Juiz Leyn, Juiz Matthieu, por favor, não faça declarações de caráter preponderante ao réu.",
  ui_story_5043_50430501_131_dialog_content = "Isto é um tribunal. Culpado significa culpado.",
  ui_story_5043_50430501_132_dialog_content = "Oh, mas Juiz Chefe Schwab... Você é tão bonito, tão popular entre as mulheres. Como você pode suportar interromper uma donzela tão bonita?",
  ui_story_5043_50430501_133_dialog_content = "E a prova do amor de uma dama por você está aqui, mas você não consegue perceber quem é essa dama.",
  ui_story_5043_50430501_134_dialog_content = "Oh! Eu acho que entendi. Você quer dizer que os cookies foram realmente destinados a...",
  ui_story_5043_50430501_135_dialog_content = "Hã?",
  ui_story_5043_50430501_136_dialog_content = "Ordem!",
  ui_story_5043_50430501_137_dialog_content = "Silêncio no tribunal! Eu desejo falar.",
  ui_story_5043_50430501_138_dialog_content = "Juiz Tina, você não pode interromper os negócios do tribunal assim!",
  ui_story_5043_50430501_139_dialog_content = "Juiz principal Schwab, como proprietário dos cookies de evidência, gostaria de fazer um <color=#FFB400>declaração de testemunha</color>.",
  ui_story_5043_50430501_140_dialog_content = "(Attagirl, Tina! Esse é o espírito!)",
  ui_story_5043_50430501_141_dialog_content = "O-Ok. O tribunal concorda. Você pode falar, testemunha.",
  ui_story_5043_50430501_142_dialog_content = "Eu fiz os biscoitos.",
  ui_story_5043_50430501_143_dialog_content = "Eu mesmo os fiz, com mãos amorosas e um coração palpitante.",
  ui_story_5043_50430501_144_dialog_content = "Bati a manteiga. Eu canalizei os designs bonitos. Assei-os até ficarem amarelos dourados e escolhi os mais bonitos.",
  ui_story_5043_50430501_145_dialog_content = "Tudo para que eu pudesse dar a ele um presente perfeito.",
  ui_story_5043_50430501_146_dialog_content = "Mas então eu perdi todos eles no Moonlight Salon.",
  ui_story_5043_50430501_147_dialog_content = "E esta carta é a prova!",
  ui_story_5043_50430501_148_dialog_content = "Eu mesmo fiz esse cartão. Posso dizer-lhe o nome no cartão e tudo o que está escrito nele.",
  ui_story_5043_50430501_149_dialog_content = "Oh! Realmente? É tão bizarro termos nos encontrado assim...",
  ui_story_5043_50430501_150_dialog_content = "É como uma linda história de amor.",
  ui_story_5043_50430501_151_dialog_content = "Não sei o que fazer com vocês, meus lindos. Vocês todos são um fardo encantador para eu carregar.",
  ui_story_5043_50430501_152_dialog_content = "Talvez a testemunha e o réu possam confirmar o que está escrito no cartão? Então podemos concluir este caso.",
  ui_story_5043_50430501_153_dialog_content = "OK. Vamos ler juntos.",
  ui_story_5043_50430501_154_dialog_content = "Boa ideia. Três. Dois. Um!",
  ui_story_5043_50430501_155_dialog_content = "<size=45><color=#FFB400>Totó</color>!</size>",
  ui_story_5043_50430501_X156_dialog_content = "Há?",
  ui_story_5043_50430501_156_dialog_content = "Quê?!",
  ui_story_5043_50430501_157_dialog_content = "Ora, Juiz Chefe Schwab, sempre ouvi falar de como você é famoso e elegante.",
  ui_story_5043_50430501_158_dialog_content = "Nunca imaginei que você teria um apelido tão fofo.",
  ui_story_5043_50430501_159_dialog_content = "Faz você parecer um pouco menos intimidador para nós, gente da Baixa Lumópolis.",
  ui_story_5043_50430501_160_dialog_content = "Querida, finalmente reconquistei sua confiança. *Soluçando*",
  ui_story_5043_50430501_161_dialog_content = "Totó. Heehee. Um nome tão fofo.",
  ui_story_5043_50430501_162_dialog_content = "Schwab, isso é um apelido de infância? Algo que sua mãe te chamou?",
  ui_story_5043_50430501_163_dialog_content = "Hahahahaha!",
  ui_story_5043_50430501_164_dialog_content = "Mas isso...",
  ui_story_5043_50430501_165_dialog_content = "Parar! O que exatamente está acontecendo!?",
  ui_story_5043_50430501_166_dialog_content = "Sim, o que está acontecendo?",
  ui_story_5043_50430501_167_dialog_content = "O que o cartão e os cookies têm a ver com o Juiz Chefe Schwab?",
  ui_story_5043_50430601_1_dialog_content = "Então... acho que foi isso que aconteceu.",
  ui_story_5043_50430601_2_dialog_content = "Fiz os biscoitos para o Totó. Mas parece que o réu teve a ideia errada...",
  ui_story_5043_50430601_3_dialog_content = "Nunca imaginei que algo assim aconteceria. Pelo menos esclarecemos o mal-entendido entre os dois amantes.",
  ui_story_5043_50430601_4_dialog_content = "Há?",
  ui_story_5043_50430601_5_dialog_content = "Eles não eram os únicos com um mal-entendido.",
  ui_story_5043_50430601_6_dialog_content = "Então, quem é esse Totó? Achamos que você gostou do nosso juiz idiota!",
  ui_story_5043_50430601_7_dialog_content = "Sim, embora isso nunca tenha feito muito sentido. Mas onde foi que erramos?",
  ui_story_5043_50430601_8_dialog_content = "É minha culpa. É uma situação embaraçosa, então eu estava sendo muito vago.",
  ui_story_5043_50430601_9_dialog_content = "Eu deveria ter explicado melhor as coisas antes de pedir ajuda a todos vocês.",
  ui_story_5043_50430601_10_dialog_content = "Embora eu não entenda como você entendeu errado, Schwab.",
  ui_story_5043_50430601_11_dialog_content = "Quase não nos falamos além do trabalho normal e do bate-papo social.",
  ui_story_5043_50430601_12_dialog_content = "Quero dizer, é óbvio quando alguém gosta de você, certo? Isso é apenas algo que as pessoas podem dizer.",
  ui_story_5043_50430601_13_dialog_content = "Suficiente. Por favor, não diga mais nada.",
  ui_story_5043_50430601_14_dialog_content = "Isso tudo é... irrelevante. O assunto importante em questão é...",
  ui_story_5043_50430601_15_dialog_content = "<size=45>Todos no Tribunal de Justiça acham que meu apelido é Totó!!!</size>",
  ui_story_5043_50430601_16_dialog_content = "<size=45>Judge Jr. e aqueles jurados assistentes do painel já devem ter contado para todo mundo!!!</size>",
  ui_story_5043_50430601_17_dialog_content = "<size=45>E logo todos os nobres da sociedade dos Jardins de Lumopolis saberão da notícia!!!</size>",
  ui_story_5043_50430601_18_dialog_content = "<size=45>E é tudo por sua causa e daqueles biscoitos idiotas e daquele cartão idiota!!!</size>",
  ui_story_5043_50430601_19_dialog_content = "<size=45>Vocês são um bando de idiotas viciados em amor! E mulheres problemáticas pegajosas...</size>",
  ui_story_5043_50430601_20_dialog_content = "<size=45>Vocês são todos iguais!</size>",
  ui_story_5043_50430601_21_dialog_content = "Sinto muito!",
  ui_story_5043_50430601_22_dialog_content = "Ei. Tina pode ter cometido um erro. Mas você está sendo muito duro com ela, Schwab.",
  ui_story_5043_50430601_23_dialog_content = "Não tenho certeza do que está acontecendo. estou aliviado Tina embora não tenha uma queda por Schwab.",
  ui_story_5043_50430601_24_dialog_content = "...",
  ui_story_5043_50430601_25_dialog_content = "Suspirar...",
  ui_story_5043_50430601_26_dialog_content = "Ok, vamos voltar aos negócios.",
  ui_story_5043_50430601_27_dialog_content = "A estátua quebrada no pátio de Lumopolis não tem nada a ver com o Sr. Byron.",
  ui_story_5043_50430601_28_dialog_content = "O que é uma sorte para você. Não quero vê-lo aparecer com novas acusações.",
  ui_story_5043_50430601_29_dialog_content = "Agora vá e prepare-se para a audiência do caso. Vá, fora!",
  ui_story_5043_50430601_30_dialog_content = "<color=#e8d9bb>Fora do Hall of Justice, Lumopolis Gardens</color>",
  ui_story_5043_50430601_31_dialog_content = "Pfft!",
  ui_story_5043_50430601_32_dialog_content = "Ei, vocês notaram a expressão de Schwab?",
  ui_story_5043_50430601_33_dialog_content = "Você foi ótimo, Tina. Tão implacável!",
  ui_story_5043_50430601_34_dialog_content = "Hehe. Aposto que ele nunca teve uma mulher falando com ele assim antes.",
  ui_story_5043_50430601_35_dialog_content = "Ah, por favor, não me provoque...",
  ui_story_5043_50430601_36_dialog_content = "Desculpe. Coloquei todos nós em apuros.",
  ui_story_5043_50430601_37_dialog_content = "Isso não importa. Mas o que eu quero saber é—",
  ui_story_5043_50430601_38_dialog_content = "Tina, você nos disse que conheceu esse homem no jardim da mansão de Schwab?",
  ui_story_5043_50430601_39_dialog_content = "Então, se não foi Schwab, quem foi?",
  ui_story_5043_50430601_40_dialog_content = "Oh, este terrível mal-entendido é tudo culpa minha.",
  ui_story_5043_50430601_41_dialog_content = "Deixa eu tentar explicar direitinho...",
  ui_story_5043_50430601_42_dialog_content = "Eu estava no jardim de Salar Manor. E eu encontrei Schwab. Ele estava sentado sozinho, lendo e bebendo chá.",
  ui_story_5043_50430601_43_dialog_content = "Ele me notou imediatamente e ficou surpreso que alguém aparecesse em um local tão isolado.",
  ui_story_5043_50430601_44_dialog_content = "Mas enquanto ele me notou, ele não percebeu que havia outro convidado inesperado por perto.",
  ui_story_5043_50430601_45_dialog_content = "Nos arbustos atrás de Schwab, vi a cabecinha peluda de Toto saindo das folhas. Ele estava tremendo enquanto olhava para mim.",
  ui_story_5043_50430601_46_dialog_content = "Acho que ele estava preocupado que eu revelasse seu esconderijo. Afinal, ninguém quer um Eclipsite em sua cerca viva.",
  ui_story_5043_50430601_47_dialog_content = "Mas ele era tão fofo e claramente inofensivo. A coitada havia se perdido naquele enorme jardim.",
  ui_story_5043_50430601_48_dialog_content = "Na verdade, eu até o vira afastar algumas moscas da xícara de chá de Schwab. Isso foi antes de Schwab me notar.",
  ui_story_5043_50430601_49_dialog_content = "Depois do Moonlight Salon, corri de volta para o jardim. Peguei sua mão e o conduzi em segurança para fora de Salar Manor.",
  ui_story_5043_50430601_50_dialog_content = "Eu tive que usar minhas novas luvas para garantir que meu Lumina e seu Darkflow não colidissem.",
  ui_story_5043_50430601_51_dialog_content = "Ele podia entender o universo, embora só pudesse dizer algumas palavras básicas. E no Mooncrown Day, pouco depois de nos conhecermos, recebi um presente dele.",
  ui_story_5043_50430601_52_dialog_content = "É isso. Essa é toda a história.",
  ui_story_5043_50430601_53_dialog_content = "(Uau. Até mesmo um pequeno Eclipsite comum tem um nome...)",
  ui_story_5043_50430601_54_dialog_content = "Espere. Você não disse nada sobre ele não responder às suas cartas?",
  ui_story_5043_50430601_55_dialog_content = "Bem, ele não terá endereço em Lumópolis, certo? Eu escrevi de volta para o endereço do remetente no presente, mas nunca ouvi nada de volta.",
  ui_story_5043_50430601_56_dialog_content = "E você disse que não teve a chance de marcar um encontro com ele?",
  ui_story_5043_50430601_57_dialog_content = "Sim. Nós não nos encontramos. Não consigo encontrá-lo em lugar nenhum.",
  ui_story_5043_50430601_58_dialog_content = "E quando você disse que ele é notado onde quer que vá...",
  ui_story_5043_50430601_59_dialog_content = "Certamente você pode entender isso. Um Eclipsite em Lumopolis está fadado a causar pânico.",
  ui_story_5043_50430601_60_dialog_content = "Então... quando você negou que estava apaixonado...",
  ui_story_5043_50430601_61_dialog_content = "Os eclipsitos vivem para atacar os aurorianos. Existe algo como um Eclipsite inofensivo?",
  ui_story_5043_50430601_62_dialog_content = "Se houver, adoraria ver um para mim.",
  ui_story_5043_50430601_63_dialog_content = "Acho que é algum tipo de sentimento desnecessário, sim. Mas é muito estranho chamar isso de amor.",
  ui_story_5043_50430601_64_dialog_content = "Eu não falaria sobre isso em termos românticos. Eu só quero cuidar dele.",
  ui_story_5043_50430601_64X1_dialog_content = "Mas de qualquer forma, também não suporto Eclipsites.",
  ui_story_5043_50430601_64X2_dialog_content = "*Onomatopeia de cheirar*",
  ui_story_5043_50430601_64X3_dialog_content = "Perder Tina, Não estou tentando alarmar ninguém, mas você parece ter o fedor de um Eclipsite sobre você.",
  ui_story_5043_50430601_64X4_dialog_content = "Huh? Você ainda pode sentir o cheiro depois de tanto tempo...? Desculpe...",
  ui_story_5043_50430601_65_dialog_content = "Como afirmei antes, a lei é a lei em Lumopolis. Eu não posso deixar isso passar.",
  ui_story_5043_50430601_66_dialog_content = "Não há sinal do Eclipsite que você mencionou em nenhuma das fichas de prisão dos guardas.",
  ui_story_5043_50430601_67_dialog_content = "Então, este assunto deve ser levado à sua conclusão aqui?",
  ui_story_5043_50430601_68_dialog_content = "Oh. Obrigado, senhora Carleen. E como parte do Tribunal de Justiça, conheço o que está em jogo.",
  ui_story_5043_50430601_69_dialog_content = "Para os aurorianos, adotar um Eclipsita não é uma fantasia incomum.",
  ui_story_5043_50430601_69X1_dialog_content = "Lamento ter causado tantos problemas a todos... Vamos voltar ao caso e tentar o nosso melhor para investigar mais.",
  ui_story_5043_50430601_69X2_dialog_content = "Não é como se tudo o que você trouxesse fossem problemas. Não aconteceu algo interessante como resultado de tudo isso?",
  ui_story_5043_50430601_70_dialog_content = "Tina, você... você realmente jogou todos na Divisão de Romance para tolos.",
  ui_story_5043_50430601_71_dialog_content = "Hahahahaha! Certo! Definitivamente, tomei a decisão certa quando escolhi trabalhar com você.",
  ui_story_5043_50430601_72_dialog_content = "Certamente encontrei muito mais do que esperava.",
  ui_story_5043_50430601_74_dialog_content = "haha. Bem, podemos não ter feito muito progresso com o caso, mas meus cookies definitivamente causaram algum entretenimento.",
  ui_story_5043_50430601_75_dialog_content = "Mas! Sinto o mesmo que todos vocês...",
  ui_story_5043_50430601_76_dialog_content = "<color=#e8d9bb>Bang—!</color>",
  ui_story_5043_50430601_77_dialog_content = "Tina!? Tina!",
  ui_story_5043_50430601_78_dialog_content = "O que há de errado com ela... Ei, não fique aí parado, venha ajudar!",
  ui_story_5043_50430601_79_dialog_content = "Ufa! Não se preocupe, ela acabou de dormir.",
  ui_story_5043_50430601_80_dialog_content = "Foi um dia muito emocionante. Ela devia estar exausta.",
  ui_story_5043_50430601_81_dialog_content = "Farei com que um de meus criados a pegue em uma carruagem e a leve para casa.",
  ui_story_5043_50430601_82_dialog_content = "Huff-Puff. Senhora Carleen...",
  ui_story_5043_50430601_83_dialog_content = "Ah, Loewe. Você terá que fazer melhor do que isso se quiser ser um servo de Salar.",
  ui_story_5043_50430601_84_dialog_content = "Desembucha!",
  ui_story_5043_50430601_85_dialog_content = "Senhora Carleen, você estava certo.",
  ui_story_5043_50430601_86_dialog_content = "Esses guardas estavam todos usando heráldica Troy.",
  ui_story_5043_50430601_87_dialog_content = "E há algo estranho no Moonlight Salon também.",
  ui_story_5043_50430601_88_dialog_content = "O quê?",
  ui_story_5043_50430601_89_dialog_content = "Sempre há um ataque de Eclipsite quando um desses salões termina.",
  ui_story_5043_50430601_90_dialog_content = "E a cabeça da estátua próxima sempre desaparece.",
  ui_story_5043_50430601_91_dialog_content = "Desculpe, foi tudo o que pude descobrir.",
  ui_story_5043_50430601_92_dialog_content = "...",
  ui_story_5043_50430601_93_dialog_content = "Você fez um ótimo trabalho, Loewe.",
  ui_story_5043_50430601_94_dialog_content = "E você poderá descansar em breve. Mas ainda não!",
  ui_story_5043_50430702_1_dialog_content = "Já que sabemos de onde vieram os guardas, não posso deixar por isso mesmo.",
  ui_story_5043_50430702_2_dialog_content = "PlayerName, preciso me encontrar com os Guardiões e decidir o que fazer a seguir.",
  ui_story_5043_50430702_3_dialog_content = "Então, precisarei atualizar o City Lord sobre os problemas recentes do Eclipsite.",
  ui_story_5043_50430702_4_dialog_content = "Vá então. Podemos lidar com as coisas aqui.",
  ui_story_5043_50430702_5_dialog_content = "OK. Falo com você antes da audiência, o mais tardar.",
  ui_story_5043_50430702_6_dialog_content = "Tomar cuidado.",
  ui_story_5043_50430702_7_dialog_content = "Todos nós tivemos um dia agitado. Devemos ir para casa e descansar.",
  ui_story_5043_50430702_8_dialog_content = "Quanto a amanhã...",
  ui_story_5043_50430702_9_dialog_content = "Bem, todos nós sabemos o que precisamos fazer, certo?",
  ui_story_5043_50430702_10_dialog_content = "Tenho certeza de que o organizador desses estranhos salões Moonlight estará no tribunal em breve.",
  ui_story_5043_50430702_11_dialog_content = "Parece que tem algo estranho acontecendo...",
  ui_story_5043_50430702_12_dialog_content = "Ouça, por que não vamos procurar aquela freira amanhã? Tudo o que precisamos fazer é seguir o balão.",
  ui_story_5043_50430702_13_dialog_content = "Alguém pode me dizer o que está acontecendo?",
  ui_story_5043_50430702_14_dialog_content = "E por que é Tina dormindo de novo?",
  ui_story_5043_50430702_15_dialog_content = "É uma longa história. Falo com você no caminho de volta.",
  ui_story_5043_50430702_16_dialog_content = "A carruagem está aqui. nós vamos levar Tina lar. PlayerName, Leyn, bem, até amanhã.",
  ui_story_5043_50430702_17_dialog_content = "Hã?",
  ui_story_5043_50430702_18_dialog_content = "O quê?",
  ui_story_5043_50430702_19_dialog_content = "Você não me chamou de plebeu pela primeira vez.",
  ui_story_5043_50430702_20_dialog_content = "Ah, cale a boca!",
  ui_story_5043_50430702_21_dialog_content = "<color=#e8d9bb>No dia seguinte</color>",
  ui_story_5043_50430702_22_dialog_content = "Ah, agora eu vejo.",
  ui_story_5043_50430702_23_dialog_content = "Você tem razão. Eu escolho os locais para nossos Salões Moonlight com muito cuidado.",
  ui_story_5043_50430702_24_dialog_content = "Eu gosto de lugares com um senso de cultura. Lugares com estátuas são ideais.",
  ui_story_5043_50430702_25_dialog_content = "Não me importo se as estátuas são de idosos, crianças, homens ou, como as duas que foram danificadas, mulheres.",
  ui_story_5043_50430702_26_dialog_content = "Eles são todos os blocos de construção da civilização de Lumopolis.",
  ui_story_5043_50430702_27_dialog_content = "Mas você não pode negar que os Moonlight Salons parecem estar causando danos às estátuas.",
  ui_story_5043_50430702_28_dialog_content = "Ah, não pretendo negar que as coisas andam meio caóticas. E obviamente eu estava por perto quando as estátuas foram danificadas.",
  ui_story_5043_50430702_29_dialog_content = "Mas posso jurar pela Noite Branca lá no alto que não tenho nada a ver com as estátuas danificadas ou os ataques do Eclipsite.",
  ui_story_5043_50430702_30_dialog_content = "(Esta freira certamente parece e soa calma e totalmente despreocupada.)",
  ui_story_5043_50430702_31_dialog_content = "(E ela tem uma aura tão poderosa. Talvez por causa de sua fé?)",
  ui_story_5043_50430702_32_dialog_content = "(Meus instintos me dizem que ela não tem nada a ver com nosso caso.)",
  ui_story_5043_50430702_33_dialog_content = "Tut. Outro beco sem saída, e acho que não podemos sair por aí prendendo pessoas com base em nossos palpites.",
  ui_story_5043_50430702_34_dialog_content = "Irmã, se tudo o que você diz é verdade...",
  ui_story_5043_50430702_35_dialog_content = "Você estaria disposto a comparecer à audiência como testemunha?",
  ui_story_5043_50430702_36_dialog_content = "Bem, estou correndo para organizar os Salões Moonlight, mas se é isso que o Tribunal de Justiça deseja, então sim.",
  ui_story_5043_50430702_37_dialog_content = "Farei tudo o que puder para ajudar.",
  ui_story_5043_50430702_38_dialog_content = "Mas...!",
  ui_story_5043_50430702_39_dialog_content = "(E se levá-la ao Tribunal de Justiça lhe causar mais problemas...)",
  ui_story_5043_50430702_40_dialog_content = "Sim? Moça, você tem algo a dizer?",
  ui_story_5043_50430702_41_dialog_content = "Eu só quero saber como você consegue ficar tão calmo.",
  ui_story_5043_50430702_42_dialog_content = "Não me oponho aos salões Moonlight. Eu gosto deles - eles fazem Lumopolis parecer um lugar diferente.",
  ui_story_5043_50430702_43_dialog_content = "Mas os costumes de Lumopolis não aceitam nem mesmo o divórcio. Muito menos amor livre.",
  ui_story_5043_50430702_44_dialog_content = "E como uma mulher de fé, alguém que é claramente muito devoto...",
  ui_story_5043_50430702_45_dialog_content = "Como você decidiu organizar esses salões para o povo de Lumópolis?",
  ui_story_5043_50430702_46_dialog_content = "E você não tem medo de colocar os pés dentro do Tribunal de Justiça? É tão... admirável.",
  ui_story_5043_50430702_47_dialog_content = "Tina...",
  ui_story_5043_50430702_48_dialog_content = "Heheh... Meu filho, talvez você esteja perguntando sobre suas próprias preocupações?",
  ui_story_5043_50430702_49_dialog_content = "O problema é que, quando você chega à minha idade, simplesmente para de se preocupar e pensar tanto.",
  ui_story_5043_50430702_50_dialog_content = "Tudo o que faço é ouvir a vontade do Deus da Luz.",
  ui_story_5043_50430702_51_dialog_content = "Ao longo de sua longa história, Lumopolis desenvolveu complexos sistemas de etiqueta para controlar nossos desejos.",
  ui_story_5043_50430702_52_dialog_content = "Mas originalmente foi fundada por homens e mulheres comuns. Aurorianos simples e puros.",
  ui_story_5043_50430702_53_dialog_content = "Ao longo dos anos, os ensinamentos do Deus da Luz foram reinterpretados continuamente.",
  ui_story_5043_50430702_54_dialog_content = "Mas, no fundo, esses ensinamentos são simples e gentis.",
  ui_story_5043_50430702_55_dialog_content = "E essa é a verdadeira bênção do Deus da Luz. Sua verdadeira lição.",
  ui_story_5043_50430702_56_dialog_content = "Tudo o que estou fazendo é levar os aurorianos de volta às suas origens, aos seus verdadeiros desejos.",
  ui_story_5043_50430702_57_dialog_content = "Não há pecado nisso. É apenas algo que nossas regras e costumes não entendem.",
  ui_story_5043_50430702_58_dialog_content = "Fé e amor... em suas raízes, eles são um.",
  ui_story_5043_50430702_59_dialog_content = "Acho que entendo. Muito obrigado.",
  ui_story_5043_50430702_60_dialog_content = "Então eu vou me despedir.",
  ui_story_5043_50430702_61_dialog_content = "E deixe-me saber se eu posso ajudar mais com sua investigação.",
  ui_story_5043_50430702_62_dialog_content = "Embora se eu pudesse oferecer uma pequena sugestão ao Tribunal de Justiça?",
  ui_story_5043_50430702_63_dialog_content = "Ai...?",
  ui_story_5043_50430702_64_dialog_content = "Se você realmente deseja saber mais antes do início da audiência no tribunal, em vez de simplesmente passar por seus processos...",
  ui_story_5043_50430702_65_dialog_content = "Então você terá que parar de trabalhar tão mecanicamente. Pense no que o autor realmente deseja.",
  ui_story_5043_50430702_66_dialog_content = "Obrigada pelo conselho. vamos pensar sobre isso...",
  ui_story_5043_50430702_67_dialog_content = "Claro. Isso é tudo. Até a próxima vez.",
  ui_story_5043_50430801_1_dialog_content = "<color=#e8d9bb>O dia seguinte</color>",
  ui_story_5043_50430801_2_dialog_content = "O que, isso é tudo que você encontrou?",
  ui_story_5043_50430801_3_dialog_content = "Então você não resolveu o caso original, mas conseguiu encontrar outra estátua sem cabeça!?",
  ui_story_5043_50430801_4_dialog_content = "Sinto muito. Ainda estamos investigando, mas não tivemos nenhum avanço até agora...",
  ui_story_5043_50430801_5_dialog_content = "Sem avanços!? Você não fez nenhum progresso!",
  ui_story_5043_50430801_6_dialog_content = "Isso é o melhor que o grande Tribunal de Justiça pode fazer?",
  ui_story_5043_50430801_7_dialog_content = "Eu também poderia entregar o caso para um cachorro cego. Talvez pudesse farejar o criminoso!",
  ui_story_5043_50430801_8_dialog_content = "Desculpe. vamos nos esforçar mais...",
  ui_story_5043_50430801_9_dialog_content = "Posso ver agora que o Tribunal de Justiça não tem interesse nos problemas românticos dos cidadãos.",
  ui_story_5043_50430801_10_dialog_content = "E esta \"Divisão Romance\" é apenas um lar para aproveitadores!",
  ui_story_5043_50430801_11_dialog_content = "Todos recebendo pacotes gordos e trabalhando duro - dormindo!",
  ui_story_5043_50430801_12_dialog_content = "Não posso negar que temos tais funcionários.",
  ui_story_5043_50430801_13_dialog_content = "M-Mas dormir me ajuda a trabalhar melhor...",
  ui_story_5043_50430801_14_dialog_content = "Estou perdendo minha paciência. A audiência é em dois dias!",
  ui_story_5043_50430801_15_dialog_content = "Não direi mais nada agora. Se você não conseguir encontrar algo novo amanhã, não terei escolha a não ser continuar processando meu vizinho.",
  ui_story_5043_50430801_16_dialog_content = "E eu estarei reclamando com Lady Irridon!",
  ui_story_5043_50430801_17_dialog_content = "Qual é o sentido de pagar tanto a vocês se vocês não podem resolver nossos problemas? Ora, Lumopolis ficaria melhor se demolissemos o prédio inteiro!",
  ui_story_5043_50430801_18_dialog_content = "Demolir?",
  ui_story_5043_50430801_19_dialog_content = "Ei, isso é um pouco duro, não é?",
  ui_story_5043_50430801_20_dialog_content = "Sr. Byron, por favor, não seja precipitado.",
  ui_story_5043_50430801_21_dialog_content = "Hmph. Todos vocês precisam fazer melhor!",
  ui_story_5043_50430801_22_dialog_content = "H-Ele se foi.",
  ui_story_5043_50430801_23_dialog_content = "Isto não é bom. A Divisão Romance pode estar com mais problemas do que eu pensava.",
  ui_story_5043_50430801_24_dialog_content = "Ótimo. Nós terminamos por agora.",
  ui_story_5043_50430801_25_dialog_content = "Juiz principal Irridon odeia feedback ruim do público. Se ela receber uma reclamação...",
  ui_story_5043_50430801_26_dialog_content = "Sim, ela vai ficar muito zangada.",
  ui_story_5043_50430801_27_dialog_content = "E este é apenas um arranjo temporário. Se o chefe decidir que a Divisão Romance não está fazendo seu trabalho...",
  ui_story_5043_50430801_28_dialog_content = "Podemos perder tudo isso.",
  ui_story_5043_50430801_29_dialog_content = "Acho que estava certo antes...",
  ui_story_5043_50430801_30_dialog_content = "Do jeito que as coisas estão, vocês realmente podem perder seus empregos.",
  ui_story_5043_50430801_31_dialog_content = "Perder nossos empregos!?",
  ui_story_5043_50430801_32_dialog_content = "Isso não pode acontecer. E as coisas não são tão ruins assim!",
  ui_story_5043_50430801_33_dialog_content = "P-Por favor, nem sugira isso.",
  ui_story_5043_50430801_34_dialog_content = "Se eu perdesse meu emprego, morreria de tédio ficando em casa o dia todo. Eu não podia sair e me divertir!",
  ui_story_5043_50430801_35_dialog_content = "Espere, é só com isso que você está preocupado? Se divertindo?",
  ui_story_5043_50430801_36_dialog_content = "Onde vou encontrar um lugar tranquilo o suficiente para dormir durante o dia?",
  ui_story_5043_50430801_37_dialog_content = "Você não deveria estar dormindo no trabalho!",
  ui_story_5043_50430801_38_dialog_content = "E se eu não tiver emprego, eles me obrigarão a voltar para casa.",
  ui_story_5043_50430801_39_dialog_content = "Eles vão me forçar a entrar nos negócios da família.",
  ui_story_5043_50430801_40_dialog_content = "Sim. Isso é famílias. Nada além de um monte de velhos antiquados chatos.",
  ui_story_5043_50430801_41_dialog_content = "Quem no mundo gostaria de sentar lá ajudando-os a contar seu Nightium?",
  ui_story_5043_50430801_42_dialog_content = "Eu posso ver que vocês, nobres, não precisam que eu me preocupe com vocês...",
  ui_story_5043_50430801_43_dialog_content = "E daí se você perder seus empregos? Você vai ficar bem! Anime-se, todos.",
  ui_story_5043_50430801_44_dialog_content = "Sim. Mesmo que percamos nossos empregos, a vida continuará.",
  ui_story_5043_50430801_45_dialog_content = "Embora sem salário... Vou precisar estocar batatas e vegetais.",
  ui_story_5043_50430801_46_dialog_content = "E reduzir para uma refeição por dia.",
  ui_story_5043_50430801_47_dialog_content = "Espere, como é que as coisas ficam tão sombrias quando chegamos até você?",
  ui_story_5043_50430801_48_dialog_content = "Porque a vida em Lumopolis é sombria, é por isso.",
  ui_story_5043_50430801_49_dialog_content = "Comprando comida, acompanhando a sociedade. Viver não é de graça, você sabe.",
  ui_story_5043_50430801_50_dialog_content = "Se eu perder meu salário, preciso começar a contar cada centavo.",
  ui_story_5043_50430801_51_dialog_content = "Uau. A vida é dura...",
  ui_story_5043_50430801_52_dialog_content = "Mas ainda não é hora de desistir! Ainda temos um dia. Façamos bom uso dela!",
  ui_story_5043_50430801_53_dialog_content = "Sim. Se realmente fizermos algo, podemos fazer algum progresso.",
  ui_story_5043_50430801_54_dialog_content = "Mas o problema é que não temos uma única pista a seguir.",
  ui_story_5043_50430801_55_dialog_content = "Que linha de investigação devemos seguir?",
  ui_story_5043_50430801_56_dialog_content = "Senhoras e senhores... Tive uma ideia!",
  ui_story_5043_50430801_57_dialog_content = "Eu estive pensando sobre as coisas. Nossa abordagem tem sido muito estreita.",
  ui_story_5043_50430801_58_dialog_content = "O caso de decapitação da estátua em série não é um crime comum.",
  ui_story_5043_50430801_59_dialog_content = "As vítimas são estátuas. Isso significa que não podemos olhar para seus círculos sociais para encontrar alguém com um motivo.",
  ui_story_5043_50430801_60_dialog_content = "Da mesma forma, não há chance de encontrar o autor do crime entre os familiares da vítima.",
  ui_story_5043_50430801_61_dialog_content = "Verdadeiro. Esses fatores dificultam nossas investigações.",
  ui_story_5043_50430801_62_dialog_content = "Mas vamos pensar fora da caixa por um momento.",
  ui_story_5043_50430801_63_dialog_content = "Há um fator crucial que fez com que os danos às estátuas se tornassem um caso aqui no tribunal...",
  ui_story_5043_50430801_64_dialog_content = "<color=#FFB400>Amor</color>!",
  ui_story_5043_50430801_65_dialog_content = "Sim. É o amor que torna este caso para a Divisão Romance.",
  ui_story_5043_50430801_66_dialog_content = "E quando o amor está envolvido, não é mais possível adotar uma abordagem puramente lógica.",
  ui_story_5043_50430801_67_dialog_content = "Não estamos diante de nenhum caso comum. Este é um assunto do coração.",
  ui_story_5043_50430801_68_dialog_content = "Oh! Oh! Assim fica tudo mais claro!",
  ui_story_5043_50430801_69_dialog_content = "Espere. Não tenho certeza se acompanho...",
  ui_story_5043_50430801_70_dialog_content = "... Vocês conseguem se ouvir?",
  ui_story_5043_50430801_71_dialog_content = "Não temos nenhuma pista. Mas talvez não precisemos de pistas.",
  ui_story_5043_50430801_72_dialog_content = "Meus queridos amigos, quando se trata de amor não é necessário entender tudo.",
  ui_story_5043_50430801_73_dialog_content = "O importante é o coração.",
  ui_story_5043_50430801_74_dialog_content = "Pense no que aquela freira disse.",
  ui_story_5043_50430801_75_dialog_content = "\"Se você realmente deseja aprender mais antes do início da audiência, em vez de simplesmente passar por seus processos...",
  ui_story_5043_50430801_76_dialog_content = "Então você terá que parar de trabalhar tão mecanicamente. Pense no que o queixoso realmente quer.\"",
  ui_story_5043_50430801_77_dialog_content = "E podemos resolver o caso com... coração?",
  ui_story_5043_50430801_78_dialog_content = "Ao trabalho, amigos!",
  ui_story_5043_50430801_79_dialog_content = "Encontraremos as respostas que o autor precisa, com amor!",
  ui_story_5043_50430801_80_dialog_content = "<color=#e8d9bb>No dia seguinte</color>",
  ui_story_5043_50430801_81_dialog_content = "Ei, por que você está bloqueando o caminho?",
  ui_story_5043_50430801_82_dialog_content = "Me deixar entrar!",
  ui_story_5043_50430801_83_dialog_content = "Por favor, espere um momento, Sr. Byron.",
  ui_story_5043_50430801_84_dialog_content = "Os juízes estão ocupados no tribunal.",
  ui_story_5043_50430801_85_dialog_content = "Vamos deixá-lo passar assim que eles tiverem tempo para falar com você.",
  ui_story_5043_50430801_86_dialog_content = "Ocupado? Não seja ridículo. Eles estão ocupados com o meu caso!",
  ui_story_5043_50430801_87_dialog_content = "Se eles querem se esconder de mim, eles podem pelo menos inventar uma desculpa melhor!",
  ui_story_5043_50430801_88_dialog_content = "Sr. Byron, os juízes são mesmo...",
  ui_story_5043_50430801_89_dialog_content = "Eu não me importo com o que eles estão fazendo. Este é o horário de funcionamento do tribunal.",
  ui_story_5043_50430801_90_dialog_content = "S-Senhor, por favor, espere!",
  ui_story_5043_50430801_91_dialog_content = "Afaste-se!",
  ui_story_5043_50430801_92_dialog_content = "Ah, mas...",
  ui_story_5043_50430801_93_dialog_content = "<size=45>Juiz Matthieu! Ele entrou!!!</size>",
  ui_story_5043_50430801_94_dialog_content = "<color=#e8d9bb>Pop! Pop! Pop!</color>",
  ui_story_5043_50430801_95_dialog_content = "Parabéns, Sr. Byron!",
  ui_story_5043_50430801_96_dialog_content = "Estou tão feliz por vocês dois!",
  ui_story_5043_50430801_97_dialog_content = "Como é maravilhoso para você se reunir com seu verdadeiro amor neste dia comum!",
  ui_story_5043_50430801_98_dialog_content = "Huh? Isto é...",
  ui_story_5043_50430801_99_dialog_content = "Demoramos um dia inteiro, mas fizemos uma nova cabeça para sua estátua.",
  ui_story_5043_50430801_100_dialog_content = "Se tivéssemos tido um pouco mais de tempo, teríamos feito com que parecesse ainda melhor!",
  ui_story_5043_50430801_101_dialog_content = "Sim. Percebemos que precisávamos de uma abordagem mais romântica e essa foi a nossa solução.",
  ui_story_5043_50430801_102_dialog_content = "A questão não é o que você perdeu. É o que você ainda pode conseguir.",
  ui_story_5043_50430801_103_dialog_content = "Afinal, certamente a perda de uma mera cabeça não vai atrapalhar o seu amor?",
  ui_story_5043_50430801_104_dialog_content = "Não. Você ainda precisa amar. Mas era compreensível que sua incompletude o entristecesse.",
  ui_story_5043_50430801_105_dialog_content = "E para tirar essa tristeza do seu coração, tivemos que torná-la completa mais uma vez.",
  ui_story_5043_50430801_106_dialog_content = "Hehe. Um belo conto de perda e recuperação...",
  ui_story_5043_50430801_107_dialog_content = "V-Você...",
  ui_story_5043_50430801_108_dialog_content = "<size=45>O que diabos você fez!?</size>",
  ui_story_5043_50430801_109_dialog_content = "O que é aquele nódulo horrível no pescoço de Galatea? Você está tentando me insultar?",
  ui_story_5043_50430801_110_dialog_content = "Esse? Horrível?",
  ui_story_5043_50430801_111_dialog_content = "Você não parece satisfeito...",
  ui_story_5043_50430801_112_dialog_content = "Tut. Eu sabia que não deveríamos confiar em um plebeu em questões de estética.",
  ui_story_5043_50430801_113_dialog_content = "Se você não está feliz com a nova aparência dela, podemos fazer outra...",
  ui_story_5043_50430801_114_dialog_content = "Pare com isso! Seus idiotas zombaram do meu amor!",
  ui_story_5043_50430801_115_dialog_content = "O que você saberia sobre o amor verdadeiro!?",
  ui_story_5043_50430801_116_dialog_content = "O amor é único e verdadeiro! O amor é uma escolha que nunca pode mudar!",
  ui_story_5043_50430801_117_dialog_content = "E quando Galatea perdeu a cabeça, meu amor morreu!",
  ui_story_5043_50430801_118_dialog_content = "Mesmo que você pudesse produzir uma réplica exata de sua cabeça, ela não seria minha Galatea!",
  ui_story_5043_50430801_119_dialog_content = "Ela não seria a pessoa que eu amava!",
  ui_story_5043_50430801_120_dialog_content = "Ah. Então é assim que funciona...",
  ui_story_5043_50430801_121_dialog_content = "Erm, então eu entendi mal?",
  ui_story_5043_50430801_122_dialog_content = "Falhamos. Acho que a Divisão Romance está condenada...",
  ui_story_5043_50430801_123_dialog_content = "Oh, não importa tudo isso por enquanto.",
  ui_story_5043_50430801_124_dialog_content = "Tenho coisas mais importantes para discutir com você.",
  ui_story_5043_50430801_125_dialog_content = "Meu <color=#FFB400>esposa</color> está em perigo mortal neste exato momento.",
  ui_story_5043_50430801_126_dialog_content = "Pelo bem do nosso amor, imploro que enviem pessoas para protegê-la!",
  ui_story_5043_50430801_127_dialog_content = "E-espere! Sua esposa está em perigo mortal?",
  ui_story_5043_50430801_128_dialog_content = "Esta não é sua esposa?",
  ui_story_5043_50430801_129_dialog_content = "Não, você entendeu errado. Galatea é minha <color=#FFB400>amante</color>!",
  ui_story_5043_50430801_130_dialog_content = "A pessoa em perigo mortal é minha <color=#FFB400>esposa</color>. Eles não são a mesma pessoa.",
  ui_story_5043_50430801_131_dialog_content = "Quê?!",
  ui_story_5043_50430801_132_dialog_content = "Sua esposa e seu amante são pessoas diferentes?",
  ui_story_5043_50430801_133_dialog_content = "Minha esposa é uma estátua linda diferente. Ela se chama Afrodite.",
  ui_story_5043_50430801_134_dialog_content = "E o que aconteceu com o amor sendo único e verdadeiro?",
  ui_story_5043_50430801_135_dialog_content = "Claro que é!",
  ui_story_5043_50430801_136_dialog_content = "Então, como você está apaixonado por duas estátuas diferentes?",
  ui_story_5043_50430801_137_dialog_content = "O amor também é vasto e receptivo.",
  ui_story_5043_50430801_138_dialog_content = "Eu amo minha esposa. E eu amo meu amante. Dois amores diferentes e únicos.",
  ui_story_5043_50430801_139_dialog_content = "Considere isto. Você ama sua mãe, não é? E você também ama seu pai?",
  ui_story_5043_50430801_140_dialog_content = "Acho que isso faz um certo sentido...",
  ui_story_5043_50430801_141_dialog_content = "Isso não! Esses são tipos de relacionamentos completamente diferentes.",
  ui_story_5043_50430801_142_dialog_content = "Olha, não tenho tempo para educar vocês, filhos, sobre a natureza do amor.",
  ui_story_5043_50430801_143_dialog_content = "Acabei de ver o balão-lua flutuando acima da Escada para os Céus.",
  ui_story_5043_50430801_144_dialog_content = "E é lá que minha esposa está.",
  ui_story_5043_50430801_145_dialog_content = "Você já sabe que balão significa que haverá um Salão Luar. E um Moonlight Salon significa que uma estátua perderá a cabeça.",
  ui_story_5043_50430801_146_dialog_content = "E se alguma coisa acontecer com minha esposa... Não terei mais ninguém para amar.",
  ui_story_5043_50430801_147_dialog_content = "Certamente é seu dever proteger o direito dos cidadãos ao amor?",
  ui_story_5043_50430801_148_dialog_content = "Bem, nós aceitamos o seu caso. Então eu acho que precisamos proteger seu amor.",
  ui_story_5043_50430801_149_dialog_content = "Tut, ou metade de seu amor, pelo menos.",
  ui_story_5043_50430801_150_dialog_content = "E há uma chance de encontrarmos uma nova pista para nos ajudar em nosso caso.",
  ui_story_5043_50430801_151_dialog_content = "Temos que ir para resolver o caso de decapitação da estátua em série.",
  ui_story_5043_50430801_152_dialog_content = "Então, o que você está esperando? Mover!",
  ui_story_5043_50430801_153_dialog_content = "O Moonlight Salon está prestes a começar!",
  ui_story_5043_50430801_154_dialog_content = "<color=#e8d9bb>Pátio de Lumopolis, perto da Escadaria para os Céus</color>",
  ui_story_5043_50430801_155_dialog_content = "Ai estamos quase lá.",
  ui_story_5043_50430801_156_dialog_content = "O Sr. Byron disse que sua esposa estava aqui. Então ela deve ser...",
  ui_story_5043_50430801_157_dialog_content = "Entendi. Deve ser este!",
  ui_story_5043_50430801_158_dialog_content = "Oh. E ainda intacto.",
  ui_story_5043_50430801_159_dialog_content = "Então tudo o que precisamos fazer é proteger a estátua?",
  ui_story_5043_50430801_160_dialog_content = "Sim. O criminoso pode tentar golpear durante o salão.",
  ui_story_5043_50430801_161_dialog_content = "Mas onde estão todos os frequentadores de salão?",
  ui_story_5043_50430801_162_dialog_content = "Eu vejo eles. Eles estão todos na parte inferior da escada.",
  ui_story_5043_50430801_163_dialog_content = "Então eles são. Eles não estão subindo?",
  ui_story_5043_50430801_164_dialog_content = "Ah, isso significa que tivemos sorte.",
  ui_story_5043_50430801_165_dialog_content = "Se o salão for lá embaixo, será mais fácil proteger uma estátua aqui em cima.",
  ui_story_5043_50430801_166_dialog_content = "Incrível. Podemos fazer o que o Sr. Byron pediu.",
  ui_story_5043_50430801_167_dialog_content = "Oh, vejo que os juízes estão aqui.",
  ui_story_5043_50430801_168_dialog_content = "Irmã! Não esperava vê-lo novamente tão cedo.",
  ui_story_5043_50430801_169_dialog_content = "Onde mais você esperaria me encontrar, senão sob o balão da lua?",
  ui_story_5043_50430801_170_dialog_content = "E agora que você está aqui, por que não participar das comemorações?",
  ui_story_5043_50430801_171_dialog_content = "O salão está sendo realizado na parte inferior da escada?",
  ui_story_5043_50430801_172_dialog_content = "Adoraríamos ajudar, mas temos um...",
  ui_story_5043_50430801_173_dialog_content = "Oh não. O evento de hoje não é um salão.",
  ui_story_5043_50430801_174_dialog_content = "Huh? E daí...",
  ui_story_5043_50430801_175_dialog_content = "<size=45>Todos estão prontos?</size>",
  ui_story_5043_50430801_176_dialog_content = "<size=45>Que comece o desfile!</size>",
  ui_story_5043_50430901_1_dialog_content = "Estamos aqui para cantar em louvor ao amor! ♪",
  ui_story_5043_50430901_2_dialog_content = "Aqui na sagrada Lumópolis! ♪",
  ui_story_5043_50430901_3_dialog_content = "Aqui à vista de todos os apaixonados! ♪",
  ui_story_5043_50430901_4_dialog_content = "Cante em louvor da verdadeira beleza do amor! ♪",
  ui_story_5043_50430901_5_dialog_content = "Cantamos em louvor ao amor! ♪",
  ui_story_5043_50430901_6_dialog_content = "Cante em louvor ao amor! ♪",
  ui_story_5043_50430901_7_dialog_content = "Marchadores... marcha!",
  ui_story_5043_50430901_8_dialog_content = "Uau? Há uma enorme multidão de pessoas subindo as escadas.",
  ui_story_5043_50430901_9_dialog_content = "Isso não é bom, certo?",
  ui_story_5043_50430901_10_dialog_content = "Sim. Se eles passarem pela estátua, será mais difícil mantê-la segura.",
  ui_story_5043_50430901_11_dialog_content = "E se a estátua ficar danificada debaixo do seu nariz novamente, seus empregos estarão perdidos.",
  ui_story_5043_50430901_12_dialog_content = "Precisamos descobrir uma maneira de parar o desfile.",
  ui_story_5043_50430901_13_dialog_content = "Parar o desfile? Por que, fizemos algo errado?",
  ui_story_5043_50430901_14_dialog_content = "Isso exigiu muita organização. Você não pode impedi-lo de prosseguir sem um bom motivo.",
  ui_story_5043_50430901_15_dialog_content = "Eles estão se movendo rapidamente. Não temos muito tempo.",
  ui_story_5043_50430901_16_dialog_content = "Vou tentar impedi-los. Você explica para a freira!",
  ui_story_5043_50430901_17_dialog_content = "Oh, por que os plebeus são sempre tão apressados...",
  ui_story_5043_50430901_18_dialog_content = "Irmã, ouça. Não queremos parar o desfile.",
  ui_story_5043_50430901_19_dialog_content = "Mas precisamos. Por amor.",
  ui_story_5043_50430901_20_dialog_content = "Amor?",
  ui_story_5043_50430901_21_dialog_content = "Alguém vai usar o desfile como disfarce para cometer um crime.",
  ui_story_5043_50430901_22_dialog_content = "E tenho certeza que você não quer que seus eventos tenham a reputação de causar desgosto, certo?",
  ui_story_5043_50430901_23_dialog_content = "Nós! Louvar! Amor!",
  ui_story_5043_50430901_24_dialog_content = "Livre! Amor!",
  ui_story_5043_50430901_25_dialog_content = "Uau! Segure-se, todos!",
  ui_story_5043_50430901_26_dialog_content = "Acho que estamos indo pelo caminho errado.",
  ui_story_5043_50430901_27_dialog_content = "Deveríamos estar indo para o bairro residencial no Pátio de Lumopolis!",
  ui_story_5043_50430901_28_dialog_content = "Precisamos dar a volta por cima e voltar.",
  ui_story_5043_50430901_29_dialog_content = "Sim! Volte!",
  ui_story_5043_50430901_30_dialog_content = "Huh? Estamos indo pelo caminho errado?",
  ui_story_5043_50430901_31_dialog_content = "Isso não está certo. Disseram-nos para subirmos juntos a Escadaria para os Céus.",
  ui_story_5043_50430901_32_dialog_content = "Devemos ter entendido errado. Talvez alguém tenha ouvido mal as instruções.",
  ui_story_5043_50430901_33_dialog_content = "O bairro residencial?",
  ui_story_5043_50430901_34_dialog_content = "Ouvi dizer que era a praça do Pátio de Lumópolis!",
  ui_story_5043_50430901_35_dialog_content = "Isso é milhas de distância! Apresse-se, vamos virar e seguir em frente!",
  ui_story_5043_50430901_36_dialog_content = "Exatamente! Vire-se e vá em frente!",
  ui_story_5043_50430901_37_dialog_content = "Volte? Mas chegamos tão longe...",
  ui_story_5043_50430901_38_dialog_content = "Sim!",
  ui_story_5043_50430901_39_dialog_content = "Mas deveríamos ir para o bairro residencial.",
  ui_story_5043_50430901_40_dialog_content = "Não! É a praça!",
  ui_story_5043_50430901_41_dialog_content = "Aguentar. Lembro-me muito claramente de ter ouvido que íamos subir a Stairway to the Skies.",
  ui_story_5043_50430901_42_dialog_content = "Certo! E se não, por que todos nós nos encontramos no final da escada?",
  ui_story_5043_50430901_43_dialog_content = "Vocês que querem ir para o bairro residencial ou para a praça, onde conseguiram suas informações?",
  ui_story_5043_50430901_44_dialog_content = "Um cara com cabelo branco amarrado em um rabo de cavalo. Ele parecia confiável.",
  ui_story_5043_50430901_45_dialog_content = "Um cara de aparência confiável com cabelo branco preso em um rabo de cavalo.",
  ui_story_5043_50430901_46_dialog_content = "Ei, é a mesma pessoa. Você foi enganado!",
  ui_story_5043_50430901_47_dialog_content = "O quê?!",
  ui_story_5043_50430901_48_dialog_content = "Ei, é ele! Olha, ele tem cabelo branco e rabo de cavalo!",
  ui_story_5043_50430901_49_dialog_content = "O que? Meu? Não, estou só de passagem...",
  ui_story_5043_50430901_50_dialog_content = "Esse é ele!",
  ui_story_5043_50430901_51_dialog_content = "Ele é o único que me disse!",
  ui_story_5043_50430901_52_dialog_content = "Então, quem é esse estranho tentando arruinar nossa Parada do Amor?",
  ui_story_5043_50430901_53_dialog_content = "Leve-o para a Divisão Romance!",
  ui_story_5043_50430901_54_dialog_content = "T-Não precisa. Eu vou lá de qualquer maneira...",
  ui_story_5043_50430901_55_dialog_content = "Vamos! Continue subindo os degraus!",
  ui_story_5043_50430901_56_dialog_content = "E não deixe esse cara fugir.",
  ui_story_5043_50430901_57_dialog_content = "(Droga. Minha ideia brilhante não foi tão boa quanto eu esperava.)",
  ui_story_5043_50430901_58_dialog_content = "(E o povo partiu de novo. O que devo fazer?)",
  ui_story_5043_50430901_59_dialog_content = "Oh querido, oh querido! Derrubei os baldes de leite e mel!",
  ui_story_5043_50430901_60_dialog_content = "Nossa, que homem desajeitado eu sou.",
  ui_story_5043_50430901_61_dialog_content = "O que? Olha o leite caindo escada abaixo.",
  ui_story_5043_50430901_62_dialog_content = "De onde no mundo isso veio?",
  ui_story_5043_50430901_63_dialog_content = "E por que tem mel misturado no leite!?",
  ui_story_5043_50430901_64_dialog_content = "(I-Isso parece uma das estratégias mais diretas de Matthieu!)",
  ui_story_5043_50430901_65_dialog_content = "(Foi uma ideia estranha, mas parece ter funcionado. As pessoas pararam.)",
  ui_story_5043_50430901_66_dialog_content = "Uau. Tudo parece estar dando errado hoje.",
  ui_story_5043_50430901_67_dialog_content = "Não podemos desistir. Como diz o Deus da Luz, o caminho para a terra abençoada é de provação e tribulação!",
  ui_story_5043_50430901_68_dialog_content = "Exatamente! O leite e o mel simplesmente mostram que estamos no caminho certo!",
  ui_story_5043_50430901_69_dialog_content = "Continuem em frente, todos. Mas cuidado para não escorregar.",
  ui_story_5043_50430901_70_dialog_content = "(Eles começaram de novo?)",
  ui_story_5043_50430901_71_dialog_content = "(Eles com certeza são um grupo determinado...)",
  ui_story_5043_50430901_72_dialog_content = "<size=45>Ahhh!</size>",
  ui_story_5043_50430901_73_dialog_content = "<size=45>As escadas são tão escorregadias!!!</size>",
  ui_story_5043_50430901_74_dialog_content = "O que está acontecendo?",
  ui_story_5043_50430901_75_dialog_content = "Acho que alguém caiu.",
  ui_story_5043_50430901_76_dialog_content = "Boo-hoo... dói mesmo...",
  ui_story_5043_50430901_77_dialog_content = "Estou vendo estrelas, mesmo que seja de dia.",
  ui_story_5043_50430901_78_dialog_content = "S-Ela parece gravemente ferida.",
  ui_story_5043_50430901_79_dialog_content = "Esses passos são meio perigosos agora...",
  ui_story_5043_50430901_80_dialog_content = "Talvez... devêssemos encerrar por hoje?",
  ui_story_5043_50430901_81_dialog_content = "Sim. Podemos desfilar em outro lugar.",
  ui_story_5043_50430901_82_dialog_content = "Não fique aí parado bloqueando o caminho. Encontre alguém para levar essa pobre garota ao médico.",
  ui_story_5043_50430901_83_dialog_content = "Eles estão caindo para trás!",
  ui_story_5043_50430901_84_dialog_content = "Excelente desempenho, Tina!",
  ui_story_5043_50430901_85_dialog_content = "Sim, muito convincente!",
  ui_story_5043_50430901_86_dialog_content = "Heehee. Se eu perder meu emprego no Tribunal de Justiça, talvez suba ao palco.",
  ui_story_5043_50430901_87_dialog_content = "E o meu truque? Inteligente, hein?",
  ui_story_5043_50430901_88_dialog_content = "Foi incrível. Simplesmente perfeito.",
  ui_story_5043_50430901_89_dialog_content = "Vocês crianças... isso foi outra coisa.",
  ui_story_5043_50430901_90_dialog_content = "Mas como era tudo para proteger a reputação desses eventos, que assim seja.",
  ui_story_5043_50430901_91_dialog_content = "Todo amor é digno de proteção. Mesmo o amor de uma estátua.",
  ui_story_5043_50430901_92_dialog_content = "Eu posso ver porque você administra seus salões. Obrigado por ser tão compreensiva, irmã.",
  ui_story_5043_50430901_93_dialog_content = "Eu tenho que ir. Vou guiar as pessoas do desfile em uma direção diferente.",
  ui_story_5043_50430901_94_dialog_content = "E faremos o nosso melhor em nossos trabalhos também.",
  ui_story_5043_50430901_95_dialog_content = "Oh não! Todos, parem!",
  ui_story_5043_50430901_96_dialog_content = "Precisamos voltar para as escadas!",
  ui_story_5043_50430901_97_dialog_content = "O que está acontecendo? Há algum tipo de comoção!",
  ui_story_5043_50430901_98_dialog_content = "Eclipsos! De onde eles vieram!?",
  ui_story_5043_50430901_99_dialog_content = "Rápido! Suba as escadas!",
  ui_story_5043_50430901_100_dialog_content = "O que? De onde vieram esses eclipsitos?",
  ui_story_5043_50430901_101_dialog_content = "Eu vejo eles! Apenas alguns, no entanto.",
  ui_story_5043_50430901_102_dialog_content = "Leyn já está lidando com eles!",
  ui_story_5043_50430901_103_dialog_content = "Vamos ajudá-lo, stat!",
  ui_story_5043_50430901_104_dialog_content = "Não se esqueça da estátua! Essa multidão está prestes a debandar.",
  ui_story_5043_50430901_105_dialog_content = "São apenas alguns Eclipsitos. Uma pessoa extra deve ser suficiente.",
  ui_story_5043_50430901_106_dialog_content = "Tina, você vai ajudar Leyn. Todos os outros ficam aqui com a estátua.",
  ui_story_5043_50430901_107_dialog_content = "Vou usar minhas habilidades psíquicas para ajudá-lo a lutar contra os Eclipsites, Tina.",
  ui_story_5043_50430901_108_dialog_content = "Ok, parece bom.",
  ui_story_5043_50430901_109_dialog_content = "Vocês, cuidem da estátua!",
  ui_story_5043_50431001_1_dialog_content = "Esse é o último ali!",
  ui_story_5043_50431001_2_dialog_content = "Deixe para mim!",
  ui_story_5043_50431001_3_dialog_content = "OK. Isso é tudo o que os Eclipsites trataram.",
  ui_story_5043_50431001_4_dialog_content = "Mas... parece que todas as pessoas subiram as escadas correndo.",
  ui_story_5043_50431001_5_dialog_content = "me pergunto como PlayerName e os outros estão fazendo.",
  ui_story_5043_50431001_6_dialog_content = "Ei! Tenham cuidado todos!",
  ui_story_5043_50431001_7_dialog_content = "Há uma estátua muito valiosa aqui. Você quebrou, você comprou!",
  ui_story_5043_50431001_8_dialog_content = "Eclipsos! O que você está esperando!? Correr!",
  ui_story_5043_50431001_9_dialog_content = "Todos podem parar de entrar em pânico! Os Eclipsites foram resolvidos!",
  ui_story_5043_50431001_10_dialog_content = "<color=#e8d9bb>Tum!</color>",
  ui_story_5043_50431001_11_dialog_content = "O que está acontecendo?",
  ui_story_5043_50431001_12_dialog_content = "Oh não! Alguém colidiu com a estátua!",
  ui_story_5043_50431001_13_dialog_content = "Felizmente, não parece estar danificado.",
  ui_story_5043_50431001_14_dialog_content = "Ahhhhhh!",
  ui_story_5043_50431001_15_dialog_content = "Eles estão voltando!",
  ui_story_5043_50431001_16_dialog_content = "Matthieu, pare-os!",
  ui_story_5043_50431001_17_dialog_content = "Claro, mas como...",
  ui_story_5043_50431001_18_dialog_content = "<color=#e8d9bb>Tum!</color>",
  ui_story_5043_50431001_19_dialog_content = "Ai!",
  ui_story_5043_50431001_20_dialog_content = "Você está bem?",
  ui_story_5043_50431001_21_dialog_content = "Que tal você me ajudar em vez de fazer perguntas estúpidas?",
  ui_story_5043_50431001_22_dialog_content = "Besteira! Há Eclipsites na multidão!",
  ui_story_5043_50431001_23_dialog_content = "Eclipses?!",
  ui_story_5043_50431001_24_dialog_content = "Você tem razão. Eu posso ver vários deles.",
  ui_story_5043_50431001_25_dialog_content = "De onde eles estão vindo?",
  ui_story_5043_50431001_26_dialog_content = "Não entrar em pânico! Vou calçar eles até a morte!",
  ui_story_5043_50431001_27_dialog_content = "Você pode matar um Eclipsite com um sapato?",
  ui_story_5043_50431001_28_dialog_content = "Espere! Isso vai atingir a estátua!",
  ui_story_5043_50431001_29_dialog_content = "<color=#e8d9bb>Tum!</color>",
  ui_story_5043_50431001_30_dialog_content = "Espero que o Sr. Byron não se oponha a uma pequena pegada...",
  ui_story_5043_50431001_31_dialog_content = "Eu ajudo! Vê isto!",
  ui_story_5043_50431001_32_dialog_content = "O que!? Outro?",
  ui_story_5043_50431001_33_dialog_content = "<color=#e8d9bb>Tum!</color>",
  ui_story_5043_50431001_34_dialog_content = "Ei, a estátua está bem?",
  ui_story_5043_50431001_35_dialog_content = "Parece bom por enquanto, mas se isso continuar...",
  ui_story_5043_50431001_36_dialog_content = "Pare de jogar sapatos. Você nem está danificando uma estátua!",
  ui_story_5043_50431001_37_dialog_content = "Muito menos derrotar os Eclipsites!",
  ui_story_5043_50431001_38_dialog_content = "Ele tem razão. Temos armas melhores?",
  ui_story_5043_50431001_39_dialog_content = "Eu faço! Um pouco de queijo. É duro como pedra!",
  ui_story_5043_50431001_40_dialog_content = "Que tipo de pessoa carrega queijo!?",
  ui_story_5043_50431001_41_dialog_content = "Oh não. Se o queijo atingir a estátua, então pode...",
  ui_story_5043_50431001_42_dialog_content = "Todos, acalmem-se! Eu disse, calma! Pare de jogar coisas.",
  ui_story_5043_50431001_43_dialog_content = "Não quero ver mais arremessos!",
  ui_story_5043_50431001_44_dialog_content = "Irmã!",
  ui_story_5043_50431001_45_dialog_content = "Todo mundo para de jogar coisas. Podemos bater na irmã.",
  ui_story_5043_50431001_46_dialog_content = "Ufa... Acho que evitamos o desastre.",
  ui_story_5043_50431001_47_dialog_content = "Obrigado, irmã.",
  ui_story_5043_50431001_48_dialog_content = "Não é nada. Eu estava apenas cumprindo meu dever.",
  ui_story_5043_50431001_49_dialog_content = "Não posso deixar que nossos eventos temáticos do Mooncrown Day ganhem a reputação de arruinar o amor das pessoas!",
  ui_story_5043_50431001_50_dialog_content = "(Bem, considerando como ela protegeu a estátua, acho que podemos eliminá-la de nossas investigações.)",
  ui_story_5043_50431001_51_dialog_content = "A multidão finalmente se dispersa.",
  ui_story_5043_50431001_52_dialog_content = "Parece que podemos relaxar.",
  ui_story_5043_50431001_53_dialog_content = "Uhum.",
  ui_story_5043_50431001_54_dialog_content = "Aquela multidão em disparada era mais assustadora do que os Eclipsitas.",
  ui_story_5043_50431001_55_dialog_content = "Claro que estava. Se eu soubesse teria ido com Tina.",
  ui_story_5043_50431001_56_dialog_content = "Ei! Por que você está parado aí?",
  ui_story_5043_50431001_57_dialog_content = "Leyn, você voltou!",
  ui_story_5043_50431001_58_dialog_content = "Atrás de você!",
  ui_story_5043_50431001_59_dialog_content = "Há Eclipsites atrás de você!",
  ui_story_5043_50431002_1_dialog_content = "Esses eclipsitas com certeza sabem como surpreender as pessoas.",
  ui_story_5043_50431002_2_dialog_content = "Mas eles não conseguem resistir a uma boa luta.",
  ui_story_5043_50431002_3_dialog_content = "Não relaxe ainda. Ainda restam alguns.",
  ui_story_5043_50431002_4_dialog_content = "Vamos, vamos acabar com eles.",
  ui_story_5043_50431002_5_dialog_content = "Espere!",
  ui_story_5043_50431002_6_dialog_content = "PlayerName, ao seu lado...",
  ui_story_5043_50431002_7_dialog_content = "Ao meu lado?",
  ui_story_5043_50431002_8_dialog_content = "É com...",
  ui_story_5043_50431002_9_dialog_content = "<color=#e8d9bb>Bata!</color>",
  ui_story_5043_50431002_10_dialog_content = "Oh não! A estátua...",
  ui_story_5043_50431002_11_dialog_content = "Quem fez isto!?",
  ui_story_5043_50431002_12_dialog_content = "Eu tenho a mão do vândalo!",
  ui_story_5043_50431002_13_dialog_content = "Rápido, tire-o da pilha de Eclipsites.",
  ui_story_5043_50431002_14_dialog_content = "Afaste-se! Você está todo no meu caminho.",
  ui_story_5043_50431002_15_dialog_content = "Huh? Não há ninguém aqui.",
  ui_story_5043_50431002_16_dialog_content = "Desculpe. Ele se foi.",
  ui_story_5043_50431002_17_dialog_content = "Ele tirou a luva e escapou. Como um lagarto abandonando sua cauda...",
  ui_story_5043_50431002_18_dialog_content = "Isso é horrível. A estátua foi danificada bem debaixo do meu nariz!",
  ui_story_5043_50431002_19_dialog_content = "Como vou explicar isso?",
  ui_story_5043_50431002_20_dialog_content = "Bem... pelo menos temos a luva do culpado, certo?",
  ui_story_5043_50431002_21_dialog_content = "Essa é uma pista valiosa.",
  ui_story_5043_50431002_22_dialog_content = "Acho que podemos chamar isso de avanço em nossa investigação.",
  ui_story_5043_50431002_23_dialog_content = "Mas... eu não acho que o Sr. Byron vai ver isso assim.",
  ui_story_5043_50431002_24_dialog_content = "Ei, onde está Tina?",
  ui_story_5043_50431002_25_dialog_content = "Eu pensei que ela estava com você, Leyn?",
  ui_story_5043_50431002_26_dialog_content = "Acho que ela foi deixada para trás enquanto eu estava correndo de volta.",
  ui_story_5043_50431002_27_dialog_content = "Ei? Vocês estão bem?",
  ui_story_5043_50431002_28_dialog_content = "Desculpe, encontrei mais alguns Eclipsites no caminho subindo as escadas.",
  ui_story_5043_50431002_29_dialog_content = "Espere, a estátua... onde está a cabeça!?",
  ui_story_5043_50431002_30_dialog_content = "Suspirar...",
  ui_story_5043_50431002_31_dialog_content = "Vamos. Vamos voltar e relatar.",
  ui_story_5043_50431002_32_dialog_content = "<color=#e8d9bb>O Hall of Justice, Lumopolis Gardens</color>",
  ui_story_5043_50431002_33_dialog_content = "<size=45>Minha esposa! Minha esposa!</size>",
  ui_story_5043_50431002_34_dialog_content = "<size=45>Minha querida Afrodite!</size>",
  ui_story_5043_50431002_35_dialog_content = "...",
  ui_story_5043_50431002_36_dialog_content = "Estava morto.",
  ui_story_5043_50431002_37_dialog_content = "Como... Por que isso tinha que acontecer?",
  ui_story_5043_50431002_38_dialog_content = "Eu te amei tanto. E fiz tudo o que pude para te proteger.",
  ui_story_5043_50431002_39_dialog_content = "E ainda... meu amor foi roubado de mim...",
  ui_story_5043_50431002_40_dialog_content = "Por que não consigo salvar minhas amadas estátuas? Nem um deles...",
  ui_story_5043_50431002_41_dialog_content = "Eu sei o que aconteceu e entendo como você deve se sentir, Sr. Byron.",
  ui_story_5043_50431002_42_dialog_content = "Você? Você entende?",
  ui_story_5043_50431002_43_dialog_content = "Você não entende nada!",
  ui_story_5043_50431002_44_dialog_content = "Não há mais nada neste mundo digno do meu amor!",
  ui_story_5043_50431002_45_dialog_content = "Oh Deus da Luz, por que você me castiga assim...",
  ui_story_5043_50431002_46_dialog_content = "Talvez se você se acalmar.",
  ui_story_5043_50431002_47_dialog_content = "Afinal, o que está feito está feito.",
  ui_story_5043_50431002_48_dialog_content = "Mas vamos garantir que você obtenha justiça.",
  ui_story_5043_50431002_49_dialog_content = "Ha. O Tribunal de Justiça não pode ajudar!",
  ui_story_5043_50431002_50_dialog_content = "Se o Tribunal de Justiça pudesse fazer seu trabalho, minha esposa não teria sofrido esse destino!",
  ui_story_5043_50431002_51_dialog_content = "Não importa o fato de que três de seus juízes não conseguiram encontrar o culpado! Você não conseguiu nem proteger uma única estátua!",
  ui_story_5043_50431002_52_dialog_content = "Apenas espere até o Juiz Chefe Irridon ouve falar de seus grandes sucessos!",
  ui_story_5043_50431002_53_dialog_content = "Tenho certeza que ela não vai deixar uma divisão cheia de incompetentes arruinar o bom nome do Tribunal de Justiça!",
  ui_story_5043_50431002_54_dialog_content = "Sinto muito por desapontá-lo tanto, Sr. Byron.",
  ui_story_5043_50431002_55_dialog_content = "Não fomos capazes de proteger a estátua ou pegar o culpado no local.",
  ui_story_5043_50431002_56_dialog_content = "Mas... conseguimos uma luva que o culpado estava usando.",
  ui_story_5043_50431002_57_dialog_content = "Meu Deus! Então minha esposa perdeu sua linda cabeça e, em troca, você tem uma luva?",
  ui_story_5043_50431002_58_dialog_content = "Certamente você não acha que essa troca valeu a pena.",
  ui_story_5043_50431002_59_dialog_content = "Quantas pessoas vivem em Lumópolis? Quantos pares de luvas eles têm?",
  ui_story_5043_50431002_60_dialog_content = "E o que você fará com esta luva, dado o quão incompetente é toda a Divisão Romance?",
  ui_story_5043_50431002_61_dialog_content = "Sr. Byron, por favor, não demita toda a Divisão Romance por causa das falhas de alguns funcionários.",
  ui_story_5043_50431002_62_dialog_content = "Os juízes não tiveram um bom desempenho. Mas, como juiz supremo, garanto que cada caso chegue a uma conclusão justa.",
  ui_story_5043_50431002_63_dialog_content = "Uma conclusão justa? Guarde as palavras bonitas para o Juiz Chefe Irridon!",
  ui_story_5043_50431002_64_dialog_content = "Meu amante e minha esposa foram danificados. E o culpado continua foragido.",
  ui_story_5043_50431002_65_dialog_content = "Você chama isso de justiça!?",
  ui_story_5043_50431002_66_dialog_content = "Ainda não, Sr. Byron. Mas não sejamos precipitados.",
  ui_story_5043_50431002_67_dialog_content = "O culpado não escapou até que o martelo caia.",
  ui_story_5043_50431002_68_dialog_content = "Oh, você acha que pode pegar o criminoso antes que o caso seja concluído?",
  ui_story_5043_50431002_69_dialog_content = "Juiz Leyn, apresente a luva.",
  ui_story_5043_50431002_70_dialog_content = "De nada.",
  ui_story_5043_50431002_71_dialog_content = "Esta é uma luva tirada da mão do culpado no local. Isso está correto?",
  ui_story_5043_50431002_72_dialog_content = "Isso é. Quase peguei o culpado, mas ele escapou ao tirar a luva.",
  ui_story_5043_50431002_73_dialog_content = "O que torna as coisas simples. O dono da luva removeu a cabeça da estátua.",
  ui_story_5043_50431002_74_dialog_content = "E acontece que meu povo descobriu <color=#FFB400>a outra luva</color>.",
  ui_story_5043_50431002_75_dialog_content = "Como você verá, as duas luvas são um par.",
  ui_story_5043_50431002_76_dialog_content = "A outra luva!?",
  ui_story_5043_50431002_77_dialog_content = "?!",
  ui_story_5043_50431002_78_dialog_content = "Mas como!?",
  ui_story_5043_50431002_79_dialog_content = "Onde você achou isso? E a quem pertence?",
  ui_story_5043_50431002_80_dialog_content = "E agora que temos as luvas, podemos facilmente levar este caso a uma conclusão justa.",
  ui_story_5043_50431002_81_dialog_content = "Guardas! Fique pronto!",
  ui_story_5043_50431002_82_dialog_content = "E prender... Tina Campbell!",
  ui_story_5043_50431002_83_dialog_content = "O que? Prender prisão Tina?",
  ui_story_5043_50431002_84_dialog_content = "Sim, senhor!",
  ui_story_5043_50431101_1_dialog_content = "Espere! Isso não pode estar certo.",
  ui_story_5043_50431101_2_dialog_content = "Como pode ser Tina!",
  ui_story_5043_50431101_3_dialog_content = "Eu sei. Não é possível.",
  ui_story_5043_50431101_4_dialog_content = "Você é algum tipo de idiota, Juiz Schwab?",
  ui_story_5043_50431101_5_dialog_content = "Vocês, juízes, carecem de julgamento. Não deixei meu raciocínio perfeitamente claro?",
  ui_story_5043_50431101_6_dialog_content = "Dona da luva recolhida pelo Juiz Leyn é o culpado. Isso é óbvio.",
  ui_story_5043_50431101_7_dialog_content = "E depois desse último incidente, meu pessoal conseguiu identificar rapidamente a outra metade do par.",
  ui_story_5043_50431101_8_dialog_content = "E foi encontrado... na gaveta da escrivaninha da juíza Tina.",
  ui_story_5043_50431101_9_dialog_content = "Quê?!",
  ui_story_5043_50431101_10_dialog_content = "Tina, estas são suas luvas?",
  ui_story_5043_50431101_11_dialog_content = "Eu... eu tenho um par de luvas assim.",
  ui_story_5043_50431101_12_dialog_content = "Mas não entendo como apareceram no local...",
  ui_story_5043_50431101_13_dialog_content = "Juiz Tina, Não tenho certeza se você entende a gravidade de sua situação.",
  ui_story_5043_50431101_14_dialog_content = "Como você é nosso principal suspeito, deveria nos contar como as luvas foram parar ali.",
  ui_story_5043_50431101_15_dialog_content = "E eu nunca teria esperado que uma coisinha bonita como você cometesse crimes tão cruéis.",
  ui_story_5043_50431101_16_dialog_content = "Ah, a tragédia de tudo isso...",
  ui_story_5043_50431101_17_dialog_content = "Ei! Pare de caluniar os pobres Tina!",
  ui_story_5043_50431101_18_dialog_content = "Tina estava conosco quando tudo aconteceu. Combatendo Eclipsites!",
  ui_story_5043_50431101_19_dialog_content = "Todos nós podemos dar-lhe um álibi. Ela não pode ser a culpada!",
  ui_story_5043_50431101_20_dialog_content = "Leyn, lembre-se de que você deve assumir a responsabilidade por suas declarações como juiz.",
  ui_story_5043_50431101_21_dialog_content = "Tenho certeza que você não precisa de mim para lhe dizer as punições por perjúrio.",
  ui_story_5043_50431101_22_dialog_content = "Mas ele está certo! E eu posso provar isso!",
  ui_story_5043_50431101_23_dialog_content = "Realmente? Pense bem, todos vocês.",
  ui_story_5043_50431101_24_dialog_content = "Quando ocorreu o incidente, era o Juiz Tina realmente ao seu lado na luta contra os Eclipsitas?",
  ui_story_5043_50431101_25_dialog_content = "Ela...",
  ui_story_5043_50431101_26_dialog_content = "Ei, onde está Tina?",
  ui_story_5043_50431101_27_dialog_content = "Eu pensei que ela estava com você, Leyn?",
  ui_story_5043_50431101_28_dialog_content = "Acho que ela foi deixada para trás enquanto eu estava correndo de volta.",
  ui_story_5043_50431101_29_dialog_content = "Ei? Vocês estão bem?",
  ui_story_5043_50431101_30_dialog_content = "(Oh não... Ela realmente não estava conosco durante a luta!)",
  ui_story_5043_50431101_31_dialog_content = "Parece que você entende agora.",
  ui_story_5043_50431101_32_dialog_content = "Ao testemunhar sob juramento, é imperativo que prestemos muita atenção a cada palavra que é dita.",
  ui_story_5043_50431101_33_dialog_content = "Se você não consegue entender um conceito básico como este, temo que nunca será um juiz digno no Tribunal de Justiça.",
  ui_story_5043_50431101_34_dialog_content = "...",
  ui_story_5043_50431101_35_dialog_content = "De qualquer forma, o culpado foi capturado, então vamos encerrar o processo ridículo de hoje.",
  ui_story_5043_50431101_36_dialog_content = "Está satisfeito com nossos resultados hoje, Sr. Byron?",
  ui_story_5043_50431101_37_dialog_content = "Eu nunca esperaria que um juiz fosse o culpado por tudo isso...",
  ui_story_5043_50431101_38_dialog_content = "Não é de admirar que vocês não façam nada por aqui!",
  ui_story_5043_50431101_39_dialog_content = "Não é nada disso, Sr. Byron...",
  ui_story_5043_50431101_40_dialog_content = "Eu fui tolo o suficiente para colocar minha fé em vocês...",
  ui_story_5043_50431101_41_dialog_content = "E o que eu ganhei em troca, hein? Um bando de desajustados discutindo sobre o amor enquanto o destroem e desperdiçam meu tempo!",
  ui_story_5043_50431101_42_dialog_content = "É melhor esta criminosa nojenta responder por seus crimes, Juiz Schwab! Quero dizer!",
  ui_story_5043_50431101_43_dialog_content = "Garanto-lhe que ela será levada à justiça, Sr. Byron... Mas não hoje.",
  ui_story_5043_50431101_44_dialog_content = "Não vamos esquecer que o julgamento do decapitador da estátua será realizado amanhã.",
  ui_story_5043_50431101_45_dialog_content = "Nessa altura, pode apresentar o seu pedido ao tribunal.",
  ui_story_5043_50431101_46_dialog_content = "Estou bem ciente disso!",
  ui_story_5043_50431101_47_dialog_content = "Minha amante, minha esposa... Eles são as verdadeiras vítimas de tudo isso! Eles não mereciam o que aconteceu com eles!",
  ui_story_5043_50431101_48_dialog_content = "Prometa-me que vai buscar justiça para eles, Juiz Schwab!",
  ui_story_5043_50431101_49_dialog_content = "Mas é claro. Afinal, a Divisão Romance tem o dever de proteger a santidade do amor.",
  ui_story_5043_50431101_50_dialog_content = "Guardas! Leve-a embora!",
  ui_story_5043_50431101_51_dialog_content = "Um momento por favor!",
  ui_story_5043_50431101_52_dialog_content = "Meritíssimo, gostaria de inspecionar essa luva mais uma vez.",
  ui_story_5043_50431101_53_dialog_content = "Não tem jeito Tina poderia ter cometido este crime... Talvez tenhamos interpretado mal algumas partes das provas?",
  ui_story_5043_50431101_54_dialog_content = "De qualquer forma, não podemos tê-la detida tão apressadamente!",
  ui_story_5043_50431101_55_dialog_content = "Ouça ouça! Só porque é o mesmo estilo de luva, não significa necessariamente que pertença ao par original!",
  ui_story_5043_50431101_56_dialog_content = "Na verdade, sou conhecido por comprar sete pares exatamente das mesmas luvas de vez em quando!",
  ui_story_5043_50431101_57_dialog_content = "Leyn... Matthieu...",
  ui_story_5043_50431101_58_dialog_content = "Chega, juízes. Já estou cheio de especulações ridículas há um dia.",
  ui_story_5043_50431101_59_dialog_content = "Se tiver mais alguma coisa a dizer, sugiro que guarde para o julgamento de amanhã.",
  ui_story_5043_50431101_60_dialog_content = "Mas por que? Eu só quero dar uma olhada...",
  ui_story_5043_50431101_61_dialog_content = "Eu disse: BASTA.",
  ui_story_5043_50431101_62_dialog_content = "O suspeito será levado em confinamento solitário em breve. Ninguém terá permissão para vê-la até o início dos procedimentos de amanhã.",
  ui_story_5043_50431101_63_dialog_content = "Confinamento solitário?! Você ficou maluco?!",
  ui_story_5043_50431101_64_dialog_content = "Você não tem o direito de colocá-la em confinamento solitário antes de seu julgamento! Isso é contra a lei!",
  ui_story_5043_50431101_65_dialog_content = "Como juiz chefe da Divisão Romance, recebi a autoridade exclusiva para bater no cascalho e decidir quem é o culpado.",
  ui_story_5043_50431101_66_dialog_content = "Colocá-la em confinamento solitário é apenas mais um passo necessário no processo, ou você duvida do Tribunal de Justiça e de suas leis?",
  ui_story_5043_50431101_67_dialog_content = "Ei, você—",
  ui_story_5043_50431101_68_dialog_content = "D-Não se precipite, pessoal!",
  ui_story_5043_50431101_69_dialog_content = "Vou concordar com a decisão do juiz Schwab por enquanto. Teremos apenas que contestar as acusações no tribunal amanhã.",
  ui_story_5043_50431101_70_dialog_content = "Tina...",
  ui_story_5043_50431101_71_dialog_content = "Sou um juiz, então tenho que acreditar que o sistema de justiça de Lumopolis nunca puniria injustamente uma pessoa inocente.",
  ui_story_5043_50431101_72_dialog_content = "Tenho certeza que a verdade ficará clara durante o julgamento de amanhã...",
  ui_story_5043_50431101_73_dialog_content = "Porque acredito na Divisão Romance.",
  ui_story_5043_50431101_74_dialog_content = "E eu acredito em todos vocês.",
  ui_story_5043_50431101_75_dialog_content = "...",
  ui_story_5043_50431101_76_dialog_content = "...",
  ui_story_5043_50431101_77_dialog_content = "Leve-a embora, guardas.",
  ui_story_5043_50431101_78_dialog_content = "Sim, senhor!",
  ui_story_5043_50431101_79_dialog_content = "<color=#e8d9bb>Fora do Hall of Justice, Lumopolis Gardens</color>",
  ui_story_5043_50431101_80_dialog_content = "Eles trancaram Tina acima. O que nós vamos fazer?",
  ui_story_5043_50431101_81_dialog_content = "Você não acha que eles vão considerá-la culpada amanhã, acha?",
  ui_story_5043_50431101_82_dialog_content = "Se as coisas continuarem como estão agora... elas ficarão.",
  ui_story_5043_50431101_83_dialog_content = "N-não podemos deixar isso acontecer! Ela é inocente!",
  ui_story_5043_50431101_84_dialog_content = "Sou só eu ou algo sobre Schwab pareceu estranho hoje?",
  ui_story_5043_50431101_85_dialog_content = "Hã?",
  ui_story_5043_50431101_86_dialog_content = "Bem, eu sempre pensei nele como uma pessoa muito estranha, mas agora que você mencionou isso...",
  ui_story_5043_50431101_87_dialog_content = "Sua atitude hoje parecia um pouco extrema.",
  ui_story_5043_50431101_88_dialog_content = "Ele estava claramente se opondo a nós, sim.",
  ui_story_5043_50431101_89_dialog_content = "Ele embelezou qualquer informação que implicasse Tina, e ignorou todas as nossas refutações.",
  ui_story_5043_50431101_90_dialog_content = "Precisamente. É demais para ser apenas uma coincidência, você não acha?",
  ui_story_5043_50431101_91_dialog_content = "No momento em que o incidente ocorreu, seu pessoal simplesmente encontrou aquela luva e a apresentou como prova.",
  ui_story_5043_50431101_92_dialog_content = "É quase como se ele já soubesse onde estava a outra luva...",
  ui_story_5043_50431101_93_dialog_content = "Não apenas isso. Ele parecia ter uma compreensão muito detalhada do que aconteceu na cena do crime.",
  ui_story_5043_50431101_94_dialog_content = "Lembra daquele olhar nojento e satisfeito que ele tinha no rosto?",
  ui_story_5043_50431101_95_dialog_content = "Realmente? Pense bem, todos vocês.",
  ui_story_5043_50431101_96_dialog_content = "Quando ocorreu o incidente, era o Juiz Tina realmente ao seu lado na luta contra os Eclipsitas?",
  ui_story_5043_50431101_97_dialog_content = "Para começar, ele nunca esteve lá, então o que lhe deu confiança para nos perguntar isso?",
  ui_story_5043_50431101_98_dialog_content = "Tem razão!",
  ui_story_5043_50431101_99_dialog_content = "Quando você leva tudo isso em consideração, o processo judicial contra Tina correu muito bem hoje.",
  ui_story_5043_50431101_100_dialog_content = "Tudo apontou para Tina ser culpado sem dúvida...",
  ui_story_5043_50431101_101_dialog_content = "Mas nenhuma dessas coisas foi tão estranha quanto sua decisão final.",
  ui_story_5043_50431101_102_dialog_content = "A decisão de trancá-la.",
  ui_story_5043_50431101_103_dialog_content = "Eu não poderia concordar mais.",
  ui_story_5043_50431101_104_dialog_content = "Encontrar aquela luva, saber exatamente o que aconteceu na cena do crime... Ele poderia explicar essas coisas facilmente - talvez houvesse muitas testemunhas, ou foi pura sorte.",
  ui_story_5043_50431101_105_dialog_content = "Todos os procedimentos eram legítimos e não haveria pontas soltas em sua acusação.",
  ui_story_5043_50431101_106_dialog_content = "De fato. Mas ele estava cansado de provar a si mesmo no final.",
  ui_story_5043_50431101_107_dialog_content = "Ele nos impediu de inspecionar as evidências e trancou Tina em confinamento solitário sem oferecer uma razão.",
  ui_story_5043_50431101_108_dialog_content = "Isso significa que ele está escondendo algo, algo que não pode permitir que outros vejam.",
  ui_story_5043_50431101_109_dialog_content = "Especialmente não nós.",
  ui_story_5043_50431101_110_dialog_content = "Deve ser uma pista importante para ele quebrar as regras a fim de encobri-lo.",
  ui_story_5043_50431101_111_dialog_content = "Algo me diz que essa pista é a chave para descobrir a verdade e provar a inocência de Tina!",
  ui_story_5043_50431101_112_dialog_content = "Uau! Que dedução brilhante!",
  ui_story_5043_50431101_113_dialog_content = "Olha o que fala.",
  ui_story_5043_50431101_114_dialog_content = "Este é o portão do Hall da Justiça.",
  ui_story_5043_50431101_115_dialog_content = "O-Oh sim, devemos mantê-lo baixo.",
  ui_story_5043_50431101_116_dialog_content = "Então, tudo o que temos a fazer é descobrir o que Schwab está escondendo de nós, e poderemos provar a inocência de Tina, certo?",
  ui_story_5043_50431101_117_dialog_content = "Parece fácil quando você coloca dessa forma, mas estou preocupado que não consigamos descobrir a tempo.",
  ui_story_5043_50431101_118_dialog_content = "Hã?",
  ui_story_5043_50431101_119_dialog_content = "Schwab definitivamente vai amarrar todas as pontas soltas antes do julgamento de amanhã.",
  ui_story_5043_50431101_120_dialog_content = "Ele sabe o que precisa ser feito para cobrir seus rastros, dos quais não temos ideia.",
  ui_story_5043_50431101_121_dialog_content = "Tenho certeza de que ele tem muitas contingências alinhadas, caso algo dê errado.",
  ui_story_5043_50431101_122_dialog_content = "As chances de sucesso dele estão fortemente a seu favor.",
  ui_story_5043_50431101_123_dialog_content = "E daí, estamos apenas esperando até o julgamento e torcendo pelo melhor?!",
  ui_story_5043_50431101_124_dialog_content = "Se nós fizermos, Tina definitivamente será considerado culpado.",
  ui_story_5043_50431101_125_dialog_content = "O que significa que precisamos desenterrar algumas pistas antes do início do julgamento.",
  ui_story_5043_50431101_126_dialog_content = "Se não conseguirmos desvendar o segredo de Schwab, teremos que procurar outras pistas.",
  ui_story_5043_50431101_127_dialog_content = "Hahaha, uma sugestão interessante!",
  ui_story_5043_50431101_128_dialog_content = "E algo me diz que você já sabe por onde começar, não é mesmo?",
  ui_story_5043_50431101_129_dialog_content = "Ei, vocês três é melhor não fazer nada estúpido, você me ouviu?",
  ui_story_5043_50431101_130_dialog_content = "Ora, vamos, Loewe! Jamais sonharíamos com isso.",
  ui_story_5043_50431101_131_dialog_content = "... Ainda tenho mais investigações, então vou embora agora.",
  ui_story_5043_50431101_132_dialog_content = "Se vocês três forem pegos fazendo algo estúpido, eu nunca estive aqui e nunca tivemos essa conversa. Entender?",
  ui_story_5043_50431101_133_dialog_content = "Você...",
  ui_story_5043_50431101_134_dialog_content = "É melhor assim, Matthieu. Mais pessoas só iriam atrapalhar.",
  ui_story_5043_50431101_135_dialog_content = "Agora cheguem mais perto, vocês dois.",
  ui_story_5043_50431101_136_dialog_content = "Claro, o que é?",
  ui_story_5043_50431101_137_dialog_content = "Se Schwab estava disposto a quebrar as regras para esconder seu segredo...",
  ui_story_5043_50431101_138_dialog_content = "Teremos que fazer o mesmo se quisermos vencê-lo.",
  ui_story_5043_50431101_139_dialog_content = "Mas como exatamente?",
  ui_story_5043_50431101_140_dialog_content = "Vamos invadir a casa de Schwab.",
  ui_story_5043_50431101_141_dialog_content = "O quê?!",
  ui_story_5043_50431101_142_dialog_content = "Se não conseguirmos chegar perto do suspeito ou da evidência, teremos que ir com a próxima melhor coisa - o próprio Schwab.",
  ui_story_5043_50431101_143_dialog_content = "E sua casa é o lugar mais seguro para guardar seus segredos.",
  ui_story_5043_50431101_144_dialog_content = "Se ele realmente está escondendo algo importante, esse seria o melhor lugar para começar a procurar.",
  ui_story_5043_50431101_145_dialog_content = "Mas... isso não seria contra a lei?",
  ui_story_5043_50431101_146_dialog_content = "Isto é interessante! Que ideia maravilhosa!",
  ui_story_5043_50431101_147_dialog_content = "Então isso resolve! Vamos fazer uma visita à mansão do bom juiz!",
  ui_story_5043_50431101_148_dialog_content = "Acho que sou o único que se importa mais com a lei... Tudo bem, estou dentro.",
  ui_story_5043_50431101_149_dialog_content = "A única razão pela qual estamos nesta situação é que nosso oponente fez o mesmo conosco.",
  ui_story_5043_50431101_150_dialog_content = "Quando chegar a hora, ficarei feliz em assumir toda a responsabilidade por invadir a casa dele.",
  ui_story_5043_50431101_151_dialog_content = "Mas o que mais importa agora é garantir que Tina não é punida por um crime que não cometeu.",
  ui_story_5043_50431101_152_dialog_content = "Hmph. Responsabilidade total, você diz?",
  ui_story_5043_50431101_153_dialog_content = "Suspiro, esse tipo de honestidade só vai causar problemas para você no futuro, você sabe.",
  ui_story_5043_50431101_154_dialog_content = "Você está certo... Provar a inocência de Tina vem em primeiro lugar!",
  ui_story_5043_50431101_155_dialog_content = "Então, devemos ir agora?",
  ui_story_5043_50431101_156_dialog_content = "Ainda há uma última coisa que temos que fazer antes disso.",
  ui_story_5043_50431101_157_dialog_content = "Não sei se vocês dois notaram, mas aqueles guardas atrás de nós estão nos seguindo há algum tempo.",
  ui_story_5043_50431101_158_dialog_content = "Schwab deve ter ordenado a eles que ficassem de olho em nós. Não há como ele simplesmente nos deixar ir.",
  ui_story_5043_50431101_159_dialog_content = "Parece que teremos que nos livrar deles, então.",
  ui_story_5043_50431101_160_dialog_content = "Exatamente meus pensamentos.",
  ui_story_5043_50431101_161_dialog_content = "Deve ser fácil o suficiente. Afinal, sou profissional quando se trata de fugir.",
  ui_story_5043_50431101_162_dialog_content = "Não se esqueça, tenho um conjunto extra de \"olhos\" neles.",
  ui_story_5043_50431101_163_dialog_content = "Isso mesmo! Podemos usar suas habilidades psíquicas neles!",
  ui_story_5043_50431101_164_dialog_content = "Então, como nosso artista de fuga residente, qual deve ser nosso primeiro passo?",
  ui_story_5043_50431101_165_dialog_content = "É bem simples, na verdade.",
  ui_story_5043_50431101_166_dialog_content = "O primeiro passo para fugir—",
  ui_story_5043_50431101_167_dialog_content = "— é começar a correr!!!",
  ui_story_5043_50431102_1_dialog_content = "Vire à direita em frente!",
  ui_story_5043_50431102_2_dialog_content = "Ah, isso é positivamente exaustivo.",
  ui_story_5043_50431102_3_dialog_content = "Bem? Há algum guarda seguindo nosso rastro?",
  ui_story_5043_50431102_4_dialog_content = "Não! Nem um único!",
  ui_story_5043_50431102_5_dialog_content = "O que? Então por que ainda estamos correndo?!",
  ui_story_5043_50431102_6_dialog_content = "A-Não vamos para a casa de Schwab agora?",
  ui_story_5043_50431102_7_dialog_content = "Tenho certeza de que este é o caminho certo.",
  ui_story_5043_50431102_8_dialog_content = "Sim, mas se ninguém estiver nos perseguindo, podemos caminhar o resto do caminho até lá!",
  ui_story_5043_50431102_9_dialog_content = "Além disso, como você sabe que a casa dele é por aqui?",
  ui_story_5043_50431102_10_dialog_content = "Porque eu disse a ele.",
  ui_story_5043_50431102_11_dialog_content = "Estamos com pouco tempo, então pensei que ir até lá seria mais rápido.",
  ui_story_5043_50431102_12_dialog_content = "Você poderia pelo menos ter me dito que perdemos os guardas! Eu estava com medo de que eles estivessem nos nossos calcanhares o tempo todo!!",
  ui_story_5043_50431102_13_dialog_content = "Tudo bem, tudo bem, fale baixo. A casa dele é logo adiante.",
  ui_story_5043_50431102_14_dialog_content = "Por que você...",
  ui_story_5043_50431102_15_dialog_content = "<color=#e8d9bb>Fora do Salar Manor, Lumopolis Gardens</color>",
  ui_story_5043_50431102_16_dialog_content = "Parece que eles têm muitos guardas e criados postados na entrada.",
  ui_story_5043_50431102_17_dialog_content = "Como devemos evitá-los E procurar pistas?",
  ui_story_5043_50431102_18_dialog_content = "Você está certo, não será fácil.",
  ui_story_5043_50431102_19_dialog_content = "Se algum deles nos vir, estaremos sentados ao lado Tina no cais amanhã.",
  ui_story_5043_50431102_20_dialog_content = "Sabendo disso, vocês dois ainda estão dispostos a continuar com isso?",
  ui_story_5043_50431102_21_dialog_content = "Esta é a nossa única escolha se quisermos provar Tina inocente...",
  ui_story_5043_50431102_22_dialog_content = "Devemos fazê-lo, não importa o quão perigoso possa ser!",
  ui_story_5043_50431102_23_dialog_content = "Há um lado positivo nesse esquema imprudente. A casa de Schwab é definitivamente grande o suficiente para nos fornecer muitos lugares para nos escondermos.",
  ui_story_5043_50431102_24_dialog_content = "Com isso e algumas habilidades psíquicas, devemos ser capazes de evitar os perigos o suficiente.",
  ui_story_5043_50431102_25_dialog_content = "Vou me certificar de ficar de olho em nossos arredores! Apenas deixe comigo!",
  ui_story_5043_50431102_26_dialog_content = "Então, como exatamente colocamos os pés dentro da mansão?",
  ui_story_5043_50431102_27_dialog_content = "Não tenho certeza se temos tempo suficiente para esperar que os guardas troquem de turno...",
  ui_story_5043_50431102_28_dialog_content = "Não importa, já que não entraremos pelo portão da frente.",
  ui_story_5043_50431102_29_dialog_content = "Oh? Por acaso você viu outro portão, então?",
  ui_story_5043_50431102_30_dialog_content = "Não, mas olha aquele jardim ali. Tem muitas sebes que podemos usar como cobertura.",
  ui_story_5043_50431102_31_dialog_content = "Assim que estivermos perto o suficiente, simplesmente pularemos o muro.",
  ui_story_5043_50431102_32_dialog_content = "Pular o muro?!",
  ui_story_5043_50431102_33_dialog_content = "Você tem razão! É perfeito para ficar fora de vista, e olha, a parede também não é tão alta assim!",
  ui_story_5043_50431102_34_dialog_content = "Vamos, vamos nos mexer.",
  ui_story_5043_50431102_35_dialog_content = "Entendido!",
  ui_story_5043_50431102_36_dialog_content = "E-esperem um minuto, vocês dois! Você não acha que pular a parede é um pouco impróprio?",
  ui_story_5043_50431102_37_dialog_content = "Afinal, sou um orgulhoso membro do Sawyer—",
  ui_story_5043_50431102_38_dialog_content = "— Ugh, esquece. Honestamente, vocês plebeus vão ser a minha morte.",
  ui_story_5043_50431201_1_dialog_content = "Ugh... Por que devo fazer algo tão tolo...?",
  ui_story_5043_50431201_2_dialog_content = "Apenas sorria e aguente, Matthieu. Estamos fazendo isso para limpar o nome de Tina.",
  ui_story_5043_50431201_3_dialog_content = "Ver? Já entramos na mansão!",
  ui_story_5043_50431201_4_dialog_content = "Tudo parece tão elegante aqui...",
  ui_story_5043_50431201_5_dialog_content = "Então esta é a casa de Schwab, hein?",
  ui_story_5043_50431201_6_dialog_content = "Sim... tenho que admitir, isso me deixa com um pouco de inveja.",
  ui_story_5043_50431201_7_dialog_content = "A Família Salar é uma das mais influentes de toda Lumópolis.",
  ui_story_5043_50431201_8_dialog_content = "O que vemos aqui é apenas a ponta do iceberg quando se trata de sua riqueza, tenho certeza—",
  ui_story_5043_50431201_9_dialog_content = "Tudo bem, dê um descanso já. Acho que vejo alguém à frente.",
  ui_story_5043_50431201_10_dialog_content = "Vamos dar uma olhada.",
  ui_story_5043_50431201_11_dialog_content = "Ei, eu também os vejo!",
  ui_story_5043_50431201_12_dialog_content = "Espere, isso é... Schwab?",
  ui_story_5043_50431201_13_dialog_content = "Perdoe-nos, mestre Schwab, perdemos seus rastros.",
  ui_story_5043_50431201_14_dialog_content = "O celestita e os dois juízes usaram os caminhos sinuosos a seu favor, então não conseguimos alcançá-los...",
  ui_story_5043_50431201_15_dialog_content = "É por isso que contratei vocês, idiotas, hein?",
  ui_story_5043_50431201_16_dialog_content = "Inútil! Todos vocês!",
  ui_story_5043_50431201_17_dialog_content = "Perdoe-nos, meu senhor!",
  ui_story_5043_50431201_18_dialog_content = "... Suficiente. O que está feito está feito.",
  ui_story_5043_50431201_19_dialog_content = "Agora que eles estão fugindo, talvez algo de bom venha de seu erro idiota.",
  ui_story_5043_50431201_20_dialog_content = "Retorne às suas postagens.",
  ui_story_5043_50431201_21_dialog_content = "Sim, Mestre Schwab!",
  ui_story_5043_50431201_22_dialog_content = "Então seus homens estavam nos espionando... Hah! Como se eu o deixasse fazer o que quisesse!",
  ui_story_5043_50431201_23_dialog_content = "Estou feliz por termos encontrado Schwab tão rapidamente.",
  ui_story_5043_50431201_24_dialog_content = "Vamos continuar a segui-lo e ver o que ele vai fazer.",
  ui_story_5043_50431201_25_dialog_content = "Qualquer mudança em seu comportamento pode nos fornecer as pistas de que precisamos!",
  ui_story_5043_50431201_26_dialog_content = "Entendido!",
  ui_story_5043_50431201_27_dialog_content = "Para que vocês dois não se esqueçam, Schwab não é um homem que possa ser facilmente compreendido.",
  ui_story_5043_50431201_28_dialog_content = "Se ele está disposto a infringir a lei perante todo o Tribunal de Justiça, quem sabe que atos indescritíveis ele é capaz de realizar na privacidade de sua própria casa...",
  ui_story_5043_50431201_29_dialog_content = "O-Ok, agora você está começando a me assustar.",
  ui_story_5043_50431201_30_dialog_content = "Bom. Seu medo o manterá alerta.",
  ui_story_5043_50431201_31_dialog_content = "Venha, não o percamos de vista.",
  ui_story_5043_50431201_32_dialog_content = "Seu chá, meu senhor.",
  ui_story_5043_50431201_33_dialog_content = "Bom, dá aqui.",
  ui_story_5043_50431201_34_dialog_content = "A cozinha está preparando algumas sobremesas. Devo trazer-lhe um prato, mestre?",
  ui_story_5043_50431201_35_dialog_content = "Isso não será necessário. Tenho outros assuntos para resolver agora.",
  ui_story_5043_50431201_36_dialog_content = "Não me perturbe até que eu termine com eles.",
  ui_story_5043_50431201_37_dialog_content = "S-Sim, Mestre Schwab!",
  ui_story_5043_50431201_38_dialog_content = "Ele mandou seu servo embora.",
  ui_story_5043_50431201_39_dialog_content = "Shhh... Esses assuntos podem ser tão perversos que nem mesmo seu próprio povo pode saber deles?",
  ui_story_5043_50431201_40_dialog_content = "Er... M-Talvez ele só queira ficar sozinho por um tempo?",
  ui_story_5043_50431201_41_dialog_content = "Honestamente, PlayerName... Você não tem imaginação?",
  ui_story_5043_50431201_42_dialog_content = "Eu disse ou não acabei de dizer que Schwab não é um homem que pode ser facilmente compreendido?",
  ui_story_5043_50431201_43_dialog_content = "Bem bem. Entendo.",
  ui_story_5043_50431201_44_dialog_content = "Ainda assim, quão ruim poderia ser? O que um homem complicado como ele poderia fazer em seu próprio jardim?",
  ui_story_5043_50431201_45_dialog_content = "Olhar! Ele está levantando a mão agora!",
  ui_story_5043_50431201_46_dialog_content = "Parece que ele está segurando algo.",
  ui_story_5043_50431201_47_dialog_content = "É uma agulha! Ele tem uma agulha na mão!",
  ui_story_5043_50431201_48_dialog_content = "Uma agulha?!",
  ui_story_5043_50431201_49_dialog_content = "Para qual propósito? Ele pretende usá-lo em si mesmo?!",
  ui_story_5043_50431201_50_dialog_content = "Não, não em si mesmo...",
  ui_story_5043_50431201_51_dialog_content = "<color=#e8d9bb>Facada!</color>",
  ui_story_5043_50431201_52_dialog_content = "Ele está usando na boneca que tem na outra mão...",
  ui_story_5043_50431201_53_dialog_content = "P-Por que ele está fazendo isso com uma boneca?!",
  ui_story_5043_50431201_54_dialog_content = "Já ouvi falar disso antes... Um tipo de maldição envolvendo o uso de bonecas.",
  ui_story_5043_50431201_55_dialog_content = "Uma maldição?",
  ui_story_5043_50431201_56_dialog_content = "Ele funciona tirando algo do corpo de uma pessoa, geralmente cabelo ou sangue, e colocando dentro de uma boneca.",
  ui_story_5043_50431201_57_dialog_content = "Ao fazer isso, a boneca se torna espiritualmente ligada a essa pessoa.",
  ui_story_5043_50431201_58_dialog_content = "Picar ou ferir a boneca inflige a mesma dor e ferimentos no alvo da maldição.",
  ui_story_5043_50431201_59_dialog_content = "E, eventualmente, a pessoa teria uma morte terrivelmente dolorosa!",
  ui_story_5043_50431201_60_dialog_content = "<color=#e8d9bb>Facada!</color>",
  ui_story_5043_50431201_61_dialog_content = "Tsk, ele fez isso de novo!",
  ui_story_5043_50431201_62_dialog_content = "Acho que já ouvi falar de maldições como essa, mas nunca esperei que alguém como Schwab se envolvesse com as artes das trevas...",
  ui_story_5043_50431201_63_dialog_content = "Bem, não acho nada surpreendente. Há muito tempo eu vi através de sua charada gentil e nobre!",
  ui_story_5043_50431201_64_dialog_content = "Não sei... Maldições como essa geralmente são apenas uma superstição assustadora, certo?",
  ui_story_5043_50431201_65_dialog_content = "Além disso, isso seria uma violação flagrante da fé de Lumopolis...",
  ui_story_5043_50431201_66_dialog_content = "Eu vejo. Não importa se a maldição é real ou não. O que importa é se as pessoas acreditam ou não nisso.",
  ui_story_5043_50431201_67_dialog_content = "E está claro para mim que Schwab acredita nisso.",
  ui_story_5043_50431201_68_dialog_content = "O que significa que em algum lugar do mundo... Há uma pessoa que Schwab odeia o suficiente para querer matá-la...",
  ui_story_5043_50431201_69_dialog_content = "<color=#e8d9bb>Facada!</color>",
  ui_story_5043_50431201_70_dialog_content = "Mas quem? Quem poderia ser?!",
  ui_story_5043_50431201_71_dialog_content = "Quem poderia tê-lo prejudicado tanto, que ele desejaria a morte deles?",
  ui_story_5043_50431201_72_dialog_content = "Não faço ideia... Mas realmente te faz pensar, não é?",
  ui_story_5043_50431201_73_dialog_content = "Segundo a maioria dos relatos, Schwab vive uma vida quase perfeita... Não consigo imaginar quem poderia arruinar isso para ele.",
  ui_story_5043_50431201_74_dialog_content = "A menos que... seu ódio venha de um lugar onde ninguém possa vê-lo facilmente.",
  ui_story_5043_50431201_75_dialog_content = "Quando você coloca dessa forma... Sim, agora faz todo o sentido!",
  ui_story_5043_50431201_76_dialog_content = "Claramente, sua raiva vem de um relacionamento perdido, mas inesquecível. <color=#FFB400>amor</color>!",
  ui_story_5043_50431201_77_dialog_content = "<color=#e8d9bb>Facada!</color>",
  ui_story_5043_50431201_78_dialog_content = "Se isso for verdade, precisamos fazer algo a respeito imediatamente! Isso pode significar a diferença entre a vida e a morte de alguém lá fora!",
  ui_story_5043_50431201_79_dialog_content = "Não sejamos precipitados. Devemos esperar que ele mostre evidências claras e inegáveis de transgressão antes de podermos interferir.",
  ui_story_5043_50431201_80_dialog_content = "O que poderíamos fazer agora, dado o nosso conhecimento atual? Impedi-lo de espetar aquela pobre boneca?",
  ui_story_5043_50431201_81_dialog_content = "Ei, você não acha que essas superstições são verdadeiras... acha?",
  ui_story_5043_50431201_82_dialog_content = "Você quer dizer usar uma boneca para amaldiçoar alguém?",
  ui_story_5043_50431201_83_dialog_content = "Sim...",
  ui_story_5043_50431201_84_dialog_content = "Porque se forem, é possível...",
  ui_story_5043_50431201_85_dialog_content = "... que estamos testemunhando uma cena de assassinato!",
  ui_story_5043_50431201_86_dialog_content = "Agora para o toque final...",
  ui_story_5043_50431201_87_dialog_content = "Deixe esta pequena e miserável existência...",
  ui_story_5043_50431201_88_dialog_content = "Temos que detê-lo! Pressa!",
  ui_story_5043_50431201_89_dialog_content = "<color=#e8d9bb>Facada!</color>",
  ui_story_5043_50431201_90_dialog_content = "— renascer!!!",
  ui_story_5043_50431201_91_dialog_content = "Meu... Você é uma gracinha, não é?",
  ui_story_5043_50431201_92_dialog_content = "Agora então, que nome devo dar a você? Que tal... Castanha?",
  ui_story_5043_50431201_93_dialog_content = "S-Então isso é... um ouriço de pelúcia?",
  ui_story_5043_50431201_94_dialog_content = "Isso com certeza parece um ouriço.",
  ui_story_5043_50431201_95_dialog_content = "Ele até deu um nome apropriado. Ver? Parece uma pequena castanha.",
  ui_story_5043_50431201_96_dialog_content = "<size=45>Então, por que estamos enlouquecendo?!?</size>",
  ui_story_5043_50431201_97_dialog_content = "Shhh! Quieto, PlayerName!",
  ui_story_5043_50431201_98_dialog_content = "Suspiro... Não acredito como somos estúpidos, falando sobre Schwab assassinar alguém.",
  ui_story_5043_50431201_99_dialog_content = "Er, bem, tentativa e erro é apenas uma parte natural de uma investigação.",
  ui_story_5043_50431201_100_dialog_content = "Somente eliminando todas as outras possibilidades a verdade se revelará. É tudo uma parte do processo.",
  ui_story_5043_50431201_101_dialog_content = "Qualquer coisa que te ajude a dormir de noite, Leyn...",
  ui_story_5043_50431201_102_dialog_content = "Ahem... De qualquer forma, vamos esquecer nossa conversa agora e focar em ajudar Tina.",
  ui_story_5043_50431201_103_dialog_content = "Schwab está voltando para dentro agora, provavelmente para se preparar para o julgamento de amanhã.",
  ui_story_5043_50431201_104_dialog_content = "Devemos ir dar uma olhada mais de perto.",
  ui_story_5043_50431201_105_dialog_content = "Suspiro, parece que meu pequeno experimento ainda está longe de ser concluído. Talvez eu faça mais progressos hoje...?",
  ui_story_5043_50431201_106_dialog_content = "Você ouviu isso? Um experimento!",
  ui_story_5043_50431201_107_dialog_content = "Sim, o que ele poderia estar pesquisando lá?",
  ui_story_5043_50431201_108_dialog_content = "Nada de bom, presumo. Afinal, ele é um homem difícil de entender.",
  ui_story_5043_50431201_109_dialog_content = "Não isso de novo, Matthieu...",
  ui_story_5043_50431201_110_dialog_content = "Não vamos tirar conclusões malucas novamente. Não depois da última vez.",
  ui_story_5043_50431201_111_dialog_content = "Talvez seja apenas uma pequena experiência caseira? Pode ser um hobby dele...",
  ui_story_5043_50431201_112_dialog_content = "<color=#e8d9bb>Bang—!</color>",
  ui_story_5043_50431201_113_dialog_content = "Uau!",
  ui_story_5043_50431201_114_dialog_content = "Aquilo foi uma explosão?! O que diabos ele está fazendo aí?!",
  ui_story_5043_50431201_115_dialog_content = "Eu não sei. Devemos chegar um pouco mais perto e ver?",
  ui_story_5043_50431201_116_dialog_content = "Como? Não há onde se esconder naquele quarto!",
  ui_story_5043_50431201_117_dialog_content = "Se chegarmos mais perto do que estamos agora, nosso disfarce será descoberto...",
  ui_story_5043_50431201_118_dialog_content = "<color=#e8d9bb>Bang—!</color>",
  ui_story_5043_50431201_119_dialog_content = "Outra explosão! Será que ele está fazendo uma bomba?!",
  ui_story_5043_50431201_120_dialog_content = "Uma bomba?! E-espere, estamos tirando conclusões precipitadas de novo!",
  ui_story_5043_50431201_121_dialog_content = "E porque não? Este é mais ou menos o negócio familiar dos Salars!",
  ui_story_5043_50431201_122_dialog_content = "<color=#e8d9bb>Bang—!</color>",
  ui_story_5043_50431201_123_dialog_content = "Mas por que ele estaria pesquisando explosivos?",
  ui_story_5043_50431201_124_dialog_content = "Bem, quanto mais elaborado for um lugar, mais suscetível ele será a explosivos. Lumópolis não é exceção.",
  ui_story_5043_50431201_125_dialog_content = "Pense bem: alguém entraria na justiça pelo vandalismo das estátuas.",
  ui_story_5043_50431201_126_dialog_content = "E se for uma torre de relógio ou uma igreja? As consequências seriam muito mais inimagináveis.",
  ui_story_5043_50431201_127_dialog_content = "Aproveitando o poder destrutivo das bombas, eles podem usar o medo para forçar os outros a obedecê-los!",
  ui_story_5043_50431201_128_dialog_content = "Não sei... Sua \"bomba\" não arranhou nem um arranhão em sua casa.",
  ui_story_5043_50431201_129_dialog_content = "É por isso que ele chamou de \"pequeno experimento\"!",
  ui_story_5043_50431201_130_dialog_content = "Depois de entender completamente a ciência por trás disso, ele pode usar Luminatics para tornar suas bombas cem vezes mais poderosas!",
  ui_story_5043_50431201_131_dialog_content = "Se ele for bem-sucedido, Schwab pode derrubar toda a nossa sociedade como a conhecemos!",
  ui_story_5043_50431201_132_dialog_content = "Toda Lumopolis pode até cair sob seu controle...",
  ui_story_5043_50431201_133_dialog_content = "I-É tão sério assim?!",
  ui_story_5043_50431201_134_dialog_content = "<color=#e8d9bb>Bang—!</color>",
  ui_story_5043_50431201_135_dialog_content = "*Cof Cof*",
  ui_story_5043_50431201_136_dialog_content = "Ah, outra tentativa fracassada.",
  ui_story_5043_50431201_137_dialog_content = "Quem diria que fazer <color=#FFB400>pudim de caramelo</color> poderia ser tão difícil?",
  ui_story_5043_50431201_138_dialog_content = "...",
  ui_story_5043_50431201_139_dialog_content = "Então, você está dizendo que ele vai dominar Lumopolis... com PUDDING?!?",
  ui_story_5043_50431201_140_dialog_content = "E-Ele é algum tipo de idiota?! Como ele consegue produzir explosões enquanto faz sobremesas?!",
  ui_story_5043_50431201_141_dialog_content = "Aqui está uma pergunta melhor: como ambas as suas suposições podem estar tão completa e totalmente erradas?!",
  ui_story_5043_50431201_142_dialog_content = "Shhh! Ele está voltando para fora! Rápido, esconda-se!",
  ui_story_5043_50431201_143_dialog_content = "Suspiro... Outra perda de tempo e esforço.",
  ui_story_5043_50431201_144_dialog_content = "Talvez seja hora de fazer algo mais produtivo? Agora, onde eu coloquei a chave do porão... Ah, aqui está.",
  ui_story_5043_50431201_145_dialog_content = "Eu deveria verificar as coisas uma última vez antes do julgamento de amanhã...",
  ui_story_5043_50431201_146_dialog_content = "Perdoe-me, mestre Schwab, mas o jantar está pronto.",
  ui_story_5043_50431201_147_dialog_content = "Não deixei bem claro que não quero ser incomodado agora?!",
  ui_story_5043_50431201_148_dialog_content = "F-Perdoe-me, Mestre! Não quis ofender... Mas a comida já está na mesa...",
  ui_story_5043_50431201_149_dialog_content = "Ugh... Muito bem, mas que esta seja a última vez que você me interrompa!",
  ui_story_5043_50431201_150_dialog_content = "Schwab foi jantar. Acho que não conseguiremos segui-lo até lá, não com todos aqueles criados por perto.",
  ui_story_5043_50431201_151_dialog_content = "Você ouviu o que ele disse antes de sair?",
  ui_story_5043_50431201_152_dialog_content = "Deixe-me adivinhar, tem algo a ver com ele ser \"difícil de entender\"?",
  ui_story_5043_50431201_153_dialog_content = "Muito engraçado, mas não - ele mencionou algo sobre um porão.",
  ui_story_5043_50431201_154_dialog_content = "Use seu cérebro pelo menos uma vez, sim? Pouco antes de ser chamado para jantar, ele pegou uma chave do porão da mansão.",
  ui_story_5043_50431201_155_dialog_content = "E olhe! Ele deixou aquela chave na fechadura ali!",
  ui_story_5043_50431201_156_dialog_content = "Vamos dar uma olhada lá dentro? Quem sabe que segredos encontraremos além daquela porta!",
  ui_story_5043_50431201_157_dialog_content = "Parece a oportunidade perfeita e tudo mais, mas...",
  ui_story_5043_50431201_158_dialog_content = "Ainda não encontramos nada que nos ajude a provar a inocência de Tina! Não sei se invadir o porão de Schwab é a ideia certa.",
  ui_story_5043_50431201_159_dialog_content = "Se você realmente acredita que ela é inocente, então a verdade tem que estar aqui na casa de Schwab em algum lugar.",
  ui_story_5043_50431201_160_dialog_content = "Mesmo que ele seja apenas um peão nisso tudo, deve haver algum tipo de pista deixada para trás.",
  ui_story_5043_50431201_161_dialog_content = "Se ainda não o encontramos, é porque não cavamos fundo o suficiente!",
  ui_story_5043_50431201_162_dialog_content = "... Você tem razão. Não há como voltar atrás agora... Então vamos ver o que tem naquele porão!",
  ui_story_5043_50431201_163_dialog_content = "<color=#e8d9bb>Crec...</color>",
  ui_story_5043_50431201_164_dialog_content = "Está escuro como breu lá dentro... Não consigo ver nada!",
  ui_story_5043_50431201_165_dialog_content = "Parece haver uma escada que leva mais para baixo. Podemos tentar sentir o nosso caminho a seguir...",
  ui_story_5043_50431201_166_dialog_content = "Tina? Tina! Você está aqui?",
  ui_story_5043_50431201_167_dialog_content = "Espera... pensei PlayerName tinha alguns poderes psíquicos?",
  ui_story_5043_50431201_168_dialog_content = "Você pode usá-los para sentir o que está por vir?",
  ui_story_5043_50431201_169_dialog_content = "Posso tentar, sim.",
  ui_story_5043_50431201_170_option_content = "Aumento de Força",
  ui_story_5043_50431201_171_dialog_content = "Ter um celestita ao lado pode ser bastante útil às vezes, não?",
  ui_story_5043_50431201_172_dialog_content = "Bem? O que você vê?",
  ui_story_5043_50431201_173_dialog_content = "Existem fontes de luz que podemos usar, como velas ou uma tocha?",
  ui_story_5043_50431201_174_dialog_content = "Esta adega parece descer muito...",
  ui_story_5043_50431201_175_dialog_content = "... Huh? Algo está vindo em nossa direção!",
  ui_story_5043_50431201_176_dialog_content = "É aquele...",
  ui_story_5043_50431201_177_dialog_content = "Graaaah—",
  ui_story_5043_50431201_178_dialog_content = "Wahhhhhhh—",
  ui_story_5043_50431201_179_dialog_content = "O que é? O que você viu?!",
  ui_story_5043_50431201_180_dialog_content = "C-corram! Volte para a entrada!",
  ui_story_5043_50431201_181_dialog_content = "Uma multidão de Eclipsites está vindo em nossa direção!",
  ui_story_5043_50431202_1_dialog_content = "Graah...",
  ui_story_5043_50431202_2_dialog_content = "Eclipsitos? O que essas criaturas imundas estão fazendo no porão de Schwab?!",
  ui_story_5043_50431202_3_dialog_content = "Aparentemente, os nobres gostam mais do que apenas as coisas boas da vida!",
  ui_story_5043_50431202_4_dialog_content = "Não nos agrupe com sua calúnia vil! Eu quero que você saiba que minha família nunca abrigaria monstros tão nojentos em nossa casa!",
  ui_story_5043_50431202_5_dialog_content = "Chega, pessoal! Eles estão se aproximando!",
  ui_story_5043_50431202_6_dialog_content = "Vou adiar os Eclipsitos! Vocês dois saiam daqui o mais rápido que puderem!",
  ui_story_5043_50431202_7_dialog_content = "A-Tem certeza?",
  ui_story_5043_50431202_8_dialog_content = "Claro que sou! Não subestime um juiz de Lumopolis!",
  ui_story_5043_50431202_9_dialog_content = "Tudo bem, sua escória do Eclipsite... Pegue isso!",
  ui_story_5043_50431202_10_dialog_content = "<color=#e8d9bb>Colidir-!</color>",
  ui_story_5043_50431202_11_dialog_content = "Oh céus! Você acabou de quebrar o lustre deles!",
  ui_story_5043_50431202_12_dialog_content = "Parece ser feito de cristais de Northland? Ou seja, era um acessório bastante caro.",
  ui_story_5043_50431202_13_dialog_content = "Opa! Acha que vão me pedir para pagar por isso...?",
  ui_story_5043_50431202_14_dialog_content = "Você está preocupado com dinheiro em um momento como este?! Concentre-se nos Eclipsitos!",
  ui_story_5043_50431202_15_dialog_content = "Lá vêm eles de novo...",
  ui_story_5043_50431202_16_dialog_content = "<color=#e8d9bb>Colidir-!</color>",
  ui_story_5043_50431202_17_dialog_content = "Ótimo! Agora a mesa de chá deles também está arruinada!",
  ui_story_5043_50431202_18_dialog_content = "E, a julgar por seu artesanato requintado, tenho certeza de que Schwab também vai perder o sono por causa disso.",
  ui_story_5043_50431202_19_dialog_content = "Sinto muito! Mas acho que não sou eu que devo pagar, já que a culpa é dos Eclipsitas em primeiro lugar...",
  ui_story_5043_50431202_20_dialog_content = "Agora não é a hora, vocês dois! Olha, ali está a porta!",
  ui_story_5043_50431202_21_dialog_content = "Precisamos sair agora mesmo!",
  ui_story_5043_50431202_22_dialog_content = "<color=#e8d9bb>Dez minutos depois...</color>",
  ui_story_5043_50431202_23_dialog_content = "Vasculhamos todo o perímetro da propriedade, Mestre Schwab... Mas ainda não há sinal de intrusos.",
  ui_story_5043_50431202_24_dialog_content = "Que bagunça... Quem ou o que poderia ter causado tudo isso?",
  ui_story_5043_50431202_25_dialog_content = "... Tem certeza de que não viu nenhum intruso?",
  ui_story_5043_50431202_26_dialog_content = "Sim mestre. Tudo parece seguro, pelo menos por enquanto.",
  ui_story_5043_50431202_27_dialog_content = "É bem possível que o culpado ou culpados sejam especialistas... Se eles deixaram alguma pista, ainda não as encontramos.",
  ui_story_5043_50431202_28_dialog_content = "Talvez seja melhor... deixar isso para o Tribunal de Justiça?",
  ui_story_5043_50431202_29_dialog_content = "Certamente, eles investigariam o assunto com toda a seriedade, dado o seu estado?",
  ui_story_5043_50431202_30_dialog_content = "Uma investigação...",
  ui_story_5043_50431202_31_dialog_content = "Não, isso não será necessário.",
  ui_story_5043_50431202_32_dialog_content = "Afinal, eram apenas alguns móveis. O que foi perdido pode ser facilmente substituído.",
  ui_story_5043_50431202_33_dialog_content = "Por enquanto, peça para alguém limpar essa bagunça imediatamente.",
  ui_story_5043_50431202_34_dialog_content = "Sim, Senhor Schwab!",
  ui_story_5043_50431202_35_dialog_content = "(A porta do porão está aberta...)",
  ui_story_5043_50431202_36_dialog_content = "(Eu desbloqueei antes de sair para jantar?)",
  ui_story_5043_50431202_37_dialog_content = "(Para eu cometer um erro tão tolo... É quase insondável.)",
  ui_story_5043_50431202_38_dialog_content = "(Eu deveria ir para a cama cedo esta noite. Vou precisar de uma cabeça limpa para o julgamento de amanhã.)",
  ui_story_5043_50431202_39_dialog_content = "Suspiro, o que diabos aconteceu aqui?",
  ui_story_5043_50431202_40_dialog_content = "Que tipo de vilão invade a casa de alguém, apenas para destruir o lustre e a mesa de chá?",
  ui_story_5043_50431202_41_dialog_content = "Ainda assim... esses pedaços quebrados podem conseguir um bom preço com o negociante de sucata certo.",
  ui_story_5043_50431202_42_dialog_content = "Arf, arf...",
  ui_story_5043_50431202_43_dialog_content = "(Finalmente... finalmente fora!)",
  ui_story_5043_50431202_44_dialog_content = "Alguém conseguiu nos seguir?",
  ui_story_5043_50431202_45_dialog_content = "Eu não acho. Parece que a costa está limpa.",
  ui_story_5043_50431202_46_dialog_content = "Tsk. Que vergonha - um dia inteiro desperdiçado em travessuras inúteis.",
  ui_story_5043_50431202_47_dialog_content = "O pior é que não conseguimos encontrar Tina, ou mesmo a menor pista que poderia ajudá-la.",
  ui_story_5043_50431202_48_dialog_content = "Como ela deve passar pelo julgamento agora?",
  ui_story_5043_50431202_49_dialog_content = "Fizemos tudo o que pudemos... Resta-nos cumprir os nossos deveres de juízes.",
  ui_story_5043_50431202_50_dialog_content = "Antes do início do julgamento, precisamos levar em conta tudo o que aconteceu hoje.",
  ui_story_5043_50431202_51_dialog_content = "É possível que as pistas que procuramos estejam escondidas nos detalhes em algum lugar.",
  ui_story_5043_50431202_52_dialog_content = "Nem é preciso dizer que cumpriremos nossos deveres com o melhor de nossas habilidades. No entanto...",
  ui_story_5043_50431202_53_dialog_content = "Sem provas definitivas, somos tão impotentes quanto qualquer outra pessoa para mudar o resultado do julgamento.",
  ui_story_5043_50431202_54_dialog_content = "Sem falar que não temos ideia de quais outros truques Schwab ainda tem na manga.",
  ui_story_5043_50431202_55_dialog_content = "Ir a julgamento contra ele assim seria inútil, para dizer o mínimo.",
  ui_story_5043_50431202_56_dialog_content = "Há mais de uma maneira de ganhar, Matthieu.",
  ui_story_5043_50431202_57_dialog_content = "Podemos não ter todas as cartas que precisamos em nossas mãos, mas isso não significa que estamos fora do jogo ainda.",
  ui_story_5043_50431202_58_dialog_content = "Oh, que coisa, estamos nos sentindo tão seguros de nós mesmos, não estamos?",
  ui_story_5043_50431202_59_dialog_content = "Não em nós mesmos, mas na verdade.",
  ui_story_5043_50431202_60_dialog_content = "O trabalho de um lado é esconder a verdade, enquanto o do outro é revelá-la. Sabendo disso, temos uma clara vantagem no caso.",
  ui_story_5043_50431202_61_dialog_content = "Além disso, nossa pequena viagem à casa de Schwab não foi totalmente infrutífera...",
  ui_story_5043_50431301_1_dialog_content = "<color=#e8d9bb>No dia seguinte</color>",
  ui_story_5043_50431301_2_dialog_content = "(Então finalmente está prestes a começar...)",
  ui_story_5043_50431301_3_dialog_content = "(O julgamento de Serial Statue Decapitations estará em sessão em breve.)",
  ui_story_5043_50431301_4_dialog_content = "(Leyn, Matthieu, e Tina... Eles serão capazes de expor a verdade perante o tribunal?)",
  ui_story_5043_50431301_5_dialog_content = "PlayerName!",
  ui_story_5043_50431301_6_dialog_content = "Carleen! E Loewe também!",
  ui_story_5043_50431301_7_dialog_content = "Você conseguiu voltar!",
  ui_story_5043_50431301_8_dialog_content = "Claro. Dei a todos minha palavra que estaria aqui para o julgamento, não dei?",
  ui_story_5043_50431301_9_dialog_content = "No entanto, algo preocupante foi trazido à minha atenção...",
  ui_story_5043_50431301_10_dialog_content = "eu ouvi isso Tina é o réu?",
  ui_story_5043_50431301_11_dialog_content = "Matthieu, você realmente se superou desta vez.",
  ui_story_5043_50431301_12_dialog_content = "Eu te desafio a dizer isso de novo...!",
  ui_story_5043_50431301_13_dialog_content = "Th-Isso mesmo, sim...",
  ui_story_5043_50431301_14_dialog_content = "Tina foi nomeado o principal suspeito no caso depois que algumas evidências bizarras vieram à tona.",
  ui_story_5043_50431301_15_dialog_content = "Mas tenho certeza que tudo vai dar certo!",
  ui_story_5043_50431301_16_dialog_content = "O que exatamente aconteceu nos últimos dois dias?",
  ui_story_5043_50431301_17_dialog_content = "É meio que uma longa história. Contarei mais quando estivermos dentro do tribunal.",
  ui_story_5043_50431301_18_dialog_content = "<color=#e8d9bb>O Hall of Justice, Divisão Romance, Lumopolis Gardens</color>",
  ui_story_5043_50431301_19_dialog_content = "Ordem, ordem!",
  ui_story_5043_50431301_20_dialog_content = "Primeiro, permita-me pedir desculpas a todos por ter que fazer tantas viagens ao tribunal para este caso.",
  ui_story_5043_50431301_21_dialog_content = "Infelizmente, não conseguimos evitar que o culpado cometesse várias instâncias desse crime hediondo.",
  ui_story_5043_50431301_22_dialog_content = "Parece que hoje é o dia em que esse vilão finalmente será levado à justiça!",
  ui_story_5043_50431301_23_dialog_content = "Agora, sem mais delongas—",
  ui_story_5043_50431301_24_dialog_content = "<color=#e8d9bb>Tum!</color>",
  ui_story_5043_50431301_25_dialog_content = "O julgamento de Serial Statue Decapitations está agora em sessão!",
  ui_story_5043_50431301_26_dialog_content = "...",
  ui_story_5043_50431301_27_dialog_content = "...",
  ui_story_5043_50431301_28_dialog_content = "<size=30>Vocês caras...</size>",
  ui_story_5043_50431301_29_dialog_content = "<size=30>Acredite neles. É tudo o que podemos fazer agora.</size>",
  ui_story_5043_50431301_30_dialog_content = "Primeiro, vamos apresentar as partes envolvidas no litígio de hoje!",
  ui_story_5043_50431301_31_dialog_content = "Para a acusação, Sr. Byron.",
  ui_story_5043_50431301_32_dialog_content = "E para a defesa, Tina Campbell.",
  ui_story_5043_50431301_33_dialog_content = "É uma grande vergonha para nós ver um de nossos próprios juízes da Divisão de Romance ser julgado por um crime tão vil. Mas todos são iguais aos olhos da lei e todos devem ser responsabilizados por seus pecados.",
  ui_story_5043_50431301_34_dialog_content = "Inacreditável...",
  ui_story_5043_50431301_35_dialog_content = "Eu, Schwab Salar, presidirei como juiz principal no julgamento de hoje.",
  ui_story_5043_50431301_36_dialog_content = "Juízes Matthieu Sawyer e Leyn participará do julgamento, assim como outros membros respeitados do júri.",
  ui_story_5043_50431301_37_dialog_content = "Hmph, você finalmente aprendeu a mostrar algum respeito aos mais velhos.",
  ui_story_5043_50431301_38_dialog_content = "Nossas contribuições para a investigação são tão importantes quanto as de qualquer outra pessoa!",
  ui_story_5043_50431301_39_dialog_content = "Diga-me, quais são seus pensamentos sobre o caso até agora?",
  ui_story_5043_50431301_40_dialog_content = "...",
  ui_story_5043_50431301_41_dialog_content = "...",
  ui_story_5043_50431301_42_dialog_content = "Ah sim, quase esqueci que devemos manter nosso silêncio por enquanto...",
  ui_story_5043_50431301_43_dialog_content = "Os detalhes básicos do caso estão descritos nos documentos colocados à sua frente. Todos são convidados a revisá-los a seu próprio critério.",
  ui_story_5043_50431301_44_dialog_content = "Graças em grande parte aos nossos esforços investigativos completos, finalmente estabelecemos uma cadeia clara de eventos.",
  ui_story_5043_50431301_45_dialog_content = "Em seguida, farei uma breve declaração sobre as conclusões dos referidos esforços investigativos sobre o caso das Decapitações de Estátuas Seriais.",
  ui_story_5043_50431301_46_dialog_content = "Nossas conclusões mostram que o réu, Tina Campbell, recorreu à destruição de estátuas para divulgar seu profundo ressentimento em relação à onda de amor que varreu toda Lumopolis.",
  ui_story_5043_50431301_47_dialog_content = "Nos dois incidentes anteriores, ela usou mal sua autoridade como juíza para destruir qualquer evidência que apontasse para seu delito.",
  ui_story_5043_50431301_48_dialog_content = "Mas graças ao Sr. Byron e seu relatório oportuno, o Juiz Leyn estava totalmente preparado para o terceiro e último incidente.",
  ui_story_5043_50431301_49_dialog_content = "E foi na cena do crime que ele conseguiu obter uma prova vital do perpetrador...",
  ui_story_5043_50431301_50_dialog_content = "Esta luva!",
  ui_story_5043_50431301_51_dialog_content = "Esplêndido! Isso deve ser mais do que suficiente para incriminar o réu!",
  ui_story_5043_50431301_52_dialog_content = "De fato. Lancei uma investigação sobre o dono desta luva e meus subordinados se depararam com uma descoberta surpreendente - a outra luva foi encontrada na gaveta de uma mesa pertencente a ninguém menos que o juiz Tina Campbell!",
  ui_story_5043_50431301_53_dialog_content = "Ora, é uma combinação perfeita!",
  ui_story_5043_50431301_54_dialog_content = "E nossa investigação confirmou o mesmo. Ambas as luvas faziam parte de um conjunto pertencente a um único dono...",
  ui_story_5043_50431301_55_dialog_content = "E esse proprietário está diante de nós hoje, no assento do réu—Tina Campbell!",
  ui_story_5043_50431301_56_dialog_content = "Não é desse jeito...",
  ui_story_5043_50431301_X56_dialog_content = "Uau! O Juiz Chefe Schwab é durão além de sua idade!",
  ui_story_5043_50431301_57_dialog_content = "Com base nas provas irrefutáveis fornecidas, o tribunal propõe que o arguido seja acusado de destruição de propriedade pública, bem como de subversão do romance!",
  ui_story_5043_50431301_58_dialog_content = "Naturalmente, você é livre para justificar seu comportamento repugnante da maneira que achar melhor.",
  ui_story_5043_50431301_59_dialog_content = "Apenas saiba que nada menos que a intervenção divina influenciará o júri a inocentá-lo de todas as acusações.",
  ui_story_5043_50431301_60_dialog_content = "Por que você...",
  ui_story_5043_50431301_61_dialog_content = "Dificilmente acho isso possível!",
  ui_story_5043_50431301_62_dialog_content = "A qualidade mais importante que temos aqui ao presidir um caso é a imparcialidade!",
  ui_story_5043_50431301_63_dialog_content = "Não é verdade, meus colegas jurados?",
  ui_story_5043_50431301_64_dialog_content = "...",
  ui_story_5043_50431301_65_dialog_content = "...",
  ui_story_5043_50431301_66_dialog_content = "Não sei mais o que dizer dessa luva...",
  ui_story_5043_50431301_67_dialog_content = "É verdade que me pertence, mas nunca o levei ao local do crime.",
  ui_story_5043_50431301_68_dialog_content = "Eu estava lutando contra os Eclipsites na época e não tinha como chegar perto daquela estátua, muito menos desfigurá-la.",
  ui_story_5043_50431301_69_dialog_content = "Quando cheguei à estátua, o estrago já estava feito...",
  ui_story_5043_50431301_70_dialog_content = "Há alguma testemunha que possa atestar isso?",
  ui_story_5043_50431301_71_dialog_content = "Eu...",
  ui_story_5043_50431301_72_dialog_content = "Me desculpe, mas eu tinha me separado de todos na época, então não havia testemunhas...",
  ui_story_5043_50431301_73_dialog_content = "Então parece que seu testemunho é incapaz de derrubar nossa conclusão atual.",
  ui_story_5043_50431301_74_dialog_content = "Se você não tem nenhuma outra evidência convincente para oferecer, então, pelos crimes de destruição de propriedade pública e subversão do amor, nós o encontramos—",
  ui_story_5043_50431301_75_dialog_content = "<size=45>Espere!!!</size>",
  ui_story_5043_50431301_76_dialog_content = "... Sim, Juiz Matthieu?",
  ui_story_5043_50431301_77_dialog_content = "Temo que devo contestar sua decisão, Juiz Schwab!",
  ui_story_5043_50431301_78_dialog_content = "Tina não poderia ser o culpado por trás dessas decapitações de estátuas em série! Ela tem evidências que provam que ela nunca esteve na cena do crime!",
  ui_story_5043_50431301_79_dialog_content = "Heh, ela tem, agora?",
  ui_story_5043_50431301_80_dialog_content = "Então vamos ouvir o que você tem a dizer, juiz Matthieu.",
  ui_story_5043_50431301_81_dialog_content = "E lembre-se de ser o mais racional e objetivo possível em sua defesa.",
  ui_story_5043_50431301_82_dialog_content = "Caso contrário, podemos encontrar evidências de cúmplices em seus crimes.",
  ui_story_5043_50431301_83_dialog_content = "Aham. Voltemos ao início do caso.",
  ui_story_5043_50431301_84_dialog_content = "Ou seja, o primeiro incidente de uma estátua sendo decapitada.",
  ui_story_5043_50431301_85_dialog_content = "Já investiguei minuciosamente as ações dos culpados naquele dia.",
  ui_story_5043_50431301_86_dialog_content = "Infelizmente, o réu não pode provar que ela não estava na cena do crime.",
  ui_story_5043_50431301_87_dialog_content = "Não, Meritíssimo... Mas o que mais importa é o que aconteceu DEPOIS que o crime foi cometido!",
  ui_story_5043_50431301_88_dialog_content = "Aquela tarde, Tina e eu estávamos no Tribunal de Justiça, onde trabalhamos juntos por aproximadamente quatro horas.",
  ui_story_5043_50431301_89_dialog_content = "Posso atestar isso pessoalmente, assim como os outros membros do Salão que estavam presentes naquele dia.",
  ui_story_5043_50431301_90_dialog_content = "Muito bem, então vocês trabalharam juntos por quatro horas. O que então?",
  ui_story_5043_50431301_91_dialog_content = "Ela poderia facilmente ter cometido o crime antes de voltar a trabalhar com você no Tribunal de Justiça.",
  ui_story_5043_50431301_92_dialog_content = "Errado, Meritíssimo! Essas quatro horas são a prova positiva de que ela nunca esteve na cena do crime!",
  ui_story_5043_50431301_93_dialog_content = "Você vê, Tina sofre de uma forma rara de hipersonia. Qualquer hospital em Lumopolis também pode atestar isso.",
  ui_story_5043_50431301_94_dialog_content = "Como resultado, o máximo que ela pode permanecer acordada durante um determinado dia é de aproximadamente quatro horas!",
  ui_story_5043_50431301_95_dialog_content = "...",
  ui_story_5043_50431301_96_dialog_content = "Em outras palavras, fora as quatro horas que passamos trabalhando juntos, ela deve ter dormido o resto do tempo!",
  ui_story_5043_50431301_97_dialog_content = "Como tal, não há como ela ter vandalizado a primeira estátua!",
  ui_story_5043_50431301_98_dialog_content = "Ela está até dormindo no trabalho!?",
  ui_story_5043_50431301_99_dialog_content = "Ela não tem vergonha? Alguém pode realmente ser pago para não fazer nada hoje em dia?",
  ui_story_5043_50431301_100_dialog_content = "Isso mesmo! Eu estava dormindo na hora!",
  ui_story_5043_50431301_101_dialog_content = "Eu não ouvi sobre a estátua até depois de acordar.",
  ui_story_5043_50431301_102_dialog_content = "Bem então? Isso é prova de que ela não é culpada pela primeira estátua?",
  ui_story_5043_50431301_103_dialog_content = "Você chama isso de argumento?",
  ui_story_5043_50431301_104_dialog_content = "Usando mera especulação não apenas para estabelecer um álibi para a ré, mas também para julgar todo o seu julgamento!",
  ui_story_5043_50431301_105_dialog_content = "Se nosso sistema de justiça fosse tão frívolo, não precisaríamos de coisas como evidências ou testemunhos!",
  ui_story_5043_50431301_106_dialog_content = "Eu entendo, Meritíssimo! Você deseja ver evidências, sim?",
  ui_story_5043_50431301_107_dialog_content = "Então, permita-me passar para a segunda instância da decapitação da estátua.",
  ui_story_5043_50431301_108_dialog_content = "Assim como o primeiro incidente, há evidências suficientes aqui provando Tina Campbell não estava na cena do crime.",
  ui_story_5043_50431301_109_dialog_content = "Para isso, o juiz Leyn e eu posso servir como testemunhas.",
  ui_story_5043_50431301_110_dialog_content = "Hmph! Tem certeza que quis dizer testemunhas e não cúmplices, Juiz Matthieu?",
  ui_story_5043_50431301_111_dialog_content = "Ora, ora, como respeitados juízes do Tribunal de Justiça, não estamos todos do mesmo lado, Meritíssimo?",
  ui_story_5043_50431301_112_dialog_content = "Ah, mas não importa... Tem mais uma pessoa aqui hoje que também pode servir como testemunha.",
  ui_story_5043_50431301_113_dialog_content = "E acredito que alguém na posição dela seria mais do que suficiente para provar a inocência de Tina.",
  ui_story_5043_50431301_114_dialog_content = "A menos, é claro, que você queira insinuar que a princesa de Lumopolis também é cúmplice desse crime?",
  ui_story_5043_50431301_115_dialog_content = "...",
  ui_story_5043_50431301_116_dialog_content = "... Dela?",
  ui_story_5043_50431301_117_dialog_content = "No momento do segundo incidente, estávamos todos na Meadow Square do Lumopolis Courtyard, respondendo a uma crise.",
  ui_story_5043_50431301_118_dialog_content = "Entendo o que você está dizendo. Mas precisamos restaurar a ordem primeiro.",
  ui_story_5043_50431301_119_dialog_content = "Por favor, não entre em pânico. Me siga!",
  ui_story_5043_50431301_120_dialog_content = "<color=#e8d9bb>Esmagar-!</color>",
  ui_story_5043_50431301_121_dialog_content = "(O que foi aquele barulho?!)",
  ui_story_5043_50431301_122_dialog_content = "Fui o primeiro a ouvir o som da estátua sendo destruída. Pouco depois, o juiz Tina e fui investigar.",
  ui_story_5043_50431301_123_dialog_content = "Ao chegar à cena do crime, nós dois descobrimos que a estátua estava sem cabeça.",
  ui_story_5043_50431301_124_dialog_content = "Em nenhum momento no decorrer dos eventos daquele dia, o juiz Tina nunca deixe minha vista. Como tal, posso atestar, com toda a certeza, que ela não estava no local do crime quando a segunda estátua foi decapitada.",
  ui_story_5043_50431301_125_dialog_content = "eu acredito senhora Carleen e a freira pode corroborar isso.",
  ui_story_5043_50431301_126_dialog_content = "É verdade. Antes do incidente, Tina esteve conosco o tempo todo.",
  ui_story_5043_50431301_127_dialog_content = "Ela não tinha como cometer o crime.",
  ui_story_5043_50431301_128_dialog_content = "De fato. Eu também posso testemunhar a falta de envolvimento da juíza Tina no crime.",
  ui_story_5043_50431301_129_dialog_content = "Bem, Meritíssimo?",
  ui_story_5043_50431301_130_dialog_content = "Esses depoimentos são evidências suficientes para você?",
  ui_story_5043_50431301_131_dialog_content = "Bem bem.",
  ui_story_5043_50431301_132_dialog_content = "O tribunal respeita e reconhece qualquer testemunho prestado por Lady Carleen.",
  ui_story_5043_50431301_133_dialog_content = "Além disso, suas palavras e paixão tiveram um efeito sobre mim, Juiz Matthieu.",
  ui_story_5043_50431301_134_dialog_content = "Parece que eu estava errado em acusar a senhorita Tina Campbell, afinal.",
  ui_story_5043_50431301_135_dialog_content = "(D-acabamos de ganhar?)",
  ui_story_5043_50431301_136_dialog_content = "O tribunal se retrata de seu julgamento anterior! Entendemos que o réu, Tina Campbell, não é o perpetrador por trás das decapitações de estátuas em série.",
  ui_story_5043_50431301_137_dialog_content = "Nós, no entanto, a consideramos culpada do <color=#FFB400>terceira instância</color> da decapitação de uma estátua!",
  ui_story_5043_50431301_138_dialog_content = "Eh...?",
  ui_story_5043_50431301_139_dialog_content = "Aff.",
  ui_story_5043_50431301_140_dialog_content = "Orgulhe-se de seus esforços, juiz Matthieu! Sem eles, a pena do réu será bastante reduzida.",
  ui_story_5043_50431301_141_dialog_content = "No entanto! Enquanto a evidência crucial fornecida anteriormente permanecer incontestada...",
  ui_story_5043_50431301_142_dialog_content = "... o tribunal ainda vai encontrar Tina Campbell culpado de destruir propriedade pública, bem como subverter o romance!",
  ui_story_5043_50431301_143_dialog_content = "Mas você já sabia disso, não é, juiz? Matthieu?",
  ui_story_5043_50431301_144_dialog_content = "Um absurdo completo...",
  ui_story_5043_50431301_145_dialog_content = "Dito isso, você ainda deseja continuar negando as provas irrefutáveis trazidas ao tribunal hoje?",
  ui_story_5043_50431301_146_dialog_content = "...",
  ui_story_5043_50431301_147_dialog_content = "<size=30>Mantenha-se firme, Matthieu...</size>",
  ui_story_5043_50431301_148_dialog_content = "<size=30>Ainda não é o suficiente...</size>",
  ui_story_5043_50431301_149_dialog_content = "Não, Meritíssimo. Eu disse tudo o que precisava dizer.",
  ui_story_5043_50431301_150_dialog_content = "O quê...?",
  ui_story_5043_50431301_151_dialog_content = "Heheheh, é mesmo?",
  ui_story_5043_50431301_152_dialog_content = "Sim, Meritíssimo.",
  ui_story_5043_50431301_153_dialog_content = "Nesse caso, o tribunal por meio deste—",
  ui_story_5043_50431301_154_dialog_content = "É sua vez, Leyn.",
  ui_story_5043_50431301_155_dialog_content = "!!!",
  ui_story_5043_50431301_156_dialog_content = "Leyn?",
  ui_story_5043_50431301_157_dialog_content = "Vá em frente, então. Os recém-chegados raramente recebem oportunidades como essa.",
  ui_story_5043_50431301_158_dialog_content = "Entendi.",
  ui_story_5043_50431301_159_dialog_content = "Juiz principal Schwab, outros membros do júri e todos os que estão aqui reunidos hoje.",
  ui_story_5043_50431301_160_dialog_content = "Peço humildemente alguns minutos do seu tempo.",
  ui_story_5043_50431301_161_dialog_content = "Para que possamos <color=#FFB400>fazer inferências</color> de nossa compreensão do crime.",
  ui_story_5043_50431301_162_dialog_content = "Huh, esse garoto é meio louco.",
  ui_story_5043_50431301_163_dialog_content = "Você faria bem em escolher suas palavras com sabedoria, Juiz Leyn. Especialmente considerando seu passado \"humilde\".",
  ui_story_5043_50431301_164_dialog_content = "Ao contrário do juiz Matthieu, você não tem o apoio de uma família nobre caso a qualidade do seu trabalho seja questionada.",
  ui_story_5043_50431301_165_dialog_content = "E ao contrário de você, Juiz Schwab, não acredito que minha origem comum seja necessariamente um obstáculo.",
  ui_story_5043_50431301_166_dialog_content = "No mínimo, minhas ações não têm como refletir ignóbilmente sobre a ilustre casta nobre.",
  ui_story_5043_50431301_167_dialog_content = "Você...",
  ui_story_5043_50431301_168_dialog_content = "Mas vamos voltar ao caso em questão, certo? Meritíssimo parece ser bastante insistente nessa peça de evidência crucial...",
  ui_story_5043_50431301_169_dialog_content = "Sugiro que façamos uma revisão ainda mais detalhada deste caso e não deixemos pedra sobre pedra.",
  ui_story_5043_50431301_170_dialog_content = "Ao examinar minuciosamente cada detalhe, acredito que encontraremos algum vestígio do verdadeiro culpado - algo que nos apontará na direção da verdade!",
  ui_story_5043_50431301_171_dialog_content = "Ohhh! Que profissional! Eu gosto de como as coisas estão acontecendo!",
  ui_story_5043_50431301_172_dialog_content = "(Algum vestígio do verdadeiro culpado, hein...)",
  ui_story_5043_50431301_173_dialog_content = "(Você finalmente descobriu algo, Leyn?)",
  ui_story_5043_50431301_174_dialog_content = "Vamos relembrar o que aconteceu na Stairway to the Skies ontem, pouco antes do incidente.",
  ui_story_5043_50431301_175_dialog_content = "Para proteger a estátua no topo da escada, tentamos impedir o desfile.",
  ui_story_5043_50431301_176_dialog_content = "Para nossa surpresa, encontramos um grupo de pequenos eclipsitas escondidos logo atrás da procissão.",
  ui_story_5043_50431301_177_dialog_content = "Eu imediatamente os enfrentei na batalha. Não muito tempo depois, o juiz Tina me pegou...",
  ui_story_5043_50431302_1_dialog_content = "Chutei o primeiro Eclipsite escada abaixo.",
  ui_story_5043_50431302_2_dialog_content = "A segunda, empalei com minha arma.",
  ui_story_5043_50431302_3_dialog_content = "O último, no entanto, foi feito em pedaços pelo punho de Tina.",
  ui_story_5043_50431302_4_dialog_content = "Está bem, está bem! Esses detalhes são realmente necessários?",
  ui_story_5043_50431302_5_dialog_content = "Com o pequeno bando de Eclipsitas derrotado, Tina e comecei a voltar para a estátua e me reunir com os outros.",
  ui_story_5043_50431302_6_dialog_content = "Mas a multidão era grande naquele dia e atravessá-la provou ser uma tarefa difícil.",
  ui_story_5043_50431302_7_dialog_content = "Como resultado, eu estava separado de Tina no meio da multidão... Não foi até depois do incidente que eu finalmente a vi novamente.",
  ui_story_5043_50431302_8_dialog_content = "Tentar passar por todas aquelas pessoas foi um pesadelo... eu mal conseguia me mexer na metade do tempo!",
  ui_story_5043_50431302_9_dialog_content = "Nisso podemos concordar.",
  ui_story_5043_50431302_10_dialog_content = "Mas isso não prova que Tina Campbell não estava na cena do crime naquele dia.",
  ui_story_5043_50431302_11_dialog_content = "Vamos deixar isso de lado por um momento, Meritíssimo. Em vez disso, voltemos nossa atenção para o momento em que o incidente ocorreu.",
  ui_story_5043_50431302_12_dialog_content = "Quando finalmente alcancei a estátua, fui emboscado por outro grupo de Eclipsitas.",
  ui_story_5043_50431302_13_dialog_content = "Enquanto estávamos lutando contra os Eclipsites, o culpado teve uma oportunidade perfeita para atacar.",
  ui_story_5043_50431302_14_dialog_content = "Aproveitando o caos ao redor, eles estenderam a mão enluvada e quebraram a cabeça da estátua.",
  ui_story_5043_50431302_15_dialog_content = "Consegui agarrar a mão deles, mas o culpado estava escondido entre os eclipsitas, o que me impediu de dar uma olhada clara em seu rosto ou corpo.",
  ui_story_5043_50431302_16_dialog_content = "No final, o culpado conseguiu escapar de minhas mãos e escapar, deixando para trás uma única luva...",
  ui_story_5043_50431302_17_dialog_content = "A luva que foi fornecida como prova chave no caso, sim.",
  ui_story_5043_50431302_18_dialog_content = "Senhora Carleen e juiz Matthieu fez um breve trabalho com os eclipsitas logo depois, mas o culpado não estava em lugar nenhum.",
  ui_story_5043_50431302_19_dialog_content = "Assim que a poeira baixou, o juiz Tina finalmente reapareceu e se juntou a nós.",
  ui_story_5043_50431302_20_dialog_content = "E isso, senhoras e senhores da corte, é o relato completo dos eventos que cercam a decapitação da estátua.",
  ui_story_5043_50431302_21_dialog_content = "E um relato muito bem formulado, ainda por cima. Obrigado pela sua contribuição, juiz Leyn.",
  ui_story_5043_50431302_22_dialog_content = "Com isso em mente, é lógico que o dono da luva é o autor do crime.",
  ui_story_5043_50431302_23_dialog_content = "Essa, por sua vez, foi a justificativa que nos levou a prender o réu, Tina Campbell.",
  ui_story_5043_50431302_24_dialog_content = "Perdoe-me, Meritíssimo... Mas você está tirando conclusões precipitadas.",
  ui_story_5043_50431302_25_dialog_content = "Como é?",
  ui_story_5043_50431302_26_dialog_content = "Com base nas informações que reunimos na cena do crime sobre o culpado—",
  ui_story_5043_50431302_27_dialog_content = "Sabemos que o culpado conseguiu esmagar a cabeça da estátua com a mão nua enquanto usava aquela luva.",
  ui_story_5043_50431302_28_dialog_content = "A pessoa que você prendeu, por outro lado...",
  ui_story_5043_50431302_29_dialog_content = "É apenas a jovem que é a legítima dona da luva.",
  ui_story_5043_50431302_30_dialog_content = "Se você comparar os dois mais de perto, encontrará mais inconsistências do que qualquer outra coisa.",
  ui_story_5043_50431302_31_dialog_content = "Eu sinto que você está pensando demais nas coisas, Juiz Leyn.",
  ui_story_5043_50431302_32_dialog_content = "Não é lógico que o dono da luva seja a pessoa com maior probabilidade de tê-la usado na cena do crime?",
  ui_story_5043_50431302_33_dialog_content = "Sim, Meritíssimo... Mas você está perdendo o ponto.",
  ui_story_5043_50431302_34_dialog_content = "julga Tina parece que ela pode pulverizar a cabeça de uma estátua com as próprias mãos?",
  ui_story_5043_50431302_35_dialog_content = "Oh? Um novo ângulo?",
  ui_story_5043_50431302_36_dialog_content = "Quando você realmente pensa sobre isso, como uma garotinha poderia quebrar uma estátua com as próprias mãos?",
  ui_story_5043_50431302_37_dialog_content = "Parece que você se perdeu em seus próprios processos de pensamento, juiz Leyn.",
  ui_story_5043_50431302_38_dialog_content = "Você já esqueceu o que disse há menos de dois minutos?",
  ui_story_5043_50431302_39_dialog_content = "Chutei o primeiro Eclipsite escada abaixo.",
  ui_story_5043_50431302_40_dialog_content = "A segunda, empalei com minha arma.",
  ui_story_5043_50431302_41_dialog_content = "A última, porém, foi <color=#FFB400>feito em pedaços pelo punho de Tina</color>.",
  ui_story_5043_50431302_42_dialog_content = "Certamente, você conhece seu colega melhor do que isso? Afinal, ela é a herdeira da Mão Divina da Família Campbell.",
  ui_story_5043_50431302_43_dialog_content = "Para alguém que pode destruir completamente um Eclipsite com um único soco, a cabeça de uma estátua não deve representar nenhum problema.",
  ui_story_5043_50431302_44_dialog_content = "Isso mesmo! Ela não é uma garota comum!",
  ui_story_5043_50431302_45_dialog_content = "Meu jovem, você precisa pensar um pouco mais em suas deduções.",
  ui_story_5043_50431302_46_dialog_content = "(Acho que ele ficou aquém do alvo, hein?)",
  ui_story_5043_50431302_47_dialog_content = "(Se apenas Leyn foi capaz de dar apenas um pequeno passo à frente do inimigo e encontrar algo que passou despercebido...)",
  ui_story_5043_50431302_48_dialog_content = "Ah sim... Tina herdou a Mão Divina.",
  ui_story_5043_50431302_49_dialog_content = "Então a suposição é que ela o usou para quebrar a cabeça da estátua, correto?",
  ui_story_5043_50431302_50_dialog_content = "Correto. Afinal, é a única conclusão lógica.",
  ui_story_5043_50431302_51_dialog_content = "E embora eu deva parabenizá-lo por seu rigoroso método de análise, Juiz Leyn...",
  ui_story_5043_50431302_52_dialog_content = "Para julgamentos futuros, sugiro que você compartilhe suas análises comigo antes do início de nossos procedimentos, em vez de desperdiçar o valioso tempo do tribunal.",
  ui_story_5043_50431302_53_dialog_content = "Acho que não desperdicei o tempo de ninguém, Meritíssimo.",
  ui_story_5043_50431302_54_dialog_content = "Todas as minhas inferências foram com o único propósito de fazer você chegar a esta mesma conclusão.",
  ui_story_5043_50431302_55_dialog_content = "Nomeadamente, Tina usou a Mão Divina para esmagar a cabeça da estátua.",
  ui_story_5043_50431302_56_dialog_content = "... Vá direto ao ponto, Juiz Leyn. O que você está tentando dizer?",
  ui_story_5043_50431302_57_dialog_content = "Agora que chegamos a essa conclusão, tudo o que precisamos fazer é olhar para trás mais uma vez para perceber a verdade.",
  ui_story_5043_50431302_58_dialog_content = "Aquela luva, aquela prova crucial, não é prova irrefutável de sua culpa, mas de sua inocência!",
  ui_story_5043_50431302_59_dialog_content = "O quê?!",
  ui_story_5043_50431302_60_dialog_content = "Meritíssimo, permita-me mostrar a todos no tribunal a luva do perpetrador!",
  ui_story_5043_50431302_61_dialog_content = "É possível que a luva tenha sido expurgada de qualquer evidência incriminatória enquanto estava em sua posse, Meritíssimo...",
  ui_story_5043_50431302_62_dialog_content = "Mas não importa, desde que seja a mesma luva da cena do crime. Podemos ter certeza disso, certo, Meritíssimo?",
  ui_story_5043_50431302_63_dialog_content = "Você está questionando minha capacidade de preservar as evidências do caso, uma das responsabilidades mais fundamentais do Tribunal de Justiça?!",
  ui_story_5043_50431302_64_dialog_content = "Fico feliz em ouvir.",
  ui_story_5043_50431302_65_dialog_content = "Peço a todos que deem uma boa e longa olhada nesta luva.",
  ui_story_5043_50431302_66_dialog_content = "É uma luva para destros, não é?",
  ui_story_5043_50431302_67_dialog_content = "Chega, juiz Leyn. Vá direto ao ponto!",
  ui_story_5043_50431302_68_dialog_content = "Que diferença faz em qual mão ele continua—",
  ui_story_5043_50431302_69_dialog_content = "!!!",
  ui_story_5043_50431302_70_dialog_content = "Hã?",
  ui_story_5043_50431302_71_dialog_content = "Ah—!",
  ui_story_5043_50431302_72_dialog_content = "A mão direita! Isso explica tudo!",
  ui_story_5043_50431302_73_dialog_content = "Espera, eu não entendo! O que está acontecendo?!",
  ui_story_5043_50431302_74_dialog_content = "Parece que você também percebeu, Meritíssimo.",
  ui_story_5043_50431302_75_dialog_content = "Há apenas uma única falha fatal em sua conclusão...",
  ui_story_5043_50431302_76_dialog_content = "A Mão Divina de Tina, que é realmente capaz de destruir a cabeça de uma estátua, requer o uso dela <color=#FFB400>mão esquerda</color>.",
  ui_story_5043_50431302_77_dialog_content = "No entanto, esta luva é uma <color=#FFB400>destro</color> luva!",
  ui_story_5043_50431302_78_dialog_content = "Oh! Agora eu entendi!!!",
  ui_story_5043_50431302_79_dialog_content = "Esquerda direita...",
  ui_story_5043_50431302_80_dialog_content = "Depois de passar todo o julgamento enfatizando a importância dessa prova crucial.",
  ui_story_5043_50431302_81_dialog_content = "Acho que todos podemos concordar com você com segurança agora, Meritíssimo.",
  ui_story_5043_50431302_82_dialog_content = "Agora que sabemos que esta não é a luva que cobre a Mão Divina de Tina, eu me pergunto que tipo de conclusão será tirada?",
  ui_story_5043_50431302_83_dialog_content = "Bem, Meritíssimo? Você gentilmente agraciaria o tribunal com seus pensamentos?",
  ui_story_5043_50431302_84_dialog_content = "Você... Você...!",
  ui_story_5043_50431302_85_dialog_content = "Muito bem, Leyn! As mesmas provas usadas para incriminar Tina também prova sua inocência!",
  ui_story_5043_50431302_86_dialog_content = "Parece que a balança está finalmente voltando a nosso favor!",
  ui_story_5043_50431302_87_dialog_content = "Isto é inacreditável...",
  ui_story_5043_50431302_88_dialog_content = "Muito bem, então. Não tenho escolha a não ser reconhecer e aceitar sua refutação.",
  ui_story_5043_50431302_89_dialog_content = "Devido à insuficiência de provas neste momento, o tribunal não pode considerar o réu culpado dos crimes acima mencionados.",
  ui_story_5043_50431302_90_dialog_content = "Portanto, o verdadeiro decapitador da estátua permanece foragido.",
  ui_story_5043_50431302_91_dialog_content = "Isso é ótimo!!!",
  ui_story_5043_50431302_92_dialog_content = "Eles fizeram isso, Carleen! Eles realmente conseguiram!",
  ui_story_5043_50431302_93_dialog_content = "De fato! Isso é maravilhoso!",
  ui_story_5043_50431302_94_dialog_content = "Testemunhar a justiça sendo preservada no Tribunal de Justiça foi uma grande honra!",
  ui_story_5043_50431302_95_dialog_content = "Então, se o perpetrador ainda estiver foragido...",
  ui_story_5043_50431302_96_dialog_content = "Isso significa que sou inocente?!",
  ui_story_5043_50431302_97_dialog_content = "Claro, Tina. Você sempre foi inocente.",
  ui_story_5043_50431302_98_dialog_content = "Você tem uma grande dívida de gratidão conosco, sabia? Especialmente para o nosso novato plebeu.",
  ui_story_5043_50431302_99_dialog_content = "Em seu primeiro caso importante, ele se saiu muito bem.",
  ui_story_5043_50431302_100_dialog_content = "Eu não poderia concordar mais! Muito obrigado aos dois por tudo que fizeram por mim!",
  ui_story_5043_50431302_101_dialog_content = "Tenho orgulho de chamá-los de meus queridos colegas!",
  ui_story_5043_50431302_102_dialog_content = "Ei! O que isso quer dizer?!",
  ui_story_5043_50431302_103_dialog_content = "Depois de perder meio dia discutindo até ficarmos roucos, você quer me dizer que você pegou a pessoa errada?!",
  ui_story_5043_50431302_104_dialog_content = "...",
  ui_story_5043_50431302_105_dialog_content = "Incrível. Simplesmente incrível!",
  ui_story_5043_50431302_106_dialog_content = "Forçando-me a sentar durante toda essa deliberação, apenas para dizer que estamos de volta onde começamos?",
  ui_story_5043_50431302_107_dialog_content = "Eu te disse muito antes! Minha paciência está no limite!",
  ui_story_5043_50431302_108_dialog_content = "Se você não encerrar este caso até o final do dia, eu encerrarei toda esta Divisão Romance dos tribunais!!!",
  ui_story_5043_50431302_109_dialog_content = "Não sejamos precipitados, meu bom senhor. Do jeito que está, discutimos apenas metade do assunto.",
  ui_story_5043_50431302_110_dialog_content = "Metade...?",
  ui_story_5043_50431302_111_dialog_content = "Sente-se aqui conosco, Juiz Tina.",
  ui_story_5043_50431302_112_dialog_content = "É hora de outra pessoa servir como réu agora.",
  ui_story_5043_50431302_113_dialog_content = "Huh? Quem é que queres dizer...?",
  ui_story_5043_50431302_114_dialog_content = "Após exaustiva investigação do caso pela Divisão Romance e todas as provas apresentadas, eu, Juiz Leyn—",
  ui_story_5043_50431302_115_dialog_content = "E eu, juiz Matthieu—",
  ui_story_5043_50431302_116_dialog_content = "Por meio deste, acuse o Sr. Schwab Salar pelos crimes de destruição de propriedade pública e subversão do amor!",
  ui_story_5043_50431302_117_dialog_content = "Juiz principal Schwab, por favor, deponha.",
  ui_story_5043_50431302_118_dialog_content = "O que? Ele está acusando Schwab?!",
  ui_story_5043_50431302_119_dialog_content = "Não me diga que isso também faz parte do plano, PlayerName?!",
  ui_story_5043_50431302_120_dialog_content = "Hum...",
  ui_story_5043_50431302_121_dialog_content = "Bem, tínhamos nossas suspeitas sobre Schwab ontem, mas...",
  ui_story_5043_50431302_122_dialog_content = "Eu não sabia que eles iriam acusá-lo de alguma coisa...",
  ui_story_5043_50431302_123_dialog_content = "Você e os outros conseguiram encontrar alguma evidência incriminadora?",
  ui_story_5043_50431302_124_dialog_content = "Não mesmo.",
  ui_story_5043_50431302_125_dialog_content = "Está me acusando, é?",
  ui_story_5043_50431302_126_dialog_content = "Você tem alguma ideia do que está fazendo, juiz Leyn?",
  ui_story_5043_50431302_127_dialog_content = "Só estou cumprindo meu dever, senhor.",
  ui_story_5043_50431302_128_dialog_content = "Hmph. É melhor esperar que sim.",
  ui_story_5043_50431302_129_dialog_content = "Porque posso dizer agora, tenho um álibi inquestionável para cada um dos três incidentes.",
  ui_story_5043_50431302_130_dialog_content = "Onde quer que essa investigação idiota possa levar, saiba que todo o Tribunal de Justiça corroborará minha história.",
  ui_story_5043_50431302_131_dialog_content = "Não tenho mais nada a dizer sobre suas acusações ilógicas por enquanto.",
  ui_story_5043_50431302_132_dialog_content = "Fique tranquilo, Juiz Schwab, minha pergunta será curta e simples.",
  ui_story_5043_50431302_133_dialog_content = "Eu também posso atestar seus álibis incontestáveis para todas as três ocorrências de irregularidades neste caso.",
  ui_story_5043_50431302_134_dialog_content = "E ainda assim você se recusa a retirar sua acusação sem sentido?",
  ui_story_5043_50431302_135_dialog_content = "Isso mesmo, senhor, porque o culpado não precisava estar presente na cena do crime.",
  ui_story_5043_50431302_136_dialog_content = "May Eu invoco uma nova testemunha?",
  ui_story_5043_50431302_137_dialog_content = "Uma testemunha?",
  ui_story_5043_50431302_138_dialog_content = "Por favor, aproxime-se do estande e prepare-se para jurar sob juramento.",
  ui_story_5043_50431302_139_dialog_content = "(Quando ele encontrou uma testemunha para isso?)",
  ui_story_5043_50431302_140_dialog_content = "(Eu me pergunto quem é...)",
  ui_story_5043_50431302_141_dialog_content = "C-Posso...",
  ui_story_5043_50431302_142_dialog_content = "Posso falar agora?",
  ui_story_5043_50431302_143_dialog_content = "Um Eclipse! E um que pode falar, nada menos!",
  ui_story_5043_50431302_144_dialog_content = "T-Totó?!?",
  ui_story_5043_50431302_145_dialog_content = "Huh? O que ele está fazendo aqui?!",
  ui_story_5043_50431302_146_dialog_content = "Ter um Eclipsite servindo como testemunha... O que ele estava pensando?",
  ui_story_5043_50431302_147_dialog_content = "Você perdeu a cabeça?! Como ousa trazer aquela criatura imunda para um tribunal sagrado do Tribunal de Justiça!",
  ui_story_5043_50431302_148_dialog_content = "Você procura minar tudo o que estabelecemos?!",
  ui_story_5043_50431302_149_dialog_content = "Não há razão para se preocupar. Confirmamos, sem dúvida, que este Eclipsite é perfeitamente inofensivo.",
  ui_story_5043_50431302_150_dialog_content = "Ninguém aqui está em perigo. Ele está aqui apenas para nos ajudar a descobrir a verdade com seu testemunho, nada mais.",
  ui_story_5043_50431302_151_dialog_content = "Acredito que estamos todos aqui pelo mesmo motivo, certo?",
  ui_story_5043_50431302_152_dialog_content = "Hmmm... Bem, se o testemunho dele favorece o julgamento, suponho que seja aceitável.",
  ui_story_5043_50431302_153_dialog_content = "Toto parece ainda mais magro do que da última vez...",
  ui_story_5043_50431302_154_dialog_content = "Isso provavelmente não tem precedentes em toda a história do Tribunal de Justiça... Eu me pergunto que tipo de testemunho ele vai dar?",
  ui_story_5043_50431302_155_dialog_content = "A-Permita-me apresentar-me.",
  ui_story_5043_50431302_156_dialog_content = "P-Por favor, não tenha medo de mim!",
  ui_story_5043_50431302_157_dialog_content = "Eu não sou nada mais do que um Eclipsite médio de baixo nível.",
  ui_story_5043_50431302_158_dialog_content = "Eu acidentalmente comi um objeto experimental em Gannon City...",
  ui_story_5043_50431302_159_dialog_content = "Não faço ideia do que foi, mas...",
  ui_story_5043_50431302_160_dialog_content = "Meu corpo começou a se transformar e, ao mesmo tempo, ganhei um certo nível de consciência!",
  ui_story_5043_50431302_161_dialog_content = "Hmph! Como é típico da Federação Illumina se envolver em pesquisas tão indescritíveis!",
  ui_story_5043_50431302_162_dialog_content = "Uau... Seu universo ficou muito mais suave desde a última vez que nos falamos?",
  ui_story_5043_50431302_163_dialog_content = "A partir desse momento, m-minha conexão com outros Eclipsites ficou mais fraca...",
  ui_story_5043_50431302_164_dialog_content = "Eu não conseguia mais controlá-los, mas eles também não conseguiam me controlar!",
  ui_story_5043_50431302_165_dialog_content = "Viver entre os outros Eclipsites foi ficando cada vez mais difícil... Não havia como eu terminar meu trabalho sem complicações constantes...",
  ui_story_5043_50431302_166_dialog_content = "O líder não tolerou e acabou me forçando a sair...",
  ui_story_5043_50431302_167_dialog_content = "Ela disse, se você quer causar problemas, vá causar problemas para os aurorianos...",
  ui_story_5043_50431302_168_dialog_content = "Emm, então existem Eclipsites que nem mesmo os Eclipsites suportam.",
  ui_story_5043_50431302_169_dialog_content = "Não sinta pena disso. O inimigo do seu inimigo pode não ser necessariamente seu amigo.",
  ui_story_5043_50431302_170_dialog_content = "Não muito tempo depois, comecei a aprender tudo o que podia sobre os aurorianos. Sua língua, suas culturas...",
  ui_story_5043_50431302_171_dialog_content = "Viajei por todo o país, procurando trabalho onde quer que pudesse. Mas não importa onde eu fosse, eu continuava sendo demitido...",
  ui_story_5043_50431302_172_dialog_content = "A vida tem sido difícil, mas estou muito mais feliz do que nunca!",
  ui_story_5043_50431302_173_dialog_content = "Eu nunca faria mal a ninguém.",
  ui_story_5043_50431302_174_dialog_content = "B-Porque eu gosto de viver como um auroriano!",
  ui_story_5043_50431302_X174_dialog_content = "Não quero mais ser odiado!",
  ui_story_5043_50431302_175_dialog_content = "Ele tem razão! Toto nunca faria mal a uma mosca!",
  ui_story_5043_50431302_176_dialog_content = "Ele é ainda mais doce do que a maioria dos aurorianos! Por favor, não se sinta ameaçado por ele!",
  ui_story_5043_50431302_177_dialog_content = "Tsk, Eclipsite que vive como um auroriano...",
  ui_story_5043_50431302_178_dialog_content = "Os tempos mudaram, parece!",
  ui_story_5043_50431302_179_dialog_content = "Obrigado, Totó. Isso servirá para uma introdução.",
  ui_story_5043_50431302_180_dialog_content = "Por favor, diga ao tribunal o motivo de sua vinda aqui e servindo como testemunha no julgamento de hoje.",
  ui_story_5043_50431302_181_dialog_content = "Eu vim denunciar um auroriano por comportamento ilegal!",
  ui_story_5043_50431302_182_dialog_content = "E quem seria?",
  ui_story_5043_50431302_183_dialog_content = "Aquele homem aí! Aquele sentado acima de todos os outros. O homem chamado Schwab!",
  ui_story_5043_50431302_184_dialog_content = "Você...",
  ui_story_5043_50431302_185_dialog_content = "Que crime ele cometeu?",
  ui_story_5043_50431302_186_dialog_content = "H-foi ele quem quebrou as estátuas!",
  ui_story_5043_50431302_187_dialog_content = "Ele tem álibis que provam que ele nunca esteve nas cenas do crime, então o que te dá tanta certeza de que ele é o culpado?",
  ui_story_5043_50431302_188_dialog_content = "Ele não precisava estar lá para destruí-los! Isso porque ele pode... ele pode...",
  ui_story_5043_50431302_189_dialog_content = "Ele pode o que?",
  ui_story_5043_50431302_190_dialog_content = "Ele pode controlar os Eclipsites!!!",
  ui_story_5043_50431401_1_dialog_content = "Controlar Eclipsites?!",
  ui_story_5043_50431401_2_dialog_content = "Meus céus! Você tem alguma ideia do que está insinuando?",
  ui_story_5043_50431401_3_dialog_content = "Consorciar-se com Eclipsitas é um crime muito grave aqui em Lumópolis!",
  ui_story_5043_50431401_4_dialog_content = "Tsk! Que testemunho ridículo!",
  ui_story_5043_50431401_5_dialog_content = "Você realmente pensou que poderia me acusar de conspirar com os Eclipsitas usando o testemunho de um deles?!",
  ui_story_5043_50431401_6_dialog_content = "Que zombaria da justiça! O testemunho de um bêbado teria mais força do que o de um imundo Eclipsita!",
  ui_story_5043_50431401_7_dialog_content = "Quando se trata de enquadrar os outros, suas habilidades ainda são extremamente deficientes, Leyn!",
  ui_story_5043_50431401_8_dialog_content = "É assim mesmo? Então talvez eu deva tirar uma ou duas páginas de seu livro, Juiz Schwab?",
  ui_story_5043_50431401_9_dialog_content = "Você...",
  ui_story_5043_50431401_10_dialog_content = "Não preciso incriminá-lo para provar sua culpa.",
  ui_story_5043_50431401_11_dialog_content = "É como você diz, o testemunho de um único Eclipsite não é suficiente para incriminá-lo por esses crimes.",
  ui_story_5043_50431401_12_dialog_content = "Mas e se aquele Eclipsite tivesse um papel especial no caso?",
  ui_story_5043_50431401_13_dialog_content = "Um papel especial...?",
  ui_story_5043_50431401_14_dialog_content = "Se você pudesse ser tão gentil, Toto?",
  ui_story_5043_50431401_15_dialog_content = "Me desculpe!!!",
  ui_story_5043_50431401_16_dialog_content = "Errei... Aceito meu castigo, aqui e agora!!!",
  ui_story_5043_50431401_17_dialog_content = "Hã?",
  ui_story_5043_50431401_18_dialog_content = "O que quer dizer, Totó? De que erro você está falando?",
  ui_story_5043_50431401_19_dialog_content = "Honestamente, em um momento está acusando o juiz supremo, e no próximo está admitindo sua própria culpa...",
  ui_story_5043_50431401_20_dialog_content = "Pare de desperdiçar nosso tempo e fale claramente, eu digo!",
  ui_story_5043_50431401_21_dialog_content = "S-Desculpe! Th-A verdade é...",
  ui_story_5043_50431401_22_dialog_content = "Fui eu quem destruiu as estátuas!",
  ui_story_5043_50431401_23_dialog_content = "O quê?!",
  ui_story_5043_50431401_24_dialog_content = "Ha? Então foi você?!",
  ui_story_5043_50431401_25_dialog_content = "Você é quem destruiu minha esposa e meu amante?!",
  ui_story_5043_50431401_26_dialog_content = "Sim, fui eu.",
  ui_story_5043_50431401_27_dialog_content = "Ora, seu podre, pequenino...!",
  ui_story_5043_50431401_28_dialog_content = "E-espere! Não fiz de propósito! Eu fui forçado a isso!",
  ui_story_5043_50431401_29_dialog_content = "Schwab foi quem me fez fazer isso todas as vezes!",
  ui_story_5043_50431401_30_dialog_content = "Por favor todos. Tenha piedade de mim—!",
  ui_story_5043_50431401_31_dialog_content = "<size=45>O que?!?</size>",
  ui_story_5043_50431401_32_dialog_content = "...",
  ui_story_5043_50431401_33_dialog_content = "Isso é realmente o que aconteceu...?",
  ui_story_5043_50431401_34_dialog_content = "I-Tudo começou há cerca de duas semanas...",
  ui_story_5043_50431401_35_dialog_content = "Eu tinha acabado de chegar em Lumopolis e estava me preparando para procurar um emprego.",
  ui_story_5043_50431401_36_dialog_content = "Mas Lumopolis é tão grande, e eu não conhecia muito bem as estradas... Antes que eu percebesse, já era noite.",
  ui_story_5043_50431401_37_dialog_content = "Depois disso, eu... encontrei um grupo de Eclipsites no Pátio de Lumopolis.",
  ui_story_5043_50431401_38_dialog_content = "Bem, tem havido vários avistamentos de atividade Eclipsite na cidade ultimamente.",
  ui_story_5043_50431401_39_dialog_content = "Isso é verdade, pelo menos.",
  ui_story_5043_50431401_40_dialog_content = "Eu não esperava encontrar mais da minha espécie na cidade. Parecia estranho.",
  ui_story_5043_50431401_41_dialog_content = "Enquanto eu estava lá tentando entender as coisas, eles presumiram que eu era apenas mais um Eclipsite perdido.",
  ui_story_5043_50431401_42_dialog_content = "Eles foram muito insistentes em me fazer entrar para suas fileiras.",
  ui_story_5043_50431401_43_dialog_content = "Apesar da minha confusão, eu os segui até que finalmente...",
  ui_story_5043_50431401_44_dialog_content = "Chegamos ao Salar Manor.",
  ui_story_5043_50431401_45_dialog_content = "Ei! Essa é a casa de Schwab!",
  ui_story_5043_50431401_46_dialog_content = "Isso mesmo, e foi lá que o vi pela primeira vez.",
  ui_story_5043_50431401_47_dialog_content = "Foi a coisa mais chocante que já vi...",
  ui_story_5043_50431401_48_dialog_content = "Ele estava dando ordens aos eclipsitas como se fossem escravos.",
  ui_story_5043_50431401_49_dialog_content = "E os Eclipsitas... Eles obedeciam a todos os seus comandos!",
  ui_story_5043_50431401_50_dialog_content = "Eu não tinha como escapar... Então tive que fingir ser um deles.",
  ui_story_5043_50431401_51_dialog_content = "Foi quando ele trancou todos nós no porão da Salar Manor!",
  ui_story_5043_50431401_52_dialog_content = "A adega?!",
  ui_story_5043_50431401_53_dialog_content = "Então ele estava mantendo aqueles eclipsitas cativos lá o tempo todo! Não admira...",
  ui_story_5043_50431401_54_dialog_content = "Você já esteve lá antes?",
  ui_story_5043_50431401_55_dialog_content = "Er, eu não acho que este é o momento ou lugar certo para te dizer...",
  ui_story_5043_50431401_56_dialog_content = "Falo com você sobre isso depois do julgamento!",
  ui_story_5043_50431401_57_dialog_content = "<size=45>Pare com essa bobagem agora mesmo!</size>",
  ui_story_5043_50431401_58_dialog_content = "Você pode acreditar no bacalhau absoluto sendo expelido da boca dessa criatura nojenta?",
  ui_story_5043_50431401_59_dialog_content = "Não tenho mais motivos para suportar essa calúnia ridícula!!!",
  ui_story_5043_50431401_60_dialog_content = "Veremos se é calúnia em breve, Juiz Schwab.",
  ui_story_5043_50431401_61_dialog_content = "Por favor, conte-nos o que aconteceu depois, Totó.",
  ui_story_5043_50431401_62_dialog_content = "Embora esta parte do seu testemunho seja chocante, de fato, tem pouco a ver com as decapitações de estátuas em série.",
  ui_story_5043_50431401_63_dialog_content = "Oh, certo! Deixe-me ligá-lo de volta ao caso!",
  ui_story_5043_50431401_64_dialog_content = "De vez em quando, Schwab tirava alguns de nós do porão para cumprir suas ordens.",
  ui_story_5043_50431401_65_dialog_content = "Eu estava desesperado por uma chance de escapar, então agi ainda mais inquieto do que meus irmãos.",
  ui_story_5043_50431401_66_dialog_content = "E eventualmente... Ele me escolheu para uma de suas tarefas.",
  ui_story_5043_50431401_67_dialog_content = "Especificamente... Ele me disse para esperar até que o Balão da Lua subisse no céu, e então d-destruir as estátuas abaixo dele!",
  ui_story_5043_50431401_68_dialog_content = "Oh! Isso combina perfeitamente com o conhecimento que temos sobre o caso!",
  ui_story_5043_50431401_69_dialog_content = "As duas primeiras vezes foram as estátuas em frente ao Hall of Justice e Meadow Square.",
  ui_story_5043_50431401_70_dialog_content = "Em frente ao Tribunal de Justiça?!",
  ui_story_5043_50431401_71_dialog_content = "Isso foi... Meu amor!",
  ui_story_5043_50431401_72_dialog_content = "Sinto muito por sua perda, Sr. Byron.",
  ui_story_5043_50431401_73_dialog_content = "Talvez seja porque as duas primeiras vezes correram tão bem... Mas Schwab pediu mais de mim pela terceira vez.",
  ui_story_5043_50431401_74_dialog_content = "H-Ele me disse... Para colocar uma luva estranha antes de quebrar a terceira estátua...",
  ui_story_5043_50431401_75_dialog_content = "Isso explica a luva!!!",
  ui_story_5043_50431401_76_dialog_content = "E assim que terminasse, deveria deixar a luva na cena do crime.",
  ui_story_5043_50431401_77_dialog_content = "Foi quando fui para a Stairway to the Skies com um grupo de Eclipsites...",
  ui_story_5043_50431401_78_dialog_content = "Mas logo depois que quebrei a cabeça da estátua, o juiz Leyn conseguiu agarrar minha mão direita... Eu mal evitei a captura naquele dia.",
  ui_story_5043_50431401_79_dialog_content = "Felizmente, consegui tirar minha mão da luva e fugir... Com isso, minha \"tarefa\" foi um sucesso.",
  ui_story_5043_50431401_80_dialog_content = "Esta é a luva que você deixou para trás?",
  ui_story_5043_50431401_81_dialog_content = "Sim! Esse é o único!",
  ui_story_5043_50431401_82_dialog_content = "Acrescenta! Tudo se soma agora!",
  ui_story_5043_50431401_83_dialog_content = "Parece que o testemunho de Toto se alinha com as evidências fornecidas neste julgamento.",
  ui_story_5043_50431401_84_dialog_content = "A seguir, vamos...",
  ui_story_5043_50431401_85_dialog_content = "Hmph! \"Alinha\", você diz?",
  ui_story_5043_50431401_86_dialog_content = "Este \"testemunho\" dele soa inteiramente ensaiado! Uma narrativa totalmente falsificada!",
  ui_story_5043_50431401_87_dialog_content = "Existe alguma evidência, alguma, que prove que mesmo uma frase do que ele falou é a verdade?!",
  ui_story_5043_50431401_88_dialog_content = "Apesar de sua vontade de se declarar culpado, ainda não acha o testemunho dele confiável o suficiente, Juiz Schwab?",
  ui_story_5043_50431401_89_dialog_content = "Claro que não! Só porque uma testemunha se declara culpada não significa que ela seja a culpada!",
  ui_story_5043_50431401_90_dialog_content = "Tenho motivos mais do que suficientes para suspeitar que alguém comprou este Eclipsite para me incriminar com ele.",
  ui_story_5043_50431401_91_dialog_content = "Afinal, usar uma forma de vida inferior para incriminar um juiz de alto escalão seria uma pechincha, não concorda?",
  ui_story_5043_50431401_92_dialog_content = "O-o que isso quer dizer?! Além disso, v-você é quem está me incriminando!!",
  ui_story_5043_50431401_93_dialog_content = "Eu vim para Lumopolis para encontrar trabalho... Eu nunca quis ser capturado e mandado por causa de suas intrigas!",
  ui_story_5043_50431401_94_dialog_content = "Se alguém não tivesse deixado a porta do porão aberta ontem, eu nunca mais teria encontrado minha liberdade!",
  ui_story_5043_50431401_95_dialog_content = "Entendo... Parece que este porão é a área de interesse.",
  ui_story_5043_50431401_96_dialog_content = "Absurdo! Está vomitando bobagens de novo!",
  ui_story_5043_50431401_97_dialog_content = "Minha casa não tem porão de nenhum tipo!",
  ui_story_5043_50431401_98_dialog_content = "Oh sim? Por que não enviamos alguém para procurá-lo e ouvir o que eles têm a dizer?!",
  ui_story_5043_50431401_99_dialog_content = "Pesquisar minha casa? Isso seria ilegal, seu monstro tolo!",
  ui_story_5043_50431401_100_dialog_content = "A privacidade da Família Salar tem direito à máxima proteção da lei!",
  ui_story_5043_50431401_101_dialog_content = "Mas como pode ser isso...?",
  ui_story_5043_50431401_102_dialog_content = "O juiz Schwab está perfeitamente correto. Não temos o direito de iniciar uma investigação sobre a residência privada da Família Salar.",
  ui_story_5043_50431401_103_dialog_content = "...",
  ui_story_5043_50431401_104_dialog_content = "A menos, é claro, que você tenha provado sua culpa.",
  ui_story_5043_50431401_105_dialog_content = "O que?!?",
  ui_story_5043_50431401_106_dialog_content = "Tsc...",
  ui_story_5043_50431401_107_dialog_content = "Tenho certeza que você também percebeu, Juiz Schwab. Afinal, as palavras saíram da sua própria boca...",
  ui_story_5043_50431401_108_dialog_content = "\"Só porque uma testemunha se declara culpada não significa que ela seja a culpada.\"",
  ui_story_5043_50431401_109_dialog_content = "...",
  ui_story_5043_50431401_110_dialog_content = "Você falou essas palavras porque sabe que tudo depende delas.",
  ui_story_5043_50431401_111_dialog_content = "No momento em que o Tribunal de Justiça o considerar culpado, tudo o que ele disse será submetido ao mais alto nível de escrutínio.",
  ui_story_5043_50431401_112_dialog_content = "Isso porque seu testemunho também foi uma admissão de culpa.",
  ui_story_5043_50431401_113_dialog_content = "E se o tribunal aceita o testemunho deste Eclipsite, também aceita o fato de que ele se rebelou contra alguém que estava mexendo os cordões nos bastidores.",
  ui_story_5043_50431401_114_dialog_content = "O Tribunal de Justiça teria então toda autoridade para investigar os elementos do testemunho de Toto em toda a extensão da lei.",
  ui_story_5043_50431401_115_dialog_content = "Se isso acontecesse, a questão de saber se Salar Manor tem ou não um porão seria respondida mais cedo ou mais tarde.",
  ui_story_5043_50431401_116_dialog_content = "Poupe-me de seus artifícios, Leyn. Eu sei muito bem o que você está planejando.",
  ui_story_5043_50431401_117_dialog_content = "Você está simplesmente usando um caso insignificante e um Eclipsite ainda mais insignificante para violar a privacidade da Família Salar.",
  ui_story_5043_50431401_118_dialog_content = "Marque minhas palavras, Leyn. Você não terá sucesso!",
  ui_story_5043_50431401_119_dialog_content = "Ei! De quem é o caso que você está chamando de \"insignificante\"?!",
  ui_story_5043_50431401_120_dialog_content = "Cala a boca, miserável!",
  ui_story_5043_50431401_121_dialog_content = "O-O que foi isso...?!",
  ui_story_5043_50431401_122_dialog_content = "Já estou farto desta farsa de julgamento!",
  ui_story_5043_50431401_123_dialog_content = "Como juiz supremo, declaro que o testemunho do Eclipsita não tem qualquer relação com o caso!",
  ui_story_5043_50431401_124_dialog_content = "Conforme declarado anteriormente, o julgamento deste caso deve ser adiado devido à falta de provas convincentes.",
  ui_story_5043_50431401_125_dialog_content = "O tribunal é adiado até o dia em que evidências conclusivas sejam trazidas à luz—",
  ui_story_5043_50431401_126_dialog_content = "E-espere! Eu tenho provas da minha culpa!",
  ui_story_5043_50431401_127_dialog_content = "!!!",
  ui_story_5043_50431401_128_dialog_content = "Está bem aqui! Bem neste tribunal!",
  ui_story_5043_50431401_129_dialog_content = "Deixe-me adivinhar, outra história sem sentido com a intenção de me envolver?",
  ui_story_5043_50431401_130_dialog_content = "Eu tenho provas! Realmente!",
  ui_story_5043_50431401_131_dialog_content = "E o que exatamente é essa prova, Toto?",
  ui_story_5043_50431401_132_dialog_content = "É a luva que foi deixada na cena do crime!",
  ui_story_5043_50431401_133_dialog_content = "A luva...?",
  ui_story_5043_50431401_134_dialog_content = "Tenho certeza que Schwab já limpou a luva para se livrar de qualquer vestígio de Eclipsites...",
  ui_story_5043_50431401_135_dialog_content = "Mas antes de quebrar a estátua, usei minhas unhas para fazer um buraco na luva!",
  ui_story_5043_50431401_136_dialog_content = "Th-Isso não é algo que ele pode simplesmente lavar!",
  ui_story_5043_50431401_137_dialog_content = "O que?!?",
  ui_story_5043_50431401_138_dialog_content = "Eu vejo. Então, se encontrarmos o buraco na luva, isso prova que era você quem a usava.",
  ui_story_5043_50431401_139_dialog_content = "O que, por sua vez, provaria que você é o culpado do crime.",
  ui_story_5043_50431401_140_dialog_content = "Isso mesmo!",
  ui_story_5043_50431401_141_dialog_content = "Juiz Schwab, podemos, por favor, inspecionar essa prova mais uma vez?",
  ui_story_5043_50431401_142_dialog_content = "...",
  ui_story_5043_50431401_143_dialog_content = "Por favor, entregue-o para o tribunal ver.",
  ui_story_5043_50431401_144_dialog_content = "Se o tribunal for suspenso em breve, prometo que não demorará muito. Esta será nossa última ordem de negócios para hoje.",
  ui_story_5043_50431401_145_dialog_content = "...",
  ui_story_5043_50431401_146_dialog_content = "Juiz Schwab?",
  ui_story_5043_50431401_147_dialog_content = "... Eca.",
  ui_story_5043_50431401_148_dialog_content = "É exatamente por isso que eu acho <color=#FFB400>o amor é nojento</color>.",
  ui_story_5043_50431401_149_dialog_content = "O quê?!",
  ui_story_5043_50431401_150_dialog_content = "Espere, isso significa que ele...?",
  ui_story_5043_50431401_151_dialog_content = "Acho nojento estar cercado por tantos plebeus adoradores.",
  ui_story_5043_50431401_152_dialog_content = "Constantemente se aproximando de mim, constantemente tentando se intrometer em minha vida privada. Tolos presunçosos!",
  ui_story_5043_50431401_153_dialog_content = "E sim, vocês me lembram muito deles.",
  ui_story_5043_50431401_154_dialog_content = "Você diz que acha o amor \"nojento\"?",
  ui_story_5043_50431401_155_dialog_content = "Claro que eu faço! O que vocês chamam de amor nada mais é do que um pesadelo inevitável!",
  ui_story_5043_50431401_156_dialog_content = "Estar cercado por meus colegas todos os dias, ter que suportar sua bajulação excessiva a cada passo.",
  ui_story_5043_50431401_157_dialog_content = "Como estudante, minha mesa estava cheia de cartas de amor e minha casa estava cheia de presentes durante as férias só para mim.",
  ui_story_5043_50431401_158_dialog_content = "Vocês têm ideia de como é doloroso ser amado por todos?!?",
  ui_story_5043_50431401_159_dialog_content = "...",
  ui_story_5043_50431401_160_dialog_content = "... Do que diabos ele está falando?",
  ui_story_5043_50431401_161_dialog_content = "Também não sei.",
  ui_story_5043_50431401_162_dialog_content = "No começo, pensei que as coisas iriam melhorar depois que eu começasse a trabalhar.",
  ui_story_5043_50431401_163_dialog_content = "Eu nunca esperaria que uma onda de amor indutor de vômito varresse toda a cidade assim!",
  ui_story_5043_50431401_164_dialog_content = "E para aumentar meu sofrimento, eles me nomearam o juiz supremo desta humilhante Divisão de Romance dentro do Tribunal de Justiça!",
  ui_story_5043_50431401_165_dialog_content = "Isso mesmo. Eu não aguentei mais, então planejei a destruição daquelas estátuas!!!",
  ui_story_5043_50431401_166_dialog_content = "Eu sabia que aqueles organizadores de eventos superficiais planejavam usá-los como peças centrais de sua celebração vil e jurei impedi-los a todo custo!",
  ui_story_5043_50431401_167_dialog_content = "Você...",
  ui_story_5043_50431401_168_dialog_content = "Você é o superficial por usar a violência para enviar sua mensagem de ódio!",
  ui_story_5043_50431401_169_dialog_content = "Então é por isso que você ordenou que os Eclipsitas destruíssem aquelas estátuas?",
  ui_story_5043_50431401_170_dialog_content = "Sim... fui eu que os enviei. Suas naturezas imundas são perfeitas para profanar a chamada \"celebração do amor\".",
  ui_story_5043_50431401_171_dialog_content = "Isso significa que posso considerar tudo o que você disse como uma admissão de culpa?",
  ui_story_5043_50431401_172_dialog_content = "Você pode dispensar as falsas formalidades agora, Leyn.",
  ui_story_5043_50431401_173_dialog_content = "Você já obteve todas as provas de que precisa. Você ganhou.",
  ui_story_5043_50431401_174_dialog_content = "O meu único erro foi ter esquecido de destruir a \"ferramenta\" que usei para o crime... Nunca pensei que voltaria a testemunhar contra mim desta forma.",
  ui_story_5043_50431401_175_dialog_content = "...",
  ui_story_5043_50431401_176_dialog_content = "Não, Schwab. A razão pela qual você perdeu não é tão complicada.",
  ui_story_5043_50431401_177_dialog_content = "A razão pela qual você perdeu é que você não nos mostrou a luva.",
  ui_story_5043_50431401_178_dialog_content = "<size=45>O que?!?</size>",
  ui_story_5043_50431401_179_dialog_content = "Espere um minuto! A luva não é a prova que precisávamos para vencer?!",
  ui_story_5043_50431401_180_dialog_content = "Será que... foi tudo um blefe?",
  ui_story_5043_50431401_181_dialog_content = "Nossa, graças a Deus acabou! Finalmente posso respirar normalmente agora.",
  ui_story_5043_50431401_182_dialog_content = "devo dizer, Leyn, você realmente é um mestre da desorientação!",
  ui_story_5043_50431401_183_dialog_content = "Vocês... Vocês me enganaram?!",
  ui_story_5043_50431401_184_dialog_content = "E-Aquele maldito Eclipsite nunca deixou nenhum tipo de buraco nele!!!",
  ui_story_5043_50431401_185_dialog_content = "Heheh... Mas espera, tem mais!",
  ui_story_5043_50431401_186_dialog_content = "Você não acha que acha isso um pouco coincidência demais?",
  ui_story_5043_50431401_187_dialog_content = "Que o único Eclipsite que conseguiu escapar de sua casa é o mesmo que você mandou destruir as estátuas?",
  ui_story_5043_50431401_188_dialog_content = "Não me diga que você...",
  ui_story_5043_50431401_189_dialog_content = "<color=#e8d9bb>Ontem...</color>",
  ui_story_5043_50431401_190_dialog_content = "Pronto para uma pequena hora extra, então?",
  ui_story_5043_50431401_191_dialog_content = "Claro. Com o caso tão obscuro como sempre, é meu trabalho coletar o máximo de informações possível antes do julgamento.",
  ui_story_5043_50431401_192_dialog_content = "Ainda assim, eu não esperava que você escolhesse me acompanhar.",
  ui_story_5043_50431401_193_dialog_content = "Tch! Diga-me, plebeu, isso foi um insulto à minha ética de trabalho ou à minha amizade com Tina agora mesmo?",
  ui_story_5043_50431401_194_dialog_content = "Não importa, suponho. Vamos deixar nossas diferenças de lado por enquanto e focar no caso...",
  ui_story_5043_50431401_195_dialog_content = "D-Desculpe incomodar, mas o Tribunal de Justiça ainda está aberto?",
  ui_story_5043_50431401_196_dialog_content = "O que é isso? Um eclipse?",
  ui_story_5043_50431401_197_dialog_content = "E na porta do Hall of Justice, nada menos! Prepare-se para morrer, demônio!",
  ui_story_5043_50431401_198_dialog_content = "E-espere, não me machuque! Estou aqui para denunciar um crime!!!",
  ui_story_5043_50431401_199_dialog_content = "Perdão? Um Eclipsite denunciando um crime?",
  ui_story_5043_50431401_200_dialog_content = "Vamos ouvir o que ele tem a dizer. Além disso, se ele causar algum problema, exterminá-lo não será um problema.",
  ui_story_5043_50431401_201_dialog_content = "Multar. Conte-nos sobre esse crime então. E faça rápido!",
  ui_story_5043_50431401_202_dialog_content = "T-tudo bem!",
  ui_story_5043_50431401_203_dialog_content = "A-Permita-me apresentar-me...",
  ui_story_5043_50431401_204_dialog_content = "<color=#e8d9bb>Dez minutos depois...</color>",
  ui_story_5043_50431401_205_dialog_content = "... E foi aí que ele nos cercou e nos trancou no porão da Salar Manor!",
  ui_story_5043_50431401_206_dialog_content = "Mas como isso poderia ser? Quer dizer, isso explica porque encontramos Eclipsites no porão...",
  ui_story_5043_50431401_207_dialog_content = "S-Sim! Foi quando eu escapei com o resto deles!",
  ui_story_5043_50431401_208_dialog_content = "O quê?!",
  ui_story_5043_50431401_209_dialog_content = "Então isso significa... Nós é que resgatamos você!",
  ui_story_5043_50431401_210_dialog_content = "A-E eu não poderia estar mais grato! Vocês são m-meus heróis!",
  ui_story_5043_50431401_211_dialog_content = "Então você quer acusar Schwab de abrigar Eclipsites contra sua vontade?",
  ui_story_5043_50431401_212_dialog_content = "S-Sim! Eu sei que a lei de L-Lumopolis nunca protegeria um E-Eclipsite, mas sei que ele deve estar tramando algo ainda pior!",
  ui_story_5043_50431401_213_dialog_content = "Uma tarefa bastante simples. Venha ao tribunal amanhã e conte a todos o que acabou de nos dizer.",
  ui_story_5043_50431401_214_dialog_content = "Em breve, todos saberão exatamente o que Schwab tem feito nas sombras!",
  ui_story_5043_50431401_215_dialog_content = "S-Claro! Eu posso fazer isso!",
  ui_story_5043_50431401_216_dialog_content = "... Você tem alguma prova?",
  ui_story_5043_50431401_217_dialog_content = "P-Proof?",
  ui_story_5043_50431401_218_dialog_content = "Lembre-se, você é um Eclipsite.",
  ui_story_5043_50431401_219_dialog_content = "Estivemos no porão da Família Salar, então podemos confiar em suas palavras, mas e os outros?",
  ui_story_5043_50431401_220_dialog_content = "Sem nenhuma evidência, tudo o que Schwab precisa fazer é negar seu testemunho e você será expulso.",
  ui_story_5043_50431401_221_dialog_content = "Além disso, ele pode até vir atrás de você assim que o julgamento terminar.",
  ui_story_5043_50431401_222_dialog_content = "Avançar com isso seria uma decisão extremamente perigosa.",
  ui_story_5043_50431401_223_dialog_content = "Lamento, mas não tenho provas...",
  ui_story_5043_50431401_224_dialog_content = "E-Precisei de tudo para escapar de seu porão...",
  ui_story_5043_50431401_225_dialog_content = "Ei! Não podemos nos render simplesmente porque não temos provas!",
  ui_story_5043_50431401_226_dialog_content = "Por que não tentamos fazer outra visita a Salar Manor?",
  ui_story_5043_50431401_227_dialog_content = "Espere, acho que não precisamos ir tão longe. Eu tenho uma ideia...",
  ui_story_5043_50431401_228_dialog_content = "Prossiga?",
  ui_story_5043_50431401_229_dialog_content = "Como não temos provas, só temos que fazer com que ele admita os crimes!",
  ui_story_5043_50431401_230_dialog_content = "... Você está brincando certo?",
  ui_story_5043_50431401_231_dialog_content = "Como poderíamos levá-lo a admiti-los sem nenhuma prova?!",
  ui_story_5043_50431401_232_dialog_content = "Diga-me, por que você acha que ele estava mantendo os Eclipsites em cativeiro em primeiro lugar?",
  ui_story_5043_50431401_233_dialog_content = "Hmm... Bem, para ele fazer algo tão perigoso, teria que ser por um motivo muito importante.",
  ui_story_5043_50431401_234_dialog_content = "Acho que ele de alguma forma ordenou que destruíssem as estátuas.",
  ui_story_5043_50431401_235_dialog_content = "Oh? O que te faz dizer isso?",
  ui_story_5043_50431401_236_dialog_content = "Lembra quando agarrei a mão do culpado na Stairway to the Skies?",
  ui_story_5043_50431401_237_dialog_content = "Depois que você e os outros destruíram o resto dos Eclipsites, não havia mais ninguém por perto.",
  ui_story_5043_50431401_238_dialog_content = "O topo da Stairway to the Skies é um espaço enorme e aberto. Não há como alguém desaparecer de nossa vista tão rapidamente.",
  ui_story_5043_50431401_239_dialog_content = "A menos, é claro, que o culpado fosse um Eclipsite.",
  ui_story_5043_50431401_240_dialog_content = "Ah, entendi agora! Se o culpado fosse um Eclipsite, teríamos nos livrado dele junto com os outros!",
  ui_story_5043_50431401_241_dialog_content = "Isso explicaria por que nunca os encontramos!",
  ui_story_5043_50431401_242_dialog_content = "Esta é a razão mais provável, sim.",
  ui_story_5043_50431401_243_dialog_content = "Então, como você planeja usar essas informações?",
  ui_story_5043_50431401_244_dialog_content = "Primeiro, vamos fazer de Toto o culpado.",
  ui_story_5043_50431401_245_dialog_content = "Em seguida, vamos fazer com que ele dê nossa versão da verdade como seu testemunho.",
  ui_story_5043_50431401_246_dialog_content = "Enquanto nosso palpite estiver próximo o suficiente da verdade, Schwab acreditará que Toto foi o Eclipsite que ele ordenou para destruir as estátuas.",
  ui_story_5043_50431401_247_dialog_content = "Está perfeito! Então seu objetivo é fazê-lo acreditar que temos provas incriminatórias contra ele. E então, uma vez que ele reconhece a derrota, ele confessa seus crimes por frustração!",
  ui_story_5043_50431401_248_dialog_content = "Isso mesmo. Temos que vencê-lo em uma batalha de inteligência.",
  ui_story_5043_50431401_249_dialog_content = "Então o que você diz, Totó? Você está disposto a mentir sob juramento?",
  ui_story_5043_50431401_250_dialog_content = "A-Contanto que exponha Schwab, eu o farei!",
  ui_story_5043_50431401_251_dialog_content = "Bom. Passaremos o resto do dia ensaiando suas falas, então.",
  ui_story_5043_50431401_252_dialog_content = "Se quisermos maximizar nossas chances de sucesso, precisaremos inventar algo convincente.",
  ui_story_5043_50431401_253_dialog_content = "Algo que fará Schwab duvidar de si mesmo o suficiente para acreditar que estamos dizendo a verdade.",
  ui_story_5043_50431401_254_dialog_content = "Vocês... Seus miseráveis charlatães!",
  ui_story_5043_50431401_255_dialog_content = "Tudo o que fizemos foi combater fogo com fogo, Juiz Schwab.",
  ui_story_5043_50431401_256_dialog_content = "E pensar que o culpado era o juiz supremo o tempo todo.",
  ui_story_5043_50431401_257_dialog_content = "Isto é inacreditável. Como algum de vocês pôde descer tão baixo? Vocês se autodenominam membros do Tribunal de Justiça?!",
  ui_story_5043_50431401_258_dialog_content = "Mesmo assim, o tribunal finalmente conseguiu trazer a verdade à tona, não foi?",
  ui_story_5043_50431401_259_dialog_content = "Às vezes, a única maneira de derrotar a escuridão é com a própria escuridão!",
  ui_story_5043_50431401_260_dialog_content = "Acabou, Juiz Schwab. Venha pacificamente e assuma a responsabilidade por suas ações.",
  ui_story_5043_50431401_261_dialog_content = "Hmph. Acabou, você diz?",
  ui_story_5043_50431401_262_dialog_content = "Parece que você também cometeu um único e crucial erro, Leyn. Gostaria de adivinhar o que é?",
  ui_story_5043_50431401_263_dialog_content = "O que você quer dizer...?",
  ui_story_5043_50431401_264_dialog_content = "Seu erro foi presumir que as coisas chegariam ao fim assim que você descobrisse a verdade.",
  ui_story_5043_50431401_265_dialog_content = "Na qualidade de juiz supremo, declaro que o Juiz Leyn, Juiz Tina, e juiz Matthieu são todos cúmplices dos crimes apresentados ao tribunal!",
  ui_story_5043_50431401_266_dialog_content = "Os três perpetradores serão imediatamente presos após o adiamento deste julgamento!",
  ui_story_5043_50431401_267_dialog_content = "Que loucura é essa, Schwab?!",
  ui_story_5043_50431401_268_dialog_content = "Todos aqui acabaram de ouvir você confessar! Você é o verdadeiro culpado, não nós!",
  ui_story_5043_50431401_269_dialog_content = "Nossa, parece que ainda não chegamos a um consenso sobre esse caso.",
  ui_story_5043_50431401_270_dialog_content = "Muito bem, então! Em vez disso, teremos o voto do júri!",
  ui_story_5043_50431401_271_dialog_content = "O júri?!",
  ui_story_5043_50431401_272_dialog_content = "Espere um minuto, aqueles são...?",
  ui_story_5043_50431401_273_dialog_content = "E-Eclipsitos?! Mas como?!",
  ui_story_5043_50431401_274_dialog_content = "Por favor, entregue sua declaração final, Juiz Leyn.",
  ui_story_5043_50431401_275_dialog_content = "... À luz de tudo o que aconteceu, concluo que Schwab Salar é o verdadeiro culpado neste caso.",
  ui_story_5043_50431401_276_dialog_content = "Bom, bom... Quem concorda com a acusação dele, levante a mão.",
  ui_story_5043_50431401_277_dialog_content = "Vamos ver... Leyn, Matthieu, Tina, e Judge Jr.",
  ui_story_5043_50431401_278_dialog_content = "Quatro votos no total. Parece que suas palavras influenciaram um grande número de corações, Leyn.",
  ui_story_5043_50431401_279_dialog_content = "Isso porque eu falo a verdade!",
  ui_story_5043_50431401_280_dialog_content = "Por outro lado, concluo que os juízes Leyn, Tina, e Matthieu são os verdadeiros culpados no caso.",
  ui_story_5043_50431401_281_dialog_content = "Aqueles que concordam com minha conclusão, por favor, batam uma vez na mesa.",
  ui_story_5043_50431401_282_dialog_content = "<color=#e8d9bb>Tum!</color>",
  ui_story_5043_50431401_283_dialog_content = "<color=#e8d9bb>Tum!</color>",
  ui_story_5043_50431401_284_dialog_content = "<color=#e8d9bb>Tum!</color>",
  ui_story_5043_50431401_285_dialog_content = "<color=#e8d9bb>Tum!</color>",
  ui_story_5043_50431401_286_dialog_content = "Mas eles são...",
  ui_story_5043_50431401_287_dialog_content = "Quatro votos.",
  ui_story_5043_50431401_288_dialog_content = "Incluindo meu próprio voto, que perfaz cinco.",
  ui_story_5043_50431401_289_dialog_content = "Parece que minha conclusão foi um pouco mais convincente do que a sua.",
  ui_story_5043_50431401_290_dialog_content = "Você... Você substituiu todos no júri por seus próprios capangas!!",
  ui_story_5043_50431401_291_dialog_content = "Seus capangas? Eles devem ser todos Eclipsites sob essas máscaras!",
  ui_story_5043_50431401_292_dialog_content = "Os votos foram lançados e uma decisão clara foi tomada!",
  ui_story_5043_50431401_293_dialog_content = "O tribunal encontra Leyn, Matthieu, e Tina—",
  ui_story_5043_50431401_294_dialog_content = "Culpado!",
  ui_story_5043_50431401_295_dialog_content = "<color=#e8d9bb>Bang—!</color>",
  ui_story_5043_50431401_296_dialog_content = "Há algo de errado com esses jurados!",
  ui_story_5043_50431401_X296_dialog_content = "Um Darkflow tão intenso! Eles realmente são Eclipsites!",
  ui_story_5043_50431401_X297_dialog_content = "O-O que você disse!?",
  ui_story_5043_50431401_X298_dialog_content = "Você deve estar brincando - todas essas pessoas sentadas aqui comigo são Eclipsitas!?",
  ui_story_5043_50431401_297_dialog_content = "Respeitados membros do júri, agradeço a vossa ajuda.",
  ui_story_5043_50431401_298_dialog_content = "Vocês serviram não apenas como testemunhas hoje, mas como meus cavaleiros na execução da justiça.",
  ui_story_5043_50431401_299_dialog_content = "Pelo poder investido no Tribunal de Justiça—",
  ui_story_5043_50431401_300_dialog_content = "Prenda esses criminosos!",
  ui_story_5043_50431401_301_dialog_content = "Graah...",
  ui_story_5043_50431401_302_dialog_content = "Droga, acho que são Eclipsites escondidos sob essas máscaras!",
  ui_story_5043_50431401_303_dialog_content = "De fato. Se este for o trunfo de Schwab, não será fácil lidar com eles.",
  ui_story_5043_50431401_304_dialog_content = "Recorrer à violência, tudo porque perdeu no tribunal? Que mesquinho!",
  ui_story_5043_50431401_305_dialog_content = "Isso não é bom, o Hall of Justice se adapta melhor ao estilo de luta deles. Estaremos cercados em pouco tempo!",
  ui_story_5043_50431401_306_dialog_content = "Tínhamos razão... Tínhamos razão, Schwab! Como você pôde deixar o mal triunfar na casa da justiça?!",
  ui_story_5043_50431401_307_dialog_content = "Deixa para lá, Leyn! A justiça sempre fica do lado do vencedor, e estamos travando uma batalha difícil aqui!",
  ui_story_5043_50431401_308_dialog_content = "Precisamos escapar enquanto podemos!",
  ui_story_5043_50431401_309_dialog_content = "Ela está certa, agora mexa-se!",
  ui_story_5043_50431401_310_dialog_content = "Por aqui, rápido!",
  ui_story_5043_50431402_1_dialog_content = "Bem acima de nossas cabeças, nosso amor flutua como uma nuvem! ♪",
  ui_story_5043_50431402_2_dialog_content = "Escondido atrás de um véu, nosso amor é tão orgulhoso! ♪",
  ui_story_5043_50431402_3_dialog_content = "De longe, nos perguntamos que beleza há dentro ♪",
  ui_story_5043_50431402_4_dialog_content = "Ver o nosso amor florescer é um desejo que não podemos esconder! ♪",
  ui_story_5043_50431402_5_dialog_content = "Ouvi dizer que eles vão estourar o balão da lua hoje. Você acha que é verdade?",
  ui_story_5043_50431402_6_dialog_content = "Claro que eles são! Essa é a razão pela qual estamos reunidos aqui hoje!",
  ui_story_5043_50431402_7_dialog_content = "Dizem que o balão está cheio de todo tipo de coisa, como flores, artesanatos de papel e até bolhas de cores diferentes!",
  ui_story_5043_50431402_8_dialog_content = "Isso soa ainda melhor do que fogos de artifício! Uma homenagem perfeita ao poder do amor!",
  ui_story_5043_50431402_9_dialog_content = "Huh? Parece que uma multidão de pessoas está saindo do Hall da Justiça.",
  ui_story_5043_50431402_10_dialog_content = "Quer saber o que eles estão fazendo?",
  ui_story_5043_50431402_11_dialog_content = "Ufa, finalmente conseguimos escapar.",
  ui_story_5043_50431402_12_dialog_content = "Ainda não podemos relaxar! Eles vão alcançá-lo a qualquer segundo agora!",
  ui_story_5043_50431402_13_dialog_content = "...",
  ui_story_5043_50431402_14_dialog_content = "Monstros persistentes, não são?",
  ui_story_5043_50431402_15_dialog_content = "Eles pretendem nos perseguir até Umbraton?!",
  ui_story_5043_50431402_16_dialog_content = "Espere, parece que um desfile está vindo para cá!",
  ui_story_5043_50431402_17_dialog_content = "Agora, de todos os tempos...",
  ui_story_5043_50431402_18_dialog_content = "Não podemos simplesmente fugir agora! Os Eclipsitas vão atacar essas pessoas se o fizermos!",
  ui_story_5043_50431402_19_dialog_content = "Isso mesmo. Teremos que derrotá-los, aqui e agora.",
  ui_story_5043_50431402_20_dialog_content = "PlayerName, você pode avisar o desfile e fazer com que evacuem a área?",
  ui_story_5043_50431402_21_dialog_content = "Claro, deixe comigo!",
  ui_story_5043_50431402_22_dialog_content = "Eles vieram para ver um show, como nunca antes haviam testemunhado.",
  ui_story_5043_50431402_23_dialog_content = "Você realmente tem coragem de roubá-los de uma experiência tão esperada?",
  ui_story_5043_50431402_24_dialog_content = "Você... Como se atreve a fazer piadas em um momento como este!",
  ui_story_5043_50431402_25_dialog_content = "Eu estava falando totalmente sério, Matthieu. Tudo que eu quero é dar às pessoas o show que elas estão morrendo de vontade de ver.",
  ui_story_5043_50431402_26_dialog_content = "Um final grandioso para esta farsa de celebração!",
  ui_story_5043_50431402_27_dialog_content = "<size=45>Por aqui, todos! Rápido, agora!</size>",
  ui_story_5043_50431402_28_dialog_content = "<size=45>O show está prestes a começar!</size>",
  ui_story_5043_50431402_29_dialog_content = "Schwab, qual é o significado disso?!",
  ui_story_5043_50431402_30_dialog_content = "Ele está tentando arruinar a celebração! Essas pessoas estão em perigo!",
  ui_story_5043_50431402_31_dialog_content = "Eles estão correndo! Não os deixe chegar perto dos Eclipsitos!",
  ui_story_5043_50431402_32_dialog_content = "Não se preocupe, eu os protegerei!",
  ui_story_5043_50431402_33_dialog_content = "Por que tão sério? Afinal, nada mais é do que um show.",
  ui_story_5043_50431402_34_dialog_content = "Agora que me lembro, o balão da lua não deveria explodir hoje?",
  ui_story_5043_50431402_35_dialog_content = "Eu me pergunto o que encontraremos escondido dentro daquele ridículo monumento flutuante ao amor quando isso acontecer.",
  ui_story_5043_50431402_36_dialog_content = "Não me diga que você...",
  ui_story_5043_50431402_37_dialog_content = "Veja os frutos de suas crenças ridículas!",
  ui_story_5043_50431402_38_dialog_content = "<color=#e8d9bb>Pop—!!!</color>",
  ui_story_5043_50431402_39_dialog_content = "Uau!!!",
  ui_story_5043_50431402_40_dialog_content = "Cuidado, galera!",
  ui_story_5043_50431402_41_dialog_content = "Ei, o que é isso flutuando sobre nós...?",
  ui_story_5043_50431402_42_dialog_content = "Os presentes de festivais antigos - meus buquês de trevo - o que são?",
  ui_story_5043_50431402_43_dialog_content = "São flores mortas?",
  ui_story_5043_50431402_44_dialog_content = "Sim, rosas mortas, para ser exato...",
  ui_story_5043_50431402_45_dialog_content = "O céu está cheio de flores mortas...",
  ui_story_5043_50431402_46_dialog_content = "Que visão feia, me sinto horrível só de vê-la.",
  ui_story_5043_50431402_47_dialog_content = "É realmente assim que o estouro do balão da lua deveria acontecer?",
  ui_story_5043_50431402_48_dialog_content = "De fato, é!",
  ui_story_5043_50431402_49_dialog_content = "Nem mais um passo, Schwab!",
  ui_story_5043_50431402_50_dialog_content = "Qual é o problema, juiz Tina? Não é esta a própria imagem do amor?",
  ui_story_5043_50431402_51_dialog_content = "Uma beleza que só podemos imaginar quando desviamos os olhos do que está dentro.",
  ui_story_5043_50431402_52_dialog_content = "Como a lua no céu noturno, ela nos cativa com sua beleza misteriosa e distante.",
  ui_story_5043_50431402_53_dialog_content = "Seu fascínio extrai força do desconhecido, da ignorância das pessoas sobre sua verdadeira natureza.",
  ui_story_5043_50431402_54_dialog_content = "E agora, todos testemunharam por si mesmos.",
  ui_story_5043_50431402_55_dialog_content = "Este é o verdadeiro significado do seu assim chamado amor.",
  ui_story_5043_50431402_56_dialog_content = "Tudo o que resta depois que a empolgação e o absurdo diminuem é um mundo em frangalhos.",
  ui_story_5043_50431402_57_dialog_content = "E a partir deste dia, ninguém mais verá a lua por sua beleza.",
  ui_story_5043_50431402_58_dialog_content = "Bem, ele está certo sobre uma coisa, nunca mais quero ver aquele balão estúpido.",
  ui_story_5043_50431402_59_dialog_content = "Sem brincadeira, de quem foi a ideia de preenchê-lo com flores mortas? Era basicamente apenas um saco flutuante de lixo...",
  ui_story_5043_50431402_60_dialog_content = "Chega de sua retórica falaciosa! Foi você quem trocou o conteúdo do balão, não foi?!",
  ui_story_5043_50431402_61_dialog_content = "Nunca toquei no conteúdo do balão. Tudo o que fiz foi remover os Luminatics que o cercavam.",
  ui_story_5043_50431402_62_dialog_content = "Você...",
  ui_story_5043_50431402_63_dialog_content = "Não me olhe assim. Foi você quem quis mentir para as massas preservando aquelas flores com Lumina.",
  ui_story_5043_50431402_64_dialog_content = "Tudo o que fiz foi descobrir a verdade.",
  ui_story_5043_50431402_65_dialog_content = "A beleza só é apreciada quando alguém assume a responsabilidade pela feiúra.",
  ui_story_5043_50431402_66_dialog_content = "Assim como aquelas donzelas de olhos arregalados que me perseguem com suas promessas de amor, elas não têm ideia do quanto sofro por causa de suas fantasias.",
  ui_story_5043_50431402_67_dialog_content = "Isso é realmente o que é o amor...?",
  ui_story_5043_50431402_68_dialog_content = "Algo tão avassalador que cria fardos para os outros...",
  ui_story_5043_50431402_69_dialog_content = "Parece que você está finalmente começando a entender minha mensagem.",
  ui_story_5043_50431402_70_dialog_content = "...",
  ui_story_5043_50431402_71_dialog_content = "(Será que... eu cometi o mesmo tipo de erro?)",
  ui_story_5043_50431402_72_dialog_content = "Não é nada disso, Tina! Não se deixe enganar pelos equívocos de Schwab!",
  ui_story_5043_50431402_73_dialog_content = "Hã?",
  ui_story_5043_50431402_74_dialog_content = "Como sua \"verdade\" poderia ter precedência sobre as experiências de outras pessoas?",
  ui_story_5043_50431402_75_dialog_content = "Assim como qualquer outra emoção, todos nós sentimos amor à nossa maneira.",
  ui_story_5043_50431402_76_dialog_content = "Posso não saber a \"verdade\" por trás do conceito de amor... Mas só de ver como todos ficam felizes em eventos como esse já me basta!",
  ui_story_5043_50431402_77_dialog_content = "E, além disso, acho que Schwab nunca sentiu um amor verdadeiramente experimentado por si mesmo!",
  ui_story_5043_50431402_78_dialog_content = "Que direito ele tem de dizer a todos como se sentir sobre isso?!",
  ui_story_5043_50431402_79_dialog_content = "Você...",
  ui_story_5043_50431402_80_dialog_content = "Claro que nunca senti amor antes! Como eu poderia me permitir sentir uma emoção tão nojenta?!",
  ui_story_5043_50431402_81_dialog_content = "Sim você está certo, PlayerName!",
  ui_story_5043_50431402_82_dialog_content = "Não há nenhuma verdade no que ele está dizendo. Ele está apenas obcecado com o pior resultado possível!",
  ui_story_5043_50431402_83_dialog_content = "Além do mais, também não há nada de errado em imaginar a beleza do amor!",
  ui_story_5043_50431402_84_dialog_content = "O amor não é algo que possa ser decidido no tribunal. Então, quem somos nós para julgá-lo?",
  ui_story_5043_50431402_85_dialog_content = "Seja uma confissão de amor ou amar alguém de longe, se unindo ou se separando, todas essas experiências são expressões válidas de amor!",
  ui_story_5043_50431402_86_dialog_content = "Schwab, você não tem ideia do que o amor realmente significa!",
  ui_story_5043_50431402_87_dialog_content = "Hmph, você pode estar certo ao dizer que não entendo o significado do amor.",
  ui_story_5043_50431402_88_dialog_content = "Também não entendo por que vocês iriam tão longe para persegui-lo.",
  ui_story_5043_50431402_89_dialog_content = "Para mim, o amor nada mais é do que um obstáculo, uma emoção parasitária que destrói minha paz e convida outras pessoas a se intrometerem em minha vida.",
  ui_story_5043_50431402_90_dialog_content = "Não, sua influência nojenta se estende muito além da minha vida! Ameaça minha carreira e capacidade de cumprir minhas obrigações, ameaça o próprio equilíbrio de toda a Lumópolis!",
  ui_story_5043_50431402_91_dialog_content = "O que te faz dizer isso?",
  ui_story_5043_50431402_92_dialog_content = "Basta olhar para as pessoas ao nosso redor. Mesmo o menor indício de emoção pode fazê-los abandonar toda a razão.",
  ui_story_5043_50431402_93_dialog_content = "Essas mesmas emoções levam ao estabelecimento dessa zombaria conhecida como Divisão Romance!",
  ui_story_5043_50431402_94_dialog_content = "O que o amor realmente fez por nós, hmm? Além de dar aos criminosos uma chance de escapar da punição, isso nos leva a acusar pessoas inocentes de crimes que nunca cometeram.",
  ui_story_5043_50431402_95_dialog_content = "Ele profana as leis centenárias que mantiveram Lumopolis unida ao longo de sua gloriosa história!",
  ui_story_5043_50431402_96_dialog_content = "Por esta razão, escolhi exercer toda a força da lei contra esta maldita onda de \"amor\" que assola nossa bela cidade...",
  ui_story_5043_50431402_97_dialog_content = "Tudo o que fiz, fiz com o único propósito de eliminar o amor como fator na execução da justiça!",
  ui_story_5043_50431402_98_dialog_content = "Eu precisava de jurados cujas opiniões estivessem alinhadas com as minhas, cujo julgamento não fosse envenenado por emoções desnecessárias.",
  ui_story_5043_50431402_99_dialog_content = "Felizmente, esses monstros hediondos eram mais do que capazes de preencher esses papéis.",
  ui_story_5043_50431402_100_dialog_content = "...",
  ui_story_5043_50431402_101_dialog_content = "Então era isso que ele estava pensando o tempo todo...",
  ui_story_5043_50431402_102_dialog_content = "Para justificar a própria paranóia dessa maneira.",
  ui_story_5043_50431402_103_dialog_content = "Esse tipo de pessoa é muito mais aterrorizante do que qualquer criminoso em busca de infâmia.",
  ui_story_5043_50431402_104_dialog_content = "Mas vamos encerrar essa conversa sem sentido sobre o amor.",
  ui_story_5043_50431402_105_dialog_content = "Em vez disso, vamos dirigir nossa atenção para o caso em questão.",
  ui_story_5043_50431402_106_dialog_content = "Afinal, você é tudo <color=#FFB400>culpado</color> aos olhos do tribunal!",
  ui_story_5043_50431402_107_dialog_content = "Ei, olha pra cá!",
  ui_story_5043_50431402_108_dialog_content = "Eclipsites estão saindo de dentro do Hall of Justice!",
  ui_story_5043_50431402_109_dialog_content = "Este dia não pode ficar mais louco! Fugir!!!",
  ui_story_5043_50431402_110_dialog_content = "Parece que Schwab está tomando a ofensiva novamente.",
  ui_story_5043_50431402_111_dialog_content = "Ele é louco se pensa que pode convocar Eclipsites na frente do público. Os guardas o prenderão em breve.",
  ui_story_5043_50431402_112_dialog_content = "Por enquanto, ainda precisamos assumir o controle da situação e garantir que nenhum civil seja ferido por suas ações.",
  ui_story_5043_50431402_113_dialog_content = "Você diz isso, mas aqueles Eclipsites mascarados não serão fáceis de lidar...",
  ui_story_5043_50431402_114_dialog_content = "Deixe-me lidar com eles.",
  ui_story_5043_50431402_115_dialog_content = "Pela minha honra e pela honra da Família Campbell...",
  ui_story_5043_50431402_116_dialog_content = "Eis o poder da Mão Divina!",
  ui_story_5043_50431402_117_dialog_content = "Uau! O que há com essa Lumina?!",
  ui_story_5043_50431402_118_dialog_content = "Um ataque como esse pode ser suficiente para...",
  ui_story_5043_50431402_119_dialog_content = "Yaaaawn—",
  ui_story_5043_50431402_120_dialog_content = "Huh? E-Ei! Por que você está bocejando em um momento como este?!",
  ui_story_5043_50431402_121_dialog_content = "Desculpe... mas eu já... passei do meu limite... por hoje...",
  ui_story_5043_50431402_122_dialog_content = "Hmph. Leve-os, Quatro Cavaleiros.",
  ui_story_5043_50431402_123_dialog_content = "E-espere, tempo limite! Isso não é justo!!",
  ui_story_5043_50431402_124_dialog_content = "Sair dessa, Tina! Ei! Ei!!!",
  ui_story_5043_50431402_125_dialog_content = "Nnng... eis o poder... da Mão Divina...!",
  ui_story_5043_50431402_126_dialog_content = "<color=#e8d9bb>Queda—</color>",
  ui_story_5043_50431402_127_dialog_content = "Sh-Ela adormeceu antes mesmo da luta começar!!!",
  ui_story_5043_50431402_128_dialog_content = "O que deveríamos fazer?! Aqui não é lugar para tirar uma soneca!!!",
  ui_story_5043_50431402_129_dialog_content = "Acordar, Tina! O inimigo está prestes a atacar!",
  ui_story_5043_50431402_130_dialog_content = "Estrelas... eu vejo estrelas... na sua cabeça... Leyn...",
  ui_story_5043_50431402_131_dialog_content = "Não é hora de olhar as estrelas! Prepare-se para a batalha!",
  ui_story_5043_50431402_132_dialog_content = "Desculpa, mas não consigo...",
  ui_story_5043_50431402_133_dialog_content = "Aqui, apenas coma isso.",
  ui_story_5043_50431402_134_dialog_content = "Isso é chocolate?! Também não é hora de lanches, Leyn!!!",
  ui_story_5043_50431402_135_dialog_content = "eu sou... eu sou...",
  ui_story_5043_50431402_136_dialog_content = "O que nós fazemos? Eles estão bem na nossa frente agora...",
  ui_story_5043_50431402_137_dialog_content = "Estou perfeitamente acordado agora!!!",
  ui_story_5043_50431402_138_dialog_content = "Hã?!",
  ui_story_5043_50431402_139_dialog_content = "Fale sobre uma soneca poderosa !!!",
  ui_story_5043_50431402_140_dialog_content = "Ei! Quando se trata de conquistar o coração de alguém, você precisa contar com mais do que apenas uma estratégia!",
  ui_story_5043_50431402_141_dialog_content = "Deixe-me mostrar-lhe como se faz!",
  ui_story_5043_50431402_142_dialog_content = "Uhh? O que é isso?",
  ui_story_5043_50431402_143_dialog_content = "Você já esqueceu? Você e os outros são os que me mostraram em primeiro lugar!",
  ui_story_5043_50431402_144_dialog_content = "Existem muitas maneiras de perseguir um interesse romântico, incluindo... <color=#FFB400>uma confissão</color>!",
  ui_story_5043_50431402_145_dialog_content = "Você estava certo o tempo todo, Leyn! Obter toda a atenção da outra pessoa é o primeiro passo e um dos mais importantes!",
  ui_story_5043_50431402_X145_dialog_content = "Afaste os monstros da multidão!",
  ui_story_5043_50431402_146_dialog_content = "Desculpa, o que...?",
  ui_story_5043_50431402_147_dialog_content = "Tudo bem, seus monstros mascarados, peguem isso!",
  ui_story_5043_50431402_148_dialog_content = "Graah...",
  ui_story_5043_50431402_149_dialog_content = "Acredito que a Mão Divina conseguiu chamar sua atenção total, sim?",
  ui_story_5043_50431402_X149_dialog_content = "Grrr!",
  ui_story_5043_50431402_X150_dialog_content = "Você não deixará nem um arranhão em meus cavaleiros com esse nível de poder! Não pare de atacar!",
  ui_story_5043_50431402_150_dialog_content = "Juiz Matthieu foi quem me mostrou o que fazer a seguir. Você ainda se lembra, certo?",
  ui_story_5043_50431402_151_dialog_content = "As pessoas não podem confiar apenas em tomar a iniciativa. Eles também precisam aprender... <color=#FFB400>a arte da ocultação</color>!",
  ui_story_5043_50431402_152_dialog_content = "E com razão! Eu vou cobrir você, Tina!",
  ui_story_5043_50431402_153_dialog_content = "Rapidamente, vamos nos proteger atrás daquela parede!",
  ui_story_5043_50431402_154_dialog_content = "Hmph. Pronto para desistir depois de um revés tão pequeno? Seu amor realmente é frágil.",
  ui_story_5043_50431402_155_dialog_content = "Você não estava dizendo há pouco que queria proteger as pessoas?",
  ui_story_5043_50431402_156_dialog_content = "Graaaaah...",
  ui_story_5043_50431402_157_dialog_content = "Grah?",
  ui_story_5043_50431402_158_dialog_content = "Eu sabia! Eles não podem nos encontrar!",
  ui_story_5043_50431402_159_dialog_content = "Acho que essas máscaras que eles estão usando podem ser seus pontos fracos!",
  ui_story_5043_50431402_160_dialog_content = "Tu podes estar certo. Vamos dar uma olhada no que está por trás de seus disfarces!",
  ui_story_5043_50431402_161_dialog_content = "É aqui que o terceiro método entra em ação!",
  ui_story_5043_50431402_162_dialog_content = "Para encontrar o equilíbrio certo entre avançar e recuar... <color=#FFB400>reconhecimento</color>!",
  ui_story_5043_50431402_163_dialog_content = "Precisamos entender a outra pessoa o máximo possível antes de dar o passo final.",
  ui_story_5043_50431402_X163_dialog_content = "Só precisamos encontrar a fraqueza deles e dar o golpe decisivo para acabar com tudo isso!",
  ui_story_5043_50431402_164_dialog_content = "Então vamos começar atacando suas máscaras!",
  ui_story_5043_50431402_165_dialog_content = "Agora é a nossa chance! Ataque!",
  ui_story_5043_50431402_166_dialog_content = "Graaah!!!",
  ui_story_5043_50431402_167_dialog_content = "<color=#e8d9bb>Vamo, vamo, vamo!!!</color>",
  ui_story_5043_50431402_168_dialog_content = "Argh, do que essas coisas são feitas?!",
  ui_story_5043_50431402_169_dialog_content = "Parece que quebrar essas máscaras não será tão fácil quanto pensávamos.",
  ui_story_5043_50431402_170_dialog_content = "Hahaha! Oh, se vocês pudessem ver os olhares estúpidos em seus rostos!",
  ui_story_5043_50431402_171_dialog_content = "Você honestamente acreditou que poderia ferir meus cavaleiros com um ataque tão patético?",
  ui_story_5043_50431402_172_dialog_content = "Hmph, mesmo quando tudo parece sem esperança, ainda há uma chance de o amor prevalecer!",
  ui_story_5043_50431402_173_dialog_content = "Neste ponto, truques e estratégias estão fora de questão. Tudo o que resta a fazer—",
  ui_story_5043_50431402_174_dialog_content = "Agora, Tina!",
  ui_story_5043_50431402_175_dialog_content = "Mostre ao mundo o que está em seu coração!!!",
  ui_story_5043_50431402_176_dialog_content = "Isso mesmo! Vou levar cada grama da minha sinceridade!",
  ui_story_5043_50431402_177_dialog_content = "E use-o para dar o golpe final!",
  ui_story_5043_50431402_178_dialog_content = "<size=45><color=#FFB400>Esplendor Divino</color>!</size>",
  ui_story_5043_50431402_179_dialog_content = "Ufa, ela conseguiu?",
  ui_story_5043_50431402_180_dialog_content = "Ela fez! Ela explodiu as máscaras daqueles Eclipsites!",
  ui_story_5043_50431402_181_dialog_content = "C-Como pode ser isso?! Meus cavaleiros...",
  ui_story_5043_50431402_182_dialog_content = "Avante, meus cavaleiros!",
  ui_story_5043_50431402_183_dialog_content = "Você não pode falhar comigo agora! Não quando a justiça ainda não foi feita!",
  ui_story_5043_50431402_184_dialog_content = "Acabou, Schwab.",
  ui_story_5043_50431402_185_dialog_content = "Assim como você, eles não sentem coisas como amor ou lealdade, tudo o que podem fazer é seguir ordens sem pensar.",
  ui_story_5043_50431402_186_dialog_content = "Como você está agora, nunca poderia esperar superar o poder bruto de nossas emoções.",
  ui_story_5043_50431402_187_dialog_content = "Mesmo agora, você insiste em falar sobre seus sentimentos?!",
  ui_story_5043_50431402_188_dialog_content = "Ela está certa, sabe? Quanto à justiça não ser feita... Você não precisa mais se preocupar com isso.",
  ui_story_5043_50431402_189_dialog_content = "Com a forma como as coisas aconteceram, o Tribunal de Justiça definitivamente levará este caso muito mais a sério.",
  ui_story_5043_50431402_190_dialog_content = "Na verdade, eu não ficaria surpreso se o Juiz Chefe Irridon preside tudo.",
  ui_story_5043_50431402_191_dialog_content = "Tenho certeza de que ela lhe fará a justiça que você tanto deseja, Schwab.",
  ui_story_5043_50431402_192_dialog_content = "Sirva-me? Não não! Isso não pode ser!",
  ui_story_5043_50431402_193_dialog_content = "Eu sou inocente, eu te digo! Ninguém pode me julgar!!!",
  ui_story_5043_50431402_194_dialog_content = "Isso não é para você decidir.",
  ui_story_5043_50431402_195_dialog_content = "Claro que é, seu tolo! Eu sou o juiz supremo!!!",
  ui_story_5043_50431402_196_dialog_content = "Esse status não é mais para você decidir.",
  ui_story_5043_50431402_197_dialog_content = "Podre! Esta cidade e suas leis estão completamente podres agora!",
  ui_story_5043_50431402_198_dialog_content = "Fora do meu caminho! Meu pai vai ouvir sobre isso!",
  ui_story_5043_50431402_199_dialog_content = "Marque minhas palavras, a Família Salar não descansará até que a verdadeira justiça seja feita!",
  ui_story_5043_50431402_200_dialog_content = "Que vergonha da sua parte, Schwab. Correr para casa para o papai quando as coisas não saem do seu jeito?",
  ui_story_5043_50431402_201_dialog_content = "Que desgraça.",
  ui_story_5043_50431402_202_dialog_content = "Eu disse sai do meu caminho!!!",
  ui_story_5043_50431402_203_dialog_content = "<color=#e8d9bb>Bata!</color>",
  ui_story_5043_50431402_204_dialog_content = "Urgh...!",
  ui_story_5043_50431402_205_dialog_content = "Quem foi? Quem me bateu agora há pouco?!",
  ui_story_5043_50431402_206_dialog_content = "Fui eu, e a menos que você venha conosco pacificamente para o Tribunal de Justiça... Haverá mais de onde isso veio.",
  ui_story_5043_50431402_207_dialog_content = "Leyn! Seu idiota!",
  ui_story_5043_50431402_208_dialog_content = "Você tem alguma ideia do que acabou de fazer, seu miserável plebeu?!",
  ui_story_5043_50431402_209_dialog_content = "Foi para o seu próprio bem.",
  ui_story_5043_50431402_210_dialog_content = "Você pode não ter chegado ao seu teste se Tina tinha batido em você em vez disso.",
  ui_story_5043_50431402_211_dialog_content = "É verdade!",
  ui_story_5043_50431402_212_dialog_content = "V-Vocês todos...",
  ui_story_5043_50431402_213_dialog_content = "Isso vai fazer, todos. Os funcionários da Divisão Romance ainda estão trabalhando!",
  ui_story_5043_50431402_214_dialog_content = "Vem vem! É hora de voltar às nossas funções!",
  ui_story_5043_50431402_215_dialog_content = "Acho que ainda temos muito trabalho para hoje, né?",
  ui_story_5043_50431402_216_dialog_content = "Yaaaawn... Oh, graças a Deus, um sofá...",
  ui_story_5043_50431402_217_dialog_content = "Ei! Tire suas mãos imundas de mim!",
  ui_story_5043_50431402_218_dialog_content = "Não serei empurrado como um criminoso comum!",
  ui_story_5043_50431402_219_dialog_content = "Uau! Eles finalmente estão levando Schwab sob custódia!",
  ui_story_5043_50431402_220_dialog_content = "Parece que no final deu tudo certo, né?",
  ui_story_5043_50431402_221_dialog_content = "De fato. Schwab tem muito a responder. Sua punição não será leve.",
  ui_story_5043_50431402_222_dialog_content = "Embora suas ações não tenham resultado em nenhum dano real, elas ainda violavam diretamente as leis de Lumopolis.",
  ui_story_5043_50431402_223_dialog_content = "Se ele decidir manipular os Eclipsites assim novamente... Não me atrevo a imaginar as consequências.",
  ui_story_5043_50431402_224_dialog_content = "Eu não acho que ele vai. Afinal, seu verdadeiro inimigo sempre foi o amor! Hahahaha!",
  ui_story_5043_50431402_225_dialog_content = "Isso é verdade. Seu ódio pelo conceito de amor o levou a tais extremos, não a ninguém ou a qualquer outra coisa, em particular.",
  ui_story_5043_50431402_226_dialog_content = "No mínimo, ele foi capaz de entregar sua mensagem equivocada, graças a essa farsa de julgamento e a essa façanha com o balão da lua.",
  ui_story_5043_50431402_227_dialog_content = "Sim, eu diria que este caso está praticamente encerrado!",
  ui_story_5043_50431402_228_dialog_content = "Eu nunca teria imaginado que um incidente tão pequeno terminaria de uma forma tão louca...",
  ui_story_5043_50431402_229_dialog_content = "Nem eu, mas finalmente acabou.",
  ui_story_5043_50431402_230_dialog_content = "Tudo o que resta é ouvir um veredicto final.",
  ui_story_5043_50431402_231_dialog_content = "Sim! Vamos encontrar alguns bons lugares!",
  ui_story_5043_50431402_232_dialog_content = "Mal posso esperar para ouvir o que o juiz tem a dizer sobre isso.",
  ui_story_5043_50431402_233_dialog_content = "Huh? Há algo errado, irmã?",
  ui_story_5043_50431402_234_dialog_content = "Acabou...",
  ui_story_5043_50431402_235_dialog_content = "P-por que você está chorando?",
  ui_story_5043_50431402_236_dialog_content = "As pessoas se foram e o balão também.",
  ui_story_5043_50431402_237_dialog_content = "Minhas flores e trevos, está tudo acabado...",
  ui_story_5043_50431402_238_dialog_content = "Sinto muito, irmã... Mas não foi sua culpa, foi de Schwab!",
  ui_story_5043_50431402_239_dialog_content = "Mesmo assim, está tudo acabado agora.",
  ui_story_5043_50431402_240_dialog_content = "A onda de amor de Lumopolis finalmente diminuiu...",
  ui_story_5043_50431501_1_dialog_content = "Após uma investigação minuciosa, a verdade por trás dos crimes era exatamente como Leyn havia presumido.",
  ui_story_5043_50431501_2_dialog_content = "Schwab foi declarado o culpado por trás das decapitações de estátuas em série e também foi considerado culpado de manipular Eclipsites para cumprir suas ordens.",
  ui_story_5043_50431501_3_dialog_content = "Felizmente, nenhum auroriano foi ferido devido a suas ações distorcidas, e os únicos danos sofridos foram nessas três estátuas.",
  ui_story_5043_50431501_4_dialog_content = "Eu acho que ele ainda tinha algum senso de justiça em seu coração afinal, haha...",
  ui_story_5043_50431501_5_dialog_content = "Eu preciso entregá-lo a esses três juízes, no entanto. Eles conseguiram deduzir a verdade por trás dos crimes com quase nenhuma evidência para ajudá-los!",
  ui_story_5043_50431501_6_dialog_content = "De fato. Após este caso, tenho certeza que o Tribunal de Justiça vai olhar para seus talentos com mais interesse.",
  ui_story_5043_50431501_7_dialog_content = "Ainda há uma coisa que eu não entendo.",
  ui_story_5043_50431501_8_dialog_content = "Como exatamente Schwab conseguiu controlar esses Eclipsites, para começar?",
  ui_story_5043_50431501_9_dialog_content = "Não o vi usar nenhum tipo de equipamento especial durante nossa batalha...",
  ui_story_5043_50431501_10_dialog_content = "Ah, a investigação também tem uma teoria sobre isso.",
  ui_story_5043_50431501_11_dialog_content = "Depois de adquirir os mandados necessários, o Hall of Justice revistou a Salar Manor e encontrou o porão onde Schwab escondia seus Eclipsites.",
  ui_story_5043_50431501_12_dialog_content = "Fora de seu porão, no entanto, os investigadores não encontraram nada que pudesse ser usado para controlá-los.",
  ui_story_5043_50431501_13_dialog_content = "Após um longo interrogatório, bem como uma busca completa no porão, o Tribunal de Justiça chegou a uma conclusão inesperada.",
  ui_story_5043_50431501_14_dialog_content = "Schwab conseguiu domar os Eclipsites com métodos diferentes daqueles usados para treinamento de animais.",
  ui_story_5043_50431501_15_dialog_content = "Ele os domesticou?!?",
  ui_story_5043_50431501_16_dialog_content = "Os Eclipsites podem realmente ser treinados assim?!",
  ui_story_5043_50431501_17_dialog_content = "Se você pensar sobre isso, a noção não está completamente fora do reino das possibilidades.",
  ui_story_5043_50431501_18_dialog_content = "Nós, aurorianos, vimos os eclipsitas como nossos inimigos mortais por gerações. Naturalmente, temos um preconceito intenso contra eles.",
  ui_story_5043_50431501_19_dialog_content = "Mas uma vez que você deixa de lado a história entre nossas espécies, você pode ver que os Eclipsitas são apenas criaturas de inteligência inferior.",
  ui_story_5043_50431501_20_dialog_content = "Eles têm suas próprias necessidades e comportamentos e não são diferentes de qualquer outro animal.",
  ui_story_5043_50431501_21_dialog_content = "Ao levar em consideração os hábitos e características de uma criatura, ela pode ser treinada para entender que seguir ordens leva a resultados positivos. Essa é a lógica por trás da domesticação de feras, não é?",
  ui_story_5043_50431501_22_dialog_content = "Tudo o que Schwab fez foi domesticá-los até certo ponto, assim como nossos ancestrais fizeram com lobos e outros animais.",
  ui_story_5043_50431501_23_dialog_content = "Entendo...",
  ui_story_5043_50431501_24_dialog_content = "Faz sentido, mas ainda acho que é meio inacreditável.",
  ui_story_5043_50431501_25_dialog_content = "Muitos dos detalhes do caso dão credibilidade à conclusão.",
  ui_story_5043_50431501_26_dialog_content = "Schwab sempre desprezou sua própria espécie, mas, curiosamente, ele mostra uma forte afinidade por pequenos animais.",
  ui_story_5043_50431501_27_dialog_content = "Para ele ir tão longe em seus esquemas, também teria sido necessária uma quantidade igualmente incrível de paciência.",
  ui_story_5043_50431501_28_dialog_content = "Quando você coloca dessa forma, ele não parece tão ruim assim, pelo menos não do ponto de vista de um auroriano.",
  ui_story_5043_50431501_29_dialog_content = "Oh, espere um minuto, eu não sou um auroriano...",
  ui_story_5043_50431501_30_dialog_content = "Tudo bem, acho que podemos deixar o resto desta discussão para mais tarde.",
  ui_story_5043_50431501_31_dialog_content = "O julgamento de Schwab está prestes a começar.",
  ui_story_5043_50431501_32_dialog_content = "O réu, Schwab Salar, é acusado de manipular os Eclipsites para realizar a destruição de três estátuas.",
  ui_story_5043_50431501_33_dialog_content = "O Tribunal de Justiça investigou exaustivamente o assunto, e as provas obtidas corroboram a acusação acima mencionada.",
  ui_story_5043_50431501_34_dialog_content = "Tem algo a dizer em sua defesa, Schwab Salar?",
  ui_story_5043_50431501_35_dialog_content = "...",
  ui_story_5043_50431501_36_dialog_content = "(Ele costumava agir tão alto e poderoso antes, mas agora ele parece completamente envergonhado de si mesmo.)",
  ui_story_5043_50431501_37_dialog_content = "A investigação também concluiu que, apesar do comportamento ilegal do réu, nenhum dano grave foi causado à cidade de Lumopolis ou à sua população.",
  ui_story_5043_50431501_38_dialog_content = "Além disso, considerando a idade relativamente jovem do réu, o tribunal acredita que ele ainda pode corrigir seus modos. Como tal, o tribunal não imporá uma pena de prisão ao arguido.",
  ui_story_5043_50431501_39_dialog_content = "Oh? Afinal, não irei para a prisão.",
  ui_story_5043_50431501_40_dialog_content = "Faz sentido. Por mais problemático que seja, as ações de Schwab nada mais foram do que vandalismo equivocado.",
  ui_story_5043_50431501_41_dialog_content = "Dada a pequena extensão dos danos, não há razão para mandá-lo para a prisão por seus crimes.",
  ui_story_5043_50431501_42_dialog_content = "No entanto, a isenção da pena de prisão não significa a isenção total de todas as repercussões legais.",
  ui_story_5043_50431501_43_dialog_content = "O réu, bem como a Família Salar, devem arcar com todos e quaisquer ônus financeiros incorridos neste processo.",
  ui_story_5043_50431501_44_dialog_content = "Seu salário como juiz do Tribunal de Justiça também será deduzido integralmente.",
  ui_story_5043_50431501_45_dialog_content = "Claro. Aceito meus castigos sem questionar.",
  ui_story_5043_50431501_46_dialog_content = "Por que ele parece tão calmo agora?",
  ui_story_5043_50431501_47_dialog_content = "Dinheiro é a coisa menos importante do mundo para um homem como ele.",
  ui_story_5043_50431501_48_dialog_content = "Se for esse o caso, você não acha que a punição dele é branda demais?",
  ui_story_5043_50431501_49_dialog_content = "Naturalmente, isso é apenas metade da sua sentença.",
  ui_story_5043_50431501_50_dialog_content = "Depois de analisar os eventos que levaram a este incidente, o Tribunal de Justiça concluiu que o comportamento extremo de Schwab Salar resultou de uma falha no sistema educacional da aristocracia.",
  ui_story_5043_50431501_51_dialog_content = "Portanto, a fim de corrigir essa falha, o tribunal condena Schwab Salar à reeducação em seu local de estudo anterior.",
  ui_story_5043_50431501_52_dialog_content = "O que...? Você quer dizer que eu tenho que voltar para o Dawn Academia e repetir minhas aulas?!",
  ui_story_5043_50431501_53_dialog_content = "Conluio com Eclipsites é um crime sério e deve ser tratado com severidade.",
  ui_story_5043_50431501_X53_dialog_content = "O tribunal decidiu que o ofensor, Schwab, precisa da orientação renovada do Deus da Luz.",
  ui_story_5043_50431501_54_dialog_content = "Para receber esta orientação, você foi designado para o <color=#FFB400>templo em que as freiras são treinadas</color>.",
  ui_story_5043_50431501_55_dialog_content = "N-Freiras?!?",
  ui_story_5043_50431501_56_dialog_content = "Isso... Isso vai longe demais, Meritíssimo!!!",
  ui_story_5043_50431501_57_dialog_content = "Permita-me apresentar seu novo instrutor. May sua reeducação prossiga sem problemas, Schwab Salar.",
  ui_story_5043_50431501_58_dialog_content = "Nos encontramos novamente, Sr. Schwab.",
  ui_story_5043_50431501_59_dialog_content = "É você! Isso só pode significar que a ideia foi sua, não foi?!",
  ui_story_5043_50431501_60_dialog_content = "Temos um currículo emocionante planejado apenas para você. Além de seus estudos teológicos diários, haverá aulas de costura, culinária e atendimento aos menos afortunados...",
  ui_story_5043_50431501_61_dialog_content = "Sinto-me honrado em ter o privilégio de orientar seus estudos nos próximos anos.",
  ui_story_5043_50431501_62_dialog_content = "Não, nãooooo!!! Eu me recuso a ser educada em um lugar comandado inteiramente por mulheres!!!",
  ui_story_5043_50431501_63_dialog_content = "Parece que seus valores sociais também precisam ser reeducados.",
  ui_story_5043_50431501_64_dialog_content = "Leve-o para o convento e prepare-o para sua nova vida de estudo e reflexão.",
  ui_story_5043_50431501_65_dialog_content = "Além de Schwab, há outras partes neste caso que precisam ser repreendidas.",
  ui_story_5043_50431501_66_dialog_content = "Juiz Leyn.",
  ui_story_5043_50431501_67_dialog_content = "Sim, Meritíssimo!",
  ui_story_5043_50431501_68_dialog_content = "Você é acusado de invadir Salar Manor. Você admite esse crime?",
  ui_story_5043_50431501_69_dialog_content = "Gosto sim.",
  ui_story_5043_50431501_70_dialog_content = "(Achei que ele não mentiria para o juiz supremo...)",
  ui_story_5043_50431501_71_dialog_content = "Muito bem. Por autoridade do Tribunal de Justiça, e de acordo com o artigo 127 do Código de Conduta do Juiz...",
  ui_story_5043_50431501_72_dialog_content = "Sua nota mensal de desempenho será zerada, e seu salário deste mês será reduzido ao mínimo salarial permitido como servidor público de Lumópolis.",
  ui_story_5043_50431501_73_dialog_content = "Eu entendo...",
  ui_story_5043_50431501_74_dialog_content = "(Ele diz isso, mas acho que foi o castigo mais doloroso que ele poderia receber!)",
  ui_story_5043_50431501_75_dialog_content = "Bem, agora, realmente... eu também sou culpado deste crime, Meritíssimo!",
  ui_story_5043_50431501_76_dialog_content = "Eu estava com ele na época, então acho que esse castigo deveria ser dividido entre nós dois.",
  ui_story_5043_50431501_77_dialog_content = "É isso mesmo, juiz Matthieu?",
  ui_story_5043_50431501_78_dialog_content = "Eu também estava lá! Não se esqueça de mim!",
  ui_story_5043_50431501_79_dialog_content = "Devo dizer que sua vontade de reconhecer seus erros é bastante revigorante. Muito bem, então! Além do salário do Juiz Matthieu ser descontado durante o mês...",
  ui_story_5043_50431501_80_dialog_content = "Eu sentencio vocês três a varrer o terreno do lado de fora do Tribunal de Justiça mais tarde.",
  ui_story_5043_50431501_81_dialog_content = "A visão de todas aquelas flores mortas é muito desagradável.",
  ui_story_5043_50431501_82_dialog_content = "Q-Que tipo de punição é essa??",
  ui_story_5043_50431501_83_dialog_content = "Você gostaria que eu reconsiderasse?",
  ui_story_5043_50431501_84_dialog_content = "N-Não, obrigado, Meritíssimo! Estamos mais do que dispostos a concordar!",
  ui_story_5043_50431501_85_dialog_content = "Bom. Isso deixa apenas um veredicto final para passar.",
  ui_story_5043_50431501_86_dialog_content = "A testemunha, Toto, pode se aproximar do estande?",
  ui_story_5043_50431501_87_dialog_content = "Estou aqui, Meritíssimo!",
  ui_story_5043_50431501_88_dialog_content = "Ah, Totó!",
  ui_story_5043_50431501_89_dialog_content = "(Uau! Quando Toto colocou as mãos nessa roupa?)",
  ui_story_5043_50431501_90_dialog_content = "(Parece tão refinado. Ele combina perfeitamente com o resto de Lumopolis!)",
  ui_story_5043_50431501_91_dialog_content = "Como vítima neste caso, você estava disposto a ajudar os aurorianos a buscar justiça. Por isso, devo elogiá-lo.",
  ui_story_5043_50431501_92_dialog_content = "No entanto, o crime de perjúrio não é tolerado levianamente aqui no Tribunal de Justiça.",
  ui_story_5043_50431501_93_dialog_content = "Como cúmplice da estratégia do juiz Leyn, você é igualmente culpado por este crime.",
  ui_story_5043_50431501_94_dialog_content = "Eu... eu entendo...",
  ui_story_5043_50431501_95_dialog_content = "Como juiz supremo, sua punição será:",
  ui_story_5043_50431501_96_dialog_content = "... desculpe-se com Schwab.",
  ui_story_5043_50431501_97_dialog_content = "Uh o quê?",
  ui_story_5043_50431501_98_dialog_content = "V-você quer que nos desculpemos? Isso é tudo?",
  ui_story_5043_50431501_99_dialog_content = "Seu ato de perjúrio também foi uma afronta à honra dele como juiz do Tribunal de Justiça, então lembre-se de mostrar pelo menos um pouco de sinceridade ao se desculpar.",
  ui_story_5043_50431501_100_dialog_content = "E com isso, todas as punições relacionadas a este caso foram dispensadas.",
  ui_story_5043_50431501_101_dialog_content = "O caso das Decapitações da Estátua Serial está encerrado! O tribunal está suspenso!",
  ui_story_5043_50431501_102_dialog_content = "<color=#e8d9bb>Tum!</color>",
  ui_story_5043_50431501_103_dialog_content = "<color=#e8d9bb>Alguns dias depois...</color>",
  ui_story_5043_50431501_104_dialog_content = "Ahem, aqui estão os detalhes das minhas viagens em Longzhou de alguns meses atrás.",
  ui_story_5043_50431501_105_dialog_content = "Muito bom. Obrigado, PlayerName.",
  ui_story_5043_50431501_106_dialog_content = "Enquanto o equilíbrio de poder muda no mundo ao nosso redor, a postura de Lumopolis nunca mudará.",
  ui_story_5043_50431501_107_dialog_content = "Rezo para que Eraveil continue a manter relações amistosas com nossa bela cidade.",
  ui_story_5043_50431501_108_dialog_content = "Rezo para que você sinta o mesmo, meu jovem amigo.",
  ui_story_5043_50431501_109_dialog_content = "O-Claro, Senhor Schwartz! Estou sempre feliz em ajudar quando se trata de fazer as pazes com os outros!",
  ui_story_5043_50431501_110_dialog_content = "Fico feliz em ouvir isso.",
  ui_story_5043_50431501_111_dialog_content = "(Ufa... Ainda bem que finalmente acabou!)",
  ui_story_5043_50431501_112_dialog_content = "Você sabe, você pode ser bastante diplomata quando se dedica a isso, PlayerName.",
  ui_story_5043_50431501_113_dialog_content = "Heheheh, você acha? Para ser sincero, ainda me sinto um pouco nervoso.",
  ui_story_5043_50431501_114_dialog_content = "Isso conclui nossa reunião de hoje. Há mais perguntas?",
  ui_story_5043_50431501_115_dialog_content = "O Tribunal de Justiça nada mais tem a relatar.",
  ui_story_5043_50431501_116_dialog_content = "Duque Otto?",
  ui_story_5043_50431501_117_dialog_content = "Hmph, minhas pernas estão começando a ficar cansadas de tanto sentar.",
  ui_story_5043_50431501_118_dialog_content = "Muito bem, então. Obrigado a todos novamente. Você está livre para sair agora.",
  ui_story_5043_50431501_119_dialog_content = "(Ainda não, há uma última coisa que preciso trazer enquanto os representantes do Hall of Justice e do Elder Council ainda estão aqui.)",
  ui_story_5043_50431501_120_dialog_content = "(Além de Eclipsites e multidões incontroláveis de pessoas, outro partido em Lumopolis tem semeado discórdia recentemente.)",
  ui_story_5043_50431501_121_dialog_content = "(Como Capitão dos Guardas dos Jardins de Lumopolis, tenho o dever de informar o Conselho Ancião!)",
  ui_story_5043_50431501_122_dialog_content = "Padre, Duque Otto... Um minuto do seu tempo, por favor.",
  ui_story_5043_50431501_123_dialog_content = "Devo dizer, Senhor Schwartz, os Jardins Lumopolis têm lidado com todas as emergências recentes de forma bastante eficaz.",
  ui_story_5043_50431501_124_dialog_content = "Fiquei bastante surpreso ao ver como eles trabalham bem com o povo de Lumopolis.",
  ui_story_5043_50431501_125_dialog_content = "Haha, seu elogio é muito gracioso, Duque Otto. Naturalmente, devemos muito do nosso sucesso ao apoio do Elder Council.",
  ui_story_5043_50431501_126_dialog_content = "Sem a sua ajuda na luta contra os Eclipsites, os Guardas dos Jardins de Lumopolis não seriam capazes de atender às necessidades de nossa cidade.",
  ui_story_5043_50431501_127_dialog_content = "O que é isso, Carleen?",
  ui_story_5043_50431501_128_dialog_content = "...",
  ui_story_5043_50431501_129_dialog_content = "Ah, não diga mais nada, milady. Não quero me intrometer em uma conversa entre pai e filha. Bom dia.",
  ui_story_5043_50431501_130_dialog_content = "Meu senhor, presumo que esteja ciente do que os guardas do Conselho Ancião fizeram durante o Dia da Coroa da Lua, certo?",
  ui_story_5043_50431501_131_dialog_content = "Muito mais consciente do que você pensa, Carleen.",
  ui_story_5043_50431501_132_dialog_content = "No ano passado, você se mostrou mais calmo e corajoso do que nunca.",
  ui_story_5043_50431501_133_dialog_content = "No entanto, abordar questões políticas como essas exige mais do que apenas coragem.",
  ui_story_5043_50431501_134_dialog_content = "Quando meu trabalho atual estiver completo, providenciarei um período de férias para todos nos Jardins de Lumopolis.",
  ui_story_5043_50431501_135_dialog_content = "Isso não será necessário, mas obrigado, padre.",
  ui_story_5043_50431501_136_dialog_content = "Vamos, PlayerName.",
  ui_story_5043_50431501_137_dialog_content = "<color=#e8d9bb>Pop! Pop! Pop!</color>",
  ui_story_5043_50431501_138_dialog_content = "Parabéns pelo relatório de trabalho bem sucedido, PlayerName!!!",
  ui_story_5043_50431501_139_dialog_content = "Sabíamos disso no momento em que vimos o Juiz Chefe Irridon saia da sala de conferências!",
  ui_story_5043_50431501_140_dialog_content = "Esses fogos de artifício sobraram de quando foram dados a Byron para suas estátuas.",
  ui_story_5043_50431501_141_dialog_content = "Não pode deixá-los ir para o lixo, certo?",
  ui_story_5043_50431501_142_dialog_content = "Qual é o problema? Muito surpreso para falar?",
  ui_story_5043_50431501_143_dialog_content = "Anime-se, não é? Isso vale para você também, senhora Carleen!",
  ui_story_5043_50431501_144_dialog_content = "Parabéns pelo trabalho bem feito, PlayerName.",
  ui_story_5043_50431501_145_dialog_content = "Uau... Obrigado a todos!",
  ui_story_5043_50431501_146_dialog_content = "Você é tudo tão...",
  ui_story_5043_50431501_147_dialog_content = "Suspiro, o que devemos fazer com você?",
  ui_story_5043_50431501_148_dialog_content = "Perdoem-me por estragar a diversão, pessoal. Mas o trabalho do Tribunal de Justiça ainda não está concluído.",
  ui_story_5043_50431501_149_dialog_content = "Sua ajuda também seria muito apreciada, Lady Carleen.",
  ui_story_5043_50431501_150_dialog_content = "Este assunto requer a colaboração de alguém dos Jardins Lumopolis.",
  ui_story_5043_50431501_151_dialog_content = "<color=#e8d9bb>O Hall of Justice, Lumopolis Gardens</color>",
  ui_story_5043_50431501_152_dialog_content = "Entendi.",
  ui_story_5043_50431501_153_dialog_content = "Portanto, apesar da dissolução da Divisão Romance, vários casos ainda precisam ser resolvidos.",
  ui_story_5043_50431501_154_dialog_content = "O Tribunal de Justiça continua tão diligente como sempre, Juiz Chefe.",
  ui_story_5043_50431501_155_dialog_content = "Uau, basta olhar para todos esses arquivos! Estaremos aqui por semanas apenas tentando ler todos eles...",
  ui_story_5043_50431501_156_dialog_content = "Bem, então, estou contando com—",
  ui_story_5043_50431501_157_dialog_content = "Nós sabemos...",
  ui_story_5043_50431501_158_dialog_content = "Uma última coisa, senhora Carleen. Embora esses casos possam parecer simples disputas entre amantes à primeira vista...",
  ui_story_5043_50431501_159_dialog_content = "Uma investigação mais profunda de seu conteúdo revela rapidamente uma miríade de problemas que afetam Lumopolis em um nível fundamental e social.",
  ui_story_5043_50431501_160_dialog_content = "Ao lê-los, ganhei uma compreensão tremenda dos pensamentos e motivos daqueles que vivem no Pátio de Lumopolis e na Baixa Lumopolis. Foi uma experiência inédita para mim.",
  ui_story_5043_50431501_161_dialog_content = "Suas várias interpretações de amor e fé... Me deram muito em que pensar.",
  ui_story_5043_50431501_162_dialog_content = "Acredito que entender esses casos é fundamental para rever nossas leis em benefício de Lumópolis como um todo.",
  ui_story_5043_50431501_163_dialog_content = "Quando chegar a hora, rezo para que o Tribunal de Justiça tenha o apoio do Lorde da Cidade, assim como o seu.",
  ui_story_5043_50431501_164_dialog_content = "Para resumir, acredito que este trabalho é essencial para garantir um futuro brilhante e próspero para Lumopolis.",
  ui_story_5043_50431501_165_dialog_content = "Muito bem, concordo com o seu pedido.",
  ui_story_5043_50431501_166_dialog_content = "Afinal, Irridon... Você não é o único que se sente assim.",
  ui_story_5043_50431501_167_dialog_content = "Você deve se sentir muito mais feliz agora, certo Carleen?",
  ui_story_5043_50431501_168_dialog_content = "Oh? É tão óbvio para você?",
  ui_story_5043_50431501_169_dialog_content = "Honestamente, estou meio chocado com a rapidez com que as ruas voltaram ao normal.",
  ui_story_5043_50431501_170_dialog_content = "Assim, as barracas e desfiles se foram, e a lua não está mais flutuando no céu.",
  ui_story_5043_50431501_171_dialog_content = "É realmente tão surpreendente para você, Leyn? Afinal, somos nobres.",
  ui_story_5043_50431501_172_dialog_content = "Os tempos e as tendências estão sempre mudando em Lumopolis. Como poderíamos nos deixar ficar para trás nas novidades?",
  ui_story_5043_50431501_173_dialog_content = "Veja por si mesmos!",
  ui_story_5043_50431501_174_dialog_content = "Huh? Essas luvas não são iguais às minhas?",
  ui_story_5043_50431501_175_dialog_content = "Sim, mas recentemente se tornaram o item de moda mais quente do mercado. Membros da nobreza já foram vistos usando-os em várias ocasiões sociais.",
  ui_story_5043_50431501_176_dialog_content = "Eles são um pouco grossos demais para o meu gosto, mas isso não me impediu de comprar sete pares deles!",
  ui_story_5043_50431501_177_dialog_content = "Que ridiculamente frívolo.",
  ui_story_5043_50431501_178_dialog_content = "Exatamente o que você esperaria de um garoto rico...",
  ui_story_5043_50431501_179_dialog_content = "Hmph! Ignore esses filisteus, Tina. Diga-me, como é ser o criador de tendências da última mania da moda de Lumopolis?",
  ui_story_5043_50431501_180_dialog_content = "Ah, e como vão as coisas com o Totó? Você já encontrou uma maneira de mantê-lo?",
  ui_story_5043_50431501_181_dialog_content = "Algo assim seria um tabu aqui em Lumopolis... Mas é isso que torna tudo mais emocionante, não?",
  ui_story_5043_50431501_182_dialog_content = "A-Na verdade, todo mundo... Eu pedi a Toto para me encontrar aqui hoje.",
  ui_story_5043_50431501_183_dialog_content = "Dessa forma, eu poderia dizer <color=#FFB400>adeus</color> para ele.",
  ui_story_5043_50431501_184_dialog_content = "O quê?!",
  ui_story_5043_50431501_185_dialog_content = "Mas por que tão cedo? Eu não tinha ideia de que sua bondade para com ele poderia durar tão pouco!",
  ui_story_5043_50431501_186_dialog_content = "Th-não é isso! Na verdade, é precisamente porque me importo tanto com o doce carinha!",
  ui_story_5043_50431501_187_dialog_content = "Os eclipsites são temidos e odiados desde que todos se lembram, mas Toto não é como os outros!",
  ui_story_5043_50431501_188_dialog_content = "Mesmo assim, nem todos estariam dispostos a ver as coisas dessa forma, muito menos aceitá-las.",
  ui_story_5043_50431501_189_dialog_content = "Se eu insistisse em ficar aqui em Lumopolis com ele, isso tornaria a vida muito mais difícil para ele.",
  ui_story_5043_50431501_190_dialog_content = "Tenho certeza que ele está mais assustado do que feliz em seu último mês morando aqui.",
  ui_story_5043_50431501_191_dialog_content = "... Hum?",
  ui_story_5043_50431501_192_dialog_content = "Hã...",
  ui_story_5043_50431501_193_dialog_content = "Por que você está se escondendo aí, Toto? Venha aqui!",
  ui_story_5043_50431501_194_dialog_content = "V-Vocês estão todos aqui...",
  ui_story_5043_50431501_X194_dialog_content = "Você trocou de roupa!?",
  ui_story_5043_50431501_X195_dialog_content = "Você parece tão refinado, combina perfeitamente com o resto de Lumopolis!",
  ui_story_5043_50431501_X196_dialog_content = "Certo... Afinal, hoje é um dia importante, então quis me vestir para a ocasião.",
  ui_story_5043_50431501_195_dialog_content = "Na verdade, vim me despedir também.",
  ui_story_5043_50431501_196_dialog_content = "Então você planeja pegar a estrada de novo, hein?",
  ui_story_5043_50431501_197_dialog_content = "Th-Isso mesmo, mas não da maneira que você pode estar pensando.",
  ui_story_5043_50431501_198_dialog_content = "Meus últimos dias em Lumopolis foram cheios de perigo e terror.",
  ui_story_5043_50431501_199_dialog_content = "Mas também foram alguns dos dias mais felizes da minha vida.",
  ui_story_5043_50431501_200_dialog_content = "Isso é porque eu conheci todos vocês.",
  ui_story_5043_50431501_201_dialog_content = "E-Especialmente você, Tina.",
  ui_story_5043_50431501_202_dialog_content = "Obrigado, Totó.",
  ui_story_5043_50431501_203_dialog_content = "V-Você foi o primeiro auroriano a me mostrar bondade incondicional.",
  ui_story_5043_50431501_204_dialog_content = "I-É algo que vou amar para o resto da minha vida.",
  ui_story_5043_50431501_205_dialog_content = "(bondade incondicional, hein...)",
  ui_story_5043_50431501_206_dialog_content = "(Eu sei como ele se sente. Realmente é algo precioso.)",
  ui_story_5043_50431501_207_dialog_content = "... Boa sorte em suas viagens, Toto.",
  ui_story_5043_50431501_208_dialog_content = "Espero que tenhamos a chance de nos encontrar novamente algum dia, meu amigo.",
  ui_story_5043_50431501_209_dialog_content = "Oh espere! Antes de ir, tenho algo que sempre quis lhe dar.",
  ui_story_5043_50431501_210_dialog_content = "Aqui, é uma fornada de biscoitos recém-assados. A estrada à sua frente será longa, com certeza. Espero que isso torne sua jornada um pouco mais fácil!",
  ui_story_5043_50431501_211_dialog_content = "Sniff... O-Obrigado... Muito obrigado, Tina...",
  ui_story_5043_50431501_212_dialog_content = "Vou valorizar cada um deles!!!",
  ui_story_5043_50431501_213_dialog_content = "Hahahaha! Só não os valorize muito, ok? Eles são feitos para comer, afinal!",
  ui_story_5043_50431501_214_dialog_content = "Você deveria ir agora.",
  ui_story_5043_50431501_215_dialog_content = "O sol pode nunca se pôr em Lumopolis, mas esse não é necessariamente o caso no resto do mundo.",
  ui_story_5043_50431501_216_dialog_content = "R-Certo, então... já vou indo!",
  ui_story_5043_50431501_217_dialog_content = "Adeus a todos!!!",
  ui_story_5043_50431501_218_dialog_content = "Adeus, Totó!!!",
  ui_story_5043_50431501_219_dialog_content = "E assim, nosso pequeno herói parte mais uma vez! ♪",
  ui_story_5043_50431501_220_dialog_content = "Mas desta vez, ele sai com um presente de seus amigos! ♪",
  ui_story_5043_50431501_221_dialog_content = "O cheiro de guloseimas assadas flutua atrás dele quando ele sai ♪",
  ui_story_5043_50431501_222_dialog_content = "E nos céus de Lumopolis na brisa da manhã! ♪"
}
return config
